    ["dash_mod_resources"]       = "Risorse",
    ["dash_mod_cdm"]             = "Cooldown Manager",
    ["dash_mod_abskin"]          = "Skin barre delle azioni",
    ["dash_mod_chatskin"]        = "Skin della chat",
    ["dash_mod_bagskin"]         = "Skin delle borse",
    ["dash_mod_mtracker"]        = "Tracker Mythic+",
    ["dash_mod_score"]           = "Punteggio Mythic+",
    ["dash_reload_popup"]        = "Ricaricare l'interfaccia ora per applicare le tue modifiche?",

    -- ═══════════════════════════════════
    -- MythicTracker Nomi EJ (2.9.10)
    -- ═══════════════════════════════════
    -- ═══════════════════════════════════
    -- Correzione CD PartyFrame + Prestazioni (2.9.12)
    -- ═══════════════════════════════════
    -- ═══════════════════════════════════
    -- Installer Overhaul & AB Toggle (2.9.17)
    -- ═══════════════════════════════════
    -- Objective Tracker Quest Buckets (2.9.18)
    -- ═══════════════════════════════════
    -- Smart Waypoint (2.9.20)
    -- ═══════════════════════════════════
    ["wn_2920_waypoint_redirect"]       = "Smart Waypoint — cross-zone redirect: the waypoint now tracks the next path step on your current map (portal, dungeon entrance) via C_SuperTrack.GetNextWaypointForMap(), updated on SUPER_TRACKING_PATH_UPDATED and zone changes.",
    ["wn_2920_waypoint_blob"]           = "Smart Waypoint — stuck 0 m fix: the beacon now hides automatically when the player is inside the quest objective area (C_Minimap.IsInsideQuestBlob), preventing the waypoint from freezing at 0 m.",
    ["wn_2920_waypoint_label"]          = "Smart Waypoint — dynamic label: the destination now shows the redirect step description (e.g. 'Travel to Durotar') or the tracked quest title instead of a blank field.",
    -- Objective Tracker Stability (2.9.19)
    -- ═══════════════════════════════════
    ["wn_2919_antiflicker"]             = "Anti-flicker — eliminated the visible 'trembling' of the Objective Tracker caused by a feedback loop between TomoMod's bucket layout and Blizzard's native Update / MarkDirty hooks. New re-entry guard, deferred pump coalescing, and a 0.20 s post-layout silence window break the recursion.",
    ["wn_2919_collapsed_persist"]       = "Collapsed bucket persistence — quest blocks under a collapsed bucket header no longer reappear when Blizzard re-runs its layout; each block gets a one-time Show hook that re-hides it while its bucket is folded.",
    ["wn_2919_header_detection"]        = "Module header detection — accent- and case-insensitive matching (Métier / métier / MÉTIER all resolve to the same keyword) and added singular variants. Quest titles and objective lines are now explicitly excluded so the full quest description is never accidentally hidden.",
    ["wn_2919_recipe_height"]           = "Recipe block height — Profession recipe blocks no longer overlap the next quest. The deepest-descendant measurement now runs unconditionally and walks 8 levels deep to reach reagent FontStrings (TrackedRecipe → Lines → Line[i]).",
    ["wn_2919_reward_preview"]          = "Reward preview exclusion — Delves (e.g. 'La Sombrevoie'), M+ scenarios, world quest reward popups and weekly vault reward blocks (e.g. 'Halte de l'Ombre-Garde' with ilvl preview) are now skipped from the bucket system. They stay in Blizzard's native location and no longer overlap our quests.",
    ["wn_2918_buckets"]                 = "Objective Tracker quest buckets — quests, world quests, weeklies, dailies, dungeons, raids, professions and achievements are now grouped into collapsible categories with colored headers and live count badges.",
    ["wn_2918_bucket_toggle"]           = "New 'Group quests into collapsible categories' checkbox in Config → Skins → Objective Tracker; disabling it instantly restores Blizzard's native module layout, no /reload required.",
    ["wn_2918_tracker_width"]           = "Tracker panel widened by 10 px so quest item icons no longer clip against the right edge.",
    ["wn_2918_layout_fix"]              = "Re-parented quest blocks now anchor both TOPLEFT and TOPRIGHT to prevent width collapse, and stale heights after collapse/expand are corrected via multi-pass layout.",

    ["wn_2917_ab_master_toggle"]        = "Action Bar master toggle — a new checkbox lets you fully disable bar management; after /reload, Blizzard's default action bars are fully restored.",
    ["wn_2917_installer_raid"]          = "Installer step 5 — Raid Frames: enable/disable, hide Blizzard frames, dispel highlights, HoT tracking, debuff and defensive icons, grid/list layout.",
    ["wn_2917_installer_coverage"]      = "Installer expanded — Skins step adds Objective Tracker, Mail, Reputation Bar; QOL step adds Auto Summon, Auto Quest, Class Reminder, Leveling Bar, Waypoint, World Quests, Frame Anchors, Profession Helper.",
    ["wn_2917_chat_skin_fix"]           = "Chat Skin fix — installer wrote to orphan key instead of the actual chatFrameSkin key.",
    ["wn_2917_talking_head_fix"]        = "HideTalkingHead fix — module now checks its DB toggle before suppressing the TalkingHead frame.",
    ["wn_2917_minimal_style"]           = "Action Bar Minimal style — the 5th skin style was missing from the Installer dropdown; now selectable.",

    -- AuctionRecipeTracker (2.9.15)
    -- ═══════════════════════════════════
    ["wn_2916_layout_fix"]              = "Errore silenzioso del pulsante Layout corretto — su un'installazione nuova, fare clic su 'Layout' non faceva nulla perché il sistema dei mover non completava l'inizializzazione. Toggle ora si inizializza in modo posticipato tramite pcall e mostra eventuali errori in chat invece di fallire silenziosamente.",
    ["wn_2916_safe_init"]               = "Rinforzo della catena di init dei moduli — ogni chiamata Initialize() dei moduli TomoMod è ora racchiusa in xpcall tramite un helper safeInit; un modulo difettoso non blocca più i ~45 moduli che si inizializzano dopo di esso, e il modulo colpevole viene segnalato in chat.",
    ["wn_2916_art_total"]               = "AuctionRecipeTracker — ogni intestazione di ricetta seguita mostra ora il costo totale globale dei suoi reagenti sulla destra; se almeno un reagente non ha un prezzo registrato, un (~) grigio indica che il totale è una stima parziale.",
    ["wn_2916_avr_gui"]                 = "GUI Auto Vendita / Riparazione — due nuove caselle in Config → QOL → Automazioni permettono di attivare in modo indipendente la riparazione automatica dal mercante e la vendita automatica degli oggetti grigi (scarsi); le impostazioni sono persistite in TomoModDB e si applicano dal vivo senza /reload.",
    ["wn_2915_art_module"]              = "Nuovo modulo QOL — AuctionRecipeTracker: una GUI si apre automaticamente dal banditore quando è seguita almeno una ricetta di professione; le righe mostrano '14x icona Nome oggetto prezzo', clic per cercare alla CdA e un pulsante di scansione completa manuale.",
    ["wn_2915_art_tooltip"]             = "Riga TomoHDV nei tooltip — dopo una scansione, ogni oggetto (zaini, banca, link in chat, equipaggiamento) mostra il prezzo unitario registrato, più il prezzo totale della pila se stack > 1, e da quanto tempo è stata fatta la scansione.",
    ["wn_2915_art_scrollbar"]           = "Barra di scorrimento moderna TomoMod — sostituisce la barra di Blizzard predefinita con una traccia sottile da 4 px e un pollice color accento dimensionato proporzionalmente al contenuto; supporta drag, clic sulla traccia per saltare, rotellina del mouse, e si nasconde automaticamente quando il contenuto entra nella finestra.",
    ["wn_2915_art_anchor"]              = "Ancoraggio predefinito di AuctionRecipeTracker — la finestra si attacca al bordo destro della finestra della CdA (TOPLEFT, AuctionHouseFrame, TOPRIGHT, 8, 0); le posizioni personalizzate tramite drag rimangono salvate e hanno la priorità.",
    ["wn_2915_art_scan_fix"]            = "Affidabilità del pulsante di scansione — OnShow ora reimposta scanInProgress, riabilita il pulsante e ripristina la sua etichetta; i ritorni anticipati silenziosi (scansione in corso, CdA chiusa, API mancante) ora mostrano un messaggio rosso invece di non fare nulla.",

    -- ═══════════════════════════════════
    -- MythicTracker Boss Names Fix (2.9.13)
    -- ═══════════════════════════════════
    ["wn_2913_boss_names"]               = "MythicTracker: i nomi dei boss ora vengono visualizzati correttamente invece di \"Boss 1\", \"Boss 2\" ecc. — in WoW 12.x il campo dei criteri dello scenario è stato rinominato da criteriaString a description; TomoMod ora legge description per primo con criteriaString come fallback.",
    ["wn_2913_boss_checkmark"]           = "MythicTracker: il prefisso del segno di spunta di Blizzard (aggiunto agli obiettivi boss completati in 12.x) viene ora rimosso prima della visualizzazione.",
    ["wn_2913_ej_pcall"]                 = "MythicTracker: la chiamata EncounterJournal_OpenJournal in FetchEJBossNames è ora racchiusa in pcall per prevenire un potenziale taint in 12.x.",

    ["wn_2912_party_cd_fix"]             = "PartyFrame: il tracciamento dei CD di interrupt e resurrezione da combattimento ora usa UNIT_SPELLCAST_SUCCEEDED con risoluzione spellID sicura (string.format); COMBAT_LOG_EVENT_UNFILTERED rimosso — registrarlo da un addon causa taint in 12.x.",
    ["wn_2912_healer_interrupt"]         = "PartyFrame: l'icona del tracker di interrupt è ora nascosta per i guaritori — dalla patch 12.x i guaritori non hanno più un'abilità di interrupt.",
    ["wn_2912_perf_cdm"]                 = "CooldownManager: UpdateButtonState ora memorizza nella cache GetCooldownTimes, GetCachedCooldownID e GetCooldownViewerCooldownInfo una sola volta per bottone per tick invece di due; ~50% in meno di chiamate API nel ciclo principale.",
    ["wn_2912_perf_aura"]                = "AuraTracker: frequenza di aggiornamento ridotta da 10 fps (0,1 s) a 5 fps (0,2 s); nessuna differenza visibile, overhead del ticker dimezzato.",
    ["wn_2912_perf_resbars"]             = "ResourceBars: soglia OnUpdate per rune DK / stagger Monaco aumentata da 50 ms a 100 ms; frequenza di esecuzione dimezzata senza impatto percepibile sulla visualizzazione.",

    -- ═══════════════════════════════════
    -- Correzioni CooldownManager / ProcGlow / BuffSkin (2.9.11)
    -- ═══════════════════════════════════
    ["wn_2911_cdm_hooks"]                = "CooldownManager: colori swipe e nascondimento GCD unificati in un singolo hook per bottone; il rilevamento GCD usa ora la cache dello Scanner invece di pcall(C_CooldownViewer).",
    ["wn_2911_procglow_fixes"]           = "CDMProcGlow: il glow viene applicato in modo sincrono in ShowAlert per evitare una race condition con HideAlert nello stesso frame; timer per frame sostituiti da un unico ticker globale di persistenza; RefreshAll ora filtra correttamente i proc attivi.",
    ["wn_2911_buffskin_fixes"]           = "BuffSkin: SkinButton riapplica le ancore e le maschere delle icone sui frame riciclati da Blizzard; hooks installati una sola volta tramite hooksInstalled (attivare/disattivare ora funziona correttamente); TemporaryEnchantFrame agganciato per gli aggiornamenti degli incantamenti; hooks installati immediatamente.",

    -- ═══════════════════════════════════
    -- MythicTracker Nomi EJ (2.9.10)
    -- ═══════════════════════════════════
    ["wn_2910_ej_boss_names"]            = "MythicTracker: i nomi dei boss vengono ora risolti tramite il Diario degli incontri — localizzati, compatibili con caratteri speciali, coprendo tutti i dungeon da Cata a The War Within.",
    ["wn_2910_ej_fallback"]              = "MythicTracker: risoluzione del nome a 3 livelli — dungeonEncounterID > indice EJ > criteriaString filtrato come fallback, con retry automatico (×5) se il EJ non è ancora caricato.",

    -- Player Auras Mover (v2.9.5)
    ["mover_player_auras"]       = "Aure del giocatore",
    ["opt_auras_spacing"]        = "Spaziatura tra icone",
    ["btn_reset_aura_position"]  = "Reimposta posizione aure",

    -- Module Reload Safety (v2.9.21)
    ["msg_module_reload"]        = "Questa modifica richiede un ricaricamento dell'interfaccia.\nRicaricare ora?",
    ["info_module_reload"]       = "Richiede /reload per avere effetto.",
    ["wn_2921_aura_mover"]       = "Le aure del giocatore hanno ora un proprio mover nella modalità Layout (overlay colorato, etichetta, drag & drop indipendente).",
    ["wn_2921_aura_gui"]         = "Nuovo cursore per la spaziatura delle aure e pulsante di reset posizione nella scheda Aure della configurazione.",
    ["wn_2921_reload_safety"]    = "Attivare/disattivare un modulo principale (UnitFrames, Nameplates, Castbars, ActionBars, Party, Raid) propone ora un /reload automatico.",

    -- Waypoint Arrow Reversed (v2.9.22)
    ["wn_2922_waypoint_arrow"]    = "La freccia del navigatore fuori schermo del waypoint è ora sul lato opposto dell'orbita: quando l'obiettivo è davanti, la freccia appare in basso e punta verso l'alto.",

    -- 3.0.3
    -- 3.0.4
    ["wn_304_consumable_bar"]    = "ConsumableBar — nuovo modulo QOL che mostra le icone del Fiasco e Ben Nutrito con timer a conto alla rovescia. Completamente configurabile (dimensione, spazio, orientamento, posizione timer) e spostabile in Modalità Layout.",
    ["wn_304_cursor_textures"]   = "Anello del cursore — due nuove texture aggiunte (Cygle e Cuore). Selettore texture disponibile in Generale → Anello del cursore.",
    ["wn_304_mythichub_tp"]      = "Teletrasporto MythicHub corretto — nessun taint (ADDON_ACTION_FORBIDDEN) o errore di ancoraggio quando si clicca sulle righe dungeon. ID degli incantesimi per Maisara Caverns e Windrunner Spire corretti.",

    -- 3.0.3
    ["wn_303_tracking_panel"]    = "Pannello di tracciamento personalizzato — cliccare il pulsante di tracciamento apre ora un pannello in stile TomoMod a sinistra della minimappa al posto del menu a tendina nativo di Blizzard.",
    ["wn_303_collector_panel"]   = "Redesign del pannello raccoglitore — i pulsanti degli addon vengono raggruppati in un pannello TomoMod (sfondo scuro, titolo verde acqua, bordo del colore della classe) ancorato a sinistra della minimappa.",
    ["wn_303_collector_autoclose"] = "Il raccoglitore si chiude automaticamente dopo 0,5 s dal login/ricaricamento una volta catturati i pulsanti — si riapre normalmente al clic.",
    ["wn_303_tooltip_fix"]       = "Correzione skin tooltip — risolto il grande rettangolo nero che appariva passando il mouse su unità o magie.",
    ["wn_303_coords_pos"]        = "Le coordinate della minimappa sono state spostate in basso al centro per una migliore leggibilità.",

    -- 3.0.0
    ["wn_300_installer"]  = "Assistente di configurazione tutto nuovo — preset prima: scegli Consigliato, Tank, Curatore, DPS, Minimale o Personalizzato e sei pronto in pochi secondi.",
    ["wn_300_presets"]    = "Preset di configurazione — un clic applica una configurazione coerente e ottimizzata per il ruolo su tutti i moduli; riutilizzabile in qualsiasi momento da /tm.",
    ["wn_300_dashboard"]  = "Nuovo pannello Home in /tm — interruttori rapidi dei moduli, rilancio dell'assistente, applicazione di un preset, cambio profilo e ripristino, tutto in un unico posto.",
    ["wn_300_search"]     = "Barra laterale con ricerca — filtra le categorie per nome o parola chiave (digita 'heal', 'cd', 'bag'…).",
    ["wn_300_locales"]    = "Localizzazione completa di tutti i nuovi testi 3.0 nelle 6 lingue supportate.",

    -- 3.0.5
    ["wn_305_rare_alert"]           = "Allarme Raro — nuovo modulo QOL: riproduce un suono e mostra un banner quando un PNG raro entra nel raggio della minimappa. Clic sinistro: prendere di mira + marcatore teschio + waypoint. Clic destro: chiudere.",

    -- =====================
