    -- =====================
    ["mover_ab_extra"] = "Azione extra",
    ["mover_ab_pet"] = "Barra del famiglio",
    ["mover_ab_stance"] = "Barra delle posture",
    ["section_extra_button"] = "Pulsante azione extra",
    ["opt_extra_enabled"] = "Gestisci il pulsante azione extra (ricarica per rilasciare)",
    ["opt_extra_scale"] = "Scala del pulsante extra",
    ["btn_extra_reset_pos"] = "Reimposta posizione",
    ["info_extra_button"] = "Posiziona il pulsante azione extra in modalità Layout. Appare durante missioni e scontri. Disattivandolo viene restituito a Blizzard dopo un /reload.",
    ["wn_306_extra_button"] = "Nuovo — il pulsante azione extra ora fa parte del sistema di barre delle azioni di TomoMod.",
    ["wn_306_extra_mover"] = "Nuovo — riposiziona il pulsante azione extra (e il pulsante abilità di zona) in modalità Layout, come qualsiasi altra barra. Posizione e scala vengono salvate nel profilo.",
    ["wn_306_extra_scale"] = "Nuovo — opzioni del pulsante azione extra in Barre delle azioni, scheda Gestione barre: attiva, scala e reimposta posizione.",
    ["wn_306_compass"] = "Correzione — Bussola: corretto un errore Lua frequente (x417) nella conversione delle coordinate mondo (C_Map.GetWorldPosFromMapPos restituisce continentID + worldPosition; il continentID viene ora correttamente scartato).",
    ["wn_306_bagskin"] = "BagSkin — gli slot ora usano ContainerFrameItemButtonTemplate di Blizzard: clic, uso, raccolta e divisione sono gestiti da codice sicuro nativo (nessun PreClick soggetto a taint). Gli slot rimandati in combattimento vengono riprodotti automaticamente alla fine del combattimento.",
    -- 3.0.7
    ["wn_307_objective_tracker"] = "Tracker obiettivi — I blocchi delle missioni mondo vengono ora inseriti nel bucket Missioni Mondo invece di fluttuare sopra il tracker. Le barre di avanzamento (forze nemiche, % settimanale) sono nascoste quando il bucket è compresso.",
    ["wn_307_guardian_rage"]     = "Barre risorse — I Druidi Guardiano vedono ora la barra Rabbia centrata sullo schermo per impostazione predefinita. Il Mana rimane come barra secondaria. La barra potere nel riquadro unità viene nascosta automaticamente.",
    ["wn_307_resource_bars"]     = "Barre risorse — Corretto: i cursori altezza per potere di classe e mana druido ora si applicano correttamente (conflitto di nome frame globale risolto). Nuovo cursore per l'altezza della barra centrale. Nuova casella in Riquadri unità › Giocatore › Dimensioni.",
    ["wn_310_brez_counter"]       = "Contatore Battle Rez — Nuovo HUD spostabile che mostra quante resurrezioni da combattimento sono disponibili e il tempo alla prossima carica. Legge il pool condiviso, funziona su qualsiasi classe. Configurabile in Riquadri raid → Funzionalità.",
    ["wn_310_resurrect"]          = "Indicatore di resurrezione — Un'icona rez appare ora su un membro del gruppo o del raid mentre una resurrezione viene lanciata su di lui.",
    ["wn_310_raid_sizes"]         = "Riquadri raid — Nuovi layout opzionali per dimensione (10 / 25 / 40): larghezza e altezza dei riquadri si adattano automaticamente alle dimensioni del gruppo attuale. Configurabile in Riquadri raid → Funzionalità.",
    ["wn_310_brez_fix"]           = "Riquadri gruppo — Corretto: il tracker cooldown resurrezione da combattimento mostra ora correttamente l'icona desaturata e il timer di ricarica quando un brez viene consumato da qualcuno nell'istanza.",

    -- 3.1.1
    ["art_searching"]        = "Ricerca: %s",
    ["art_searching_qty"]    = "Ricerca: %s × %d",
    ["wn_311_icicles"]        = "Mago del Ghiaccio: nuovo tracker Ghiaccioli nella barra delle risorse (5 segmenti + bagliore Picco Glaciale al massimo). Colore personalizzabile in CD & Risorse → Colori.",
    ["wn_311_taint_money"]   = "Corretto un errore di taint (Midnight): passare il mouse sugli oggetti nel Diario delle spedizioni non genera più l'errore 'secret number' sul valore in oro — TomoMod non contamina più i tooltip di confronto.",
    ["wn_311_art_qty"]       = "AuctionRecipeTracker: cliccare su un reagente cerca l'oggetto nella Casa d'aste e mostra la quantità richiesta nella barra di stato (es. Ricerca: Fuoco Risvegliato × 14).",

    -- 3.1.2
    ["wn_312_brand"]         = "Colore accento aggiornato da #0cd29f a #2ed884 (verde menta) in tutta l'interfaccia — barra del titolo, pannelli, messaggi chat, popup e valori colore predefiniti.",
    ["wn_312_brand_api"]     = "Nuove costanti TomoMod_Utils.BRAND / BRAND_DARK / BRAND_HOVER centralizzano il colore accento: i pannelli di configurazione e il tema Widget leggono ora da un'unica fonte.",
    ["wn_312_companion_fix"] = "CompanionStatus: corretta una perdita di variabile globale (UpdateIcon era dichiarata senza 'local').",

    -- 3.1.3
    ["wn_313_nav"]        = "Interfaccia di configurazione riprogettata: 16 pannelli raggruppati in 6 categorie (Interfaccia, Unità, Combattimento, Comfort, Strumenti), ciascuna con colore accento e intestazione dedicati.",
    ["wn_313_accent"]     = "I widget ora adottano automaticamente il colore accento del pannello ospitante — schede, intestazioni, separatori, caselle di controllo, pulsanti e tab si adattano al contesto di categoria attivo.",
    ["wn_313_segmented"]  = "Nuovo widget SegmentedControl sostituisce i menu a tendina brevi (Barra zaini, Micro Menu, Stile chat, Layout zaini, Ordinamento, Canale audio).",
    ["wn_313_dashboard"]  = "Dashboard Accueil completamente rinnovata: banner hero con stato diagnostica in tempo reale, scorciatoie rapide (Programma di installazione, Profili, Diagnostica, Ricarica) e toggle moduli ridisegnati.",
    ["wn_313_np_preview"] = "Nameplate: nuovo pannello di anteprima live in cima alla configurazione — mostra alleato, ostile e boss, si aggiorna in tempo reale al variare di larghezza, altezza, barra di cast e dimensione font.",
    ["wn_313_loot_filter"] = "Correzione filtro classe bottino: gli oggetti assenti dall'IDB (es. drop di nuovi raid) ora usano il tipo d'armatura come fallback invece di essere mostrati a tutte le classi.",
    ["wn_313_sporefall"]   = "Dati bottino: raid Sporefall (ejEncounterID 2711) aggiunto con 15 oggetti dal dataset KeystoneLoot build 12.0.7.",
    ["wn_313_diag"]       = "Diagnostica: 7 nuove parole chiave di esclusione UIError (commerciante, cavalcatura, inventario, eliminazione, potenziamento, aspetto, duello) + la console ora appare sempre sopra il menu di configurazione.",
    ["wn_313_tooltip_anchor"] = "Posizione del tooltip: nuovo sistema di ancoraggio a 4 modalità — Predefinito, Cursore (segue il mouse), Angolo (fisso su un angolo dello schermo) e Personalizzato (cornice trascinabile).",

