    ["preview_np_boss"]    = "Boss segnalato",

    -- 3.1.4
    ["wn_314_tooltip_anchor"] = "Posizione del tooltip: nuovo sistema a 4 modalità — Predefinito, Cursore (segue il mouse), Angolo (angolo dello schermo) e Personalizzato (cornice trascinabile). Configurabile in Skins → Tooltip.",
    ["wn_314_locale_fix"]     = "Corrette le etichette di colore del tooltip mancanti: i selettori di colore sfondo e bordo in Skins → Tooltip ora vengono visualizzati correttamente.",

    -- 3.1.5
    ["wn_315_ot_itembutton"] = "Tracker Obiettivi: i pulsanti degli oggetti delle missioni ora si nascondono correttamente quando il loro bucket viene compresso (il pulsante è figlio del tracker nativo, non del blocco — in precedenza rimaneva visibile sopra i bucket compressi).",
    ["wn_315_talkinghead"] = "QOL: l'opzione «Nascondi Talking Head» è tornata nella GUI di configurazione (QOL → Automazioni). Ora si applica immediatamente senza /reload ed è reversibile — deselezionandola si ripristinano i dialoghi a scorrimento.",

    -- 3.1.6
    ["wn_316_party_combat"] = "Frame di gruppo: risolti bug di visibilità quando un membro entra, esce, o il gruppo si converte in raid durante il combattimento — i frame ora si mostrano/nascondono in modo affidabile in ogni situazione.",
    ["wn_316_raid_combat"] = "Frame di raid: risolto il problema dei frame che restavano bloccati visibili o nascosti quando i membri del raid entravano o uscivano durante il combattimento — la visibilità è ora gestita da un sistema sicuro e compatibile col combattimento.",
    ["wn_316_roster_repaint"] = "Frame di gruppo e raid: risolte informazioni obsolete (colore classe, assorbimenti, evidenziazione dispel) che mostravano brevemente il giocatore sbagliato dopo un cambio di composizione, anche in combattimento.",
    ["wn_317_cdm_holders"] = "Cooldown Manager: nuovo sistema di 'Holders' — sposta e blocca liberamente ogni visualizzatore di cooldown (Essenziale, Utilità, Icone buff, Barre buff) indipendentemente dalla griglia della Modalità Modifica di Blizzard, con anteprima live di icone/barre quando sono vuoti.",
    ["wn_317_resourcebars_health"] = "Barre delle risorse: nuova barra della vita opzionale — altezza configurabile, formato (%, valore o entrambi), riempimento colorato per classe, animazione fluida e una soglia di colore per vita bassa.",
    ["wn_317_config_cards"] = "Interfaccia di configurazione: il pannello Cooldown & Risorse ha ora un layout a schede (cards) e una nuova scheda Barre che raggruppa tutte le impostazioni della barra della vita.",
    ["wn_316_locale_cdm"] = "Risolto: la scheda Barre, le card di posizionamento/anteprima live e la sezione barra della vita & animazioni mostravano chiavi grezze invece del testo tradotto — tradotto in tutte le 6 lingue.",
    ["wn_316_taint_chat"] = "Risolto un errore di taint ('secret string value') nello skin della chat durante la ricezione di messaggi di canale.",
    ["wn_316_taint_skyride"] = "Risolto un errore di taint ('secret number value') nella barra di velocità dello Skyriding, causato dai valori protetti di velocità di volo/planata del gioco.",
    ["wn_316_durability_pos"] = "Minimappa: la posizione del testo di durabilità è ora configurabile (angolo + offset X/Y) in Interfaccia → Generale → Info Panel — utile per evitare la sovrapposizione con il nuovo pulsante di espansione della patch 12.0.7.",

    -- 3.1.7
    ["wn_317_libserialize_namespace"] = "Profili: la libreria LibSerialize incorporata ora usa uno spazio dei nomi privato ('TomoSerialize-1.0') invece del nome condiviso 'LibSerialize', evitando conflitti di esportazione/importazione con altri addon che incorporano anch'essi LibSerialize.",
    ["wn_317_drag_absolute_coords"] = "Frame mobili: risolto un problema per cui le posizioni salvate si spostavano o si invertivano dopo il trascinamento su Leveling Bar, Movers, AuctionRecipeTracker, Mythic+ Tracker, TomoScore, Frame Anchors, Bag Skin, le barre di lancio, le ancore dei frame di gruppo/raid, la Bussola, la Barra dei consumabili, il Loot Browser, la Minimappa, il Tracker Obiettivi, la barra Skyriding, le Barre delle risorse e gli UnitFrames — le posizioni ora vengono salvate come coordinate assolute dello schermo, stabili.",
    ["wn_317_ot_combat_taint"] = "Tracker Obiettivi: risolto un possibile errore di taint quando Blizzard mostra nuovamente un blocco bucket di missione compresso durante un aggiornamento missione in combattimento.",
    ["wn_317_deadcode_cleanup"] = "Pulizia interna: rimossi diversi moduli inutilizzati/disattivati per ridurre le dimensioni dell'addon — nessuna funzionalità visibile all'utente è stata interessata.",
    ["wn_317_raidmanager_fix"] = "Riquadri incursione: risolto un problema per cui il pannello predefinito del capogruppo di Blizzard (ready check, indicatori bersaglio incursione, converti in incursione, limite ping, abbandona gruppo) veniva nascosto insieme ai riquadri incursione quando è attiva l'opzione «Nascondi riquadri incursione di Blizzard» — ora viene soppresso solo il contenitore dei riquadri dei membri, la barra degli strumenti del capogruppo resta disponibile.",
    ["wn_317_groupmanager_skin"] = "Riquadri incursione: l'opzione «Personalizza il pannello del capogruppo» ora applica un restyling completo alla barra degli strumenti di Blizzard con il tema scuro/verde menta di TomoMod — menu a tendina di modalità e limite ping, filtri ruolo/gruppo, pulsanti della barra degli strumenti (modalità modifica, impostazioni, ready check, sondaggio ruolo, conto alla rovescia), pulsanti dei marcatori di incursione con le relative schede Unità/Terra, e pulsanti abbandona gruppo in stile rosso — il tutto senza alterare alcuna icona di Blizzard, con attivazione/disattivazione live senza ricaricare l'interfaccia.",
    ["wn_317_groupmanager_collapsetab"] = "Riquadri incursione: risolto un problema per cui il pulsante di riduzione del pannello del capogruppo lasciava una striscia residua sul bordo dello schermo, sostituito ora da un'apposita linguetta verde menta invece di un semplice pulsante personalizzato.",

    -- 3.1.8
    ["wn_318_bagskin_itemclass_enum"] = "Bag Skin: la corrispondenza delle categorie ora usa le costanti Enum.ItemClass di Blizzard (con fallback numerico) invece di numeri di classe oggetto codificati, mantenendo la categorizzazione corretta su ogni client.",
    ["wn_318_bagskin_cat_order"] = "Bag Skin: ordine predefinito delle categorie aggiornato — gli Oggetti missione ora sono raggruppati subito dopo l'Equipaggiamento, prima di Consumabili e Materiali.",
    ["wn_318_bagskin_cat_foundation"] = "Bag Skin: aggiunte le basi interne per una futura opzione di nascondere/riordinare le categorie — Varie e Slot liberi restano sempre visibili così nessun oggetto può mai sparire.",

    -- 3.1.9
    ["wn_3110_actionbar_spelldrag"] = "Barre azione: la correzione degli slot vuoti della 3.1.9 non funzionava ancora per un incantesimo, una macro o una cavalcatura già presente su una barra (con «Mostra slot vuoti» disattivato) — spostarlo su uno slot vuoto ora funziona durante qualsiasi trascinamento, senza aprire il Libro degli incantesimi/Talenti.",
    ["wn_3110_skyride_taint"] = "Skyriding: risolto un errore di corruzione ricorrente sulla visualizzazione della velocità a terra, che poteva ancora verificarsi centinaia di volte per sessione nonostante una correzione precedente — il calcolo della velocità è ora rafforzato con una protezione aggiuntiva così da non poter più generare un errore.",
    ["wn_3110_diag_exclusions"] = "Diagnostica: aggiunte due nuove parole chiave di esclusione (mercante che rifiuta di acquistare un oggetto, raccolta del bottino bloccata mentre la modalità Sfida è attiva) così questi normali messaggi di gioco non vengono più registrati come bug.",
    ["wn_319_actionbar_dragfix"] = "Barre azione: risolto un problema per cui non era possibile trascinare un incantesimo su uno slot vuoto (con «Mostra slot vuoti» disattivato) a meno che il Libro degli incantesimi/Talenti non fosse aperto — gli slot vuoti ora si rivelano durante qualsiasi trascinamento.",
    ["wn_319_ot_mover_fix"] = "Tracker Obiettivi: risolto un problema per cui la posizione dell'ancoraggio si reimpostava da sola (la Modalità Modifica di Blizzard poteva sovrascriverla silenziosamente) — trascinarlo ora rimane affidabile.",
    ["wn_319_ot_quest_limit"] = "Tracker Obiettivi: risolto il cursore «Numero massimo di missioni mostrate» che non aveva alcun effetto nel layout predefinito a Categorie.",
    ["wn_319_minimap_drift"] = "Minimappa: risolto un problema per cui la minimappa si spostava da sola dopo un /reload (un errore di calcolo della scala applicava due volte il fattore di scala alla posizione salvata).",
    ["wn_319_minimap_collector"] = "Minimappa: risolto il raccoglitore di pulsanti che continuava a nascondere i pulsanti degli altri addon dopo un reload anche se disattivato.",
    ["wn_319_minimap_tracking"] = "Minimappa: risolto il pulsante di tracciamento che a volte scompariva, e il pulsante di tracciamento nativo di Blizzard che restava non cliccabile dopo essere stato mostrato di nuovo.",
    ["wn_319_repbar_hide"] = "Barra reputazione: risolta la barra di reputazione/onore di Blizzard che a volte restava visibile nonostante l'opzione «Nascondi barra reputazione Blizzard» fosse attiva.",
    ["wn_319_tooltip_bg"] = "Tooltip: sfondo predefinito meno trasparente (opacità 92% → 97%) — ancora regolabile tramite il cursore di opacità dello sfondo.",
    ["wn_319_tooltip_anchor"] = "Tooltip: l'ancoraggio di posizione «Personalizzato» non resta più visibile sullo schermo al di fuori della modalità Layout, ed è stato aggiunto un nuovo pulsante «Mostra/Nascondi l'ancoraggio» in Skins → Tooltip.",
    ["wn_319_diag_copy"] = "Diagnostica: risolto il pulsante «Copy Report» che sembrava non fare nulla — la finestra di esportazione poteva aprirsi nascosta dietro la console.",

    -- 3.1.11
    ["wn_3111_castbar_deathstuck"] = "Barra di lancio: risolto un problema per cui la barra di lancio di bersaglio, focus, boss e altre unità non giocatore restava visibile bloccata sullo schermo se l'unità moriva o scompariva senza che venisse mai generato un evento di fine lancio corrispondente.",
    ["wn_3111_castbar_targetreset"] = "Barra di lancio: cambiare bersaglio o focus ora reimposta completamente la barra di lancio invece di cancellare solo il timer di fallimento, impedendo che un lancio residuo dell'unità precedente resti visualizzato su quella appena selezionata.",
    ["wn_3111_ot_lfgbutton"] = "Tracker Obiettivi: comprimere una categoria di missioni ora nasconde anche il suo pulsante «Cerca gruppo», non solo il pulsante oggetto — entrambi vengono ripristinati correttamente quando la categoria viene espansa di nuovo.",
    ["wn_3112_score_taint"] = "Classifica Mitica+: corretta una serie di errori di corruzione (taint) che potevano impedire alla classifica di fine dungeon di visualizzarsi/posizionarsi correttamente se il giocatore era ancora in combattimento proprio mentre il dungeon veniva completato.",
    ["wn_3112_config_resize"] = "Finestra di configurazione: la finestra /tm ora può essere ridimensionata trascinando l'angolo in basso a destra e scalata con un nuovo slider 70-130% in Generale — dimensione predefinita aumentata a 1240x820, con un pulsante per ripristinare entrambi con un clic.",
    -- =====================
