    ["info_skyride_ground_speed"]     = "Mostra anche la tua velocità di movimento al suolo (gli indicatori di volo restano nascosti quando non stai volando).",
    ["btn_class_reminder_preview"]    = "Anteprima",
    ["sublabel_class_reminder_coverage"] = "— Buff e forme monitorati —",
    ["opt_char_skin_movable"]         = "Finestra spostabile",
    ["info_char_skin_movable"]        = "Una volta attivato, trascina la finestra Personaggio per spostarla. La sua posizione viene memorizzata.",
    ["btn_char_skin_reset_pos"]       = "Ripristina posizione",
    ["btn_sound_test"]                = "▶ Riproduci questo suono",
    ["opt_auras_max_width"]           = "Larghezza massima (a capo)",
    ["opt_auras_per_row"]             = "Icone per riga",

    -- 3.2.0
    ["wn_320_gsearch"] = "Finestra di configurazione: la ricerca nella barra laterale ora è globale — trova le opzioni corrispondenti in tutte le categorie e schede, non solo nella pagina visibile, e cliccando su un risultato si salta direttamente ad esso con un lampeggio di evidenziazione.",
    ["wn_320_panelcache"] = "Finestra di configurazione: il passaggio tra le schede di categoria ora è istantaneo dopo la prima visita — i pannelli vengono memorizzati nella cache invece di essere ricostruiti ogni volta.",
    ["wn_320_configlocale"] = "Finestra di configurazione: tutte le etichette in francese rimaste codificate fisse nei pannelli delle impostazioni sono ora completamente traducibili.",
    ["cfg_tab_cdforge"]           = "Cooldowns",

    -- 3.2.1
    ["wn_321_cdf_intro"] = "Nuovo — CooldownForge: crea barre di cooldown personalizzate per classe, tracciando incantesimi, oggetti, preset (pozioni, pietra di guarigione...), monili o la tua abilità razziale, dalla nuova scheda Cooldowns (categoria Combattimento).",
    ["wn_321_cdf_movers_io"] = "Le barre CooldownForge ora possono essere trascinate tramite il gestore di spostamento unificato, e condivise tra personaggi con una stringa di importazione/esportazione per classe.",

    -- 3.2.2
    ["wn_322_studio_intro"] = "Nuovo — Cooldown Studio: un editor a schermo intero dedicato alle barre di CooldownForge, con schede per barra Layout/Stile/Incantesimi/Visibilità/Condivisione, accessibile dalla scheda Cooldowns.",
    ["wn_322_studio_fix"] = "Cooldown Studio: risolto il problema per cui la finestra non veniva sempre visualizzata sopra le altre finestre, e i suoi widget non ereditavano sempre il colore di accento corretto.",
    ["wn_322_studio_visibility"] = "Cooldown Studio: aggiunta la visibilità condizionale per barra — mostra o nascondi una barra in base allo stato di combattimento, istanza, gruppo o raid, tramite semplici menu Indifferente/Sì/No nella scheda Visibilità.",
    ["wn_322_studio_finestyle"] = "Cooldown Studio: aggiunti controlli di stile fini nella scheda Stile — opacità, colore/spessore del bordo, un colore del timer personalizzato e un interruttore per l'ombra proiettata.",
    ["wn_322_forge_internal"] = "Interno: la logica condivisa di CooldownForge e Cooldown Studio è stata estratta in una nuova libreria interna Forge, gettando le basi per i futuri moduli di editing avanzato — nessuna modifica visibile all'utente.",
    ["wn_322_studio_fixes2"] = "Cooldown Studio: risolto il problema per cui i pulsanti della barra laterale (Nuova/Duplica/Rinomina/Elimina/modelli) a volte non rispondevano ai clic e traboccavano dalla loro riga, risolto il problema per cui Esc chiudeva la finestra causando un errore di corruzione (taint), e risolto il problema per cui la scheda selezionata si reimpostava invece di essere ricordata cambiando barra.",
    ["wn_322_studio_talents"] = "Cooldown Studio: la libreria degli incantesimi ora include anche i tuoi talenti attivi e i talenti eroici, non solo gli incantesimi del grimorio, così puoi tracciarli anche sulle barre dei cooldown.",
    ["wn_322_talent_scan_fix"] = "Cooldown Studio: risolto il problema per cui la scansione dei talenti/talenti eroici della libreria non trovava nulla in gioco — ora vengono considerati solo i talenti effettivamente scelti, usando il campo API corretto per leggere la tua scelta selezionata.",
    ["wn_322_diag_taintown"] = "Diagnostica: corretti i rapporti fantasma di ADDON_ACTION_FORBIDDEN (UseToy, SetNote...) attribuiti ad addon casuali — la Diagnostica ora assume la proprietà esclusiva degli eventi di corruzione (taint) invece di lasciare che la gestione nativa di Blizzard li ripropaghi.",
    ["wn_322_actionbars_discover"] = "Barre d'azione: il testo informativo della scheda Gestione barre ora menziona anche che espandere una barra rivela i controlli di dimensione dei pulsanti e scala, rendendo quell'opzione più facile da trovare.",
    ["wn_322_tracker_editmode"] = "Tracker degli obiettivi: risolto il problema per cui il tracker si bloccava durante il trascinamento mentre la modalità Modifica nativa di Blizzard era attiva.",
    ["wn_323_studio_preview"] = "Cooldown Studio: la scheda Stile ora mostra un'anteprima delle icone in tempo reale (stesso rendering delle barre reali) che alterna tra pronto/in cooldown, per vedere le modifiche di stile all'istante.",
    ["wn_323_studio_copystyle"] = "Cooldown Studio: aggiunto un pulsante \"Copia stile da...\" nella scheda Stile per copiare solo lo stile visivo di un'altra barra senza toccare incantesimi, posizione o layout.",
    ["wn_323_studio_create"] = "Cooldown Studio: \"+ Nuova\" ora chiede subito il nome della barra invece di creare un segnaposto da rinominare in seguito, e i popup di rinomina/creazione ora vengono mostrati in modo affidabile sopra la finestra con il campo nome messo automaticamente a fuoco.",
    ["wn_323_slider_entry"] = "Cursori di configurazione: clic destro su un valore per digitare un numero esatto, Ctrl+clic per ripristinare il valore predefinito, con un promemoria nel tooltip per entrambi.",
    ["wn_323_petbar_editmode"] = "Barre d'azione: le barre Animale domestico e Forme ora possono essere selezionate e trascinate in Modalità Modifica anche quando sono nascoste a riposo (nessun animale domestico/nessuna forma).",
    ["wn_324_studio_real_icons"] = "Cooldown Studio: l'anteprima della scheda Stile ora usa icone reali — prima gli incantesimi della barra stessa, poi il libro degli incantesimi e i talenti della tua classe — invece di tre icone dimostrative fisse di classi estranee.",
    ["wn_324_chat_contacts"] = "Chat: la barra laterale della chat guadagna un pulsante Contatti che apre la lista amici di Blizzard con un solo clic, ripristinando un accesso che era sparito perché lo skin nasconde il pulsante social nativo.",
    ["wn_324_editbox_scrollbar"] = "Configurazione: le caselle di testo multilinea (importa/esporta, note...) non mostrano più la barra di scorrimento dorata di Blizzard — ora usano la sottile barra con il colore d'accento dell'addon e supportano la rotellina del mouse.",
    ["wn_325_friends_window"] = "Contatti: la finestra amici è ora completamente personalizzata invece di essere un lavoro a metà — corpo scuro e piatto, bordo d'accento disegnato sopra la lista, titolo ridisegnato e un semplice pulsante di chiusura d'accento.",
    ["wn_325_friends_tabs"] = "Contatti: le schede in basso e le sotto-schede Amici / Alleati recenti / Recluta un amico hanno perso le loro placche dorate, e ora mostrano una sottolineatura e un'etichetta d'accento su quella selezionata.",
    ["wn_325_friends_buttons"] = "Contatti: ogni pulsante della finestra (Aggiungi amico, Invia messaggio, i pulsanti della scheda Chi, Converti in incursione, Info incursione, Unisciti alla coda) condivide ora un unico stile piatto d'accento che si schiarisce al passaggio del mouse, e i due pulsanti di contatto si dividono equamente la riga inferiore.",
    ["wn_325_friends_toggle"] = "Contatti: disattivare lo skin nelle impostazioni ora ripristina immediatamente l'aspetto di Blizzard, senza bisogno di ricaricare.",
    ["wn_325_cdf_radial"] = "CooldownForge: le barre di recupero possono ora disporre le loro icone in cerchio invece che in linea — imposta il raggio, l'angolo di partenza, l'ampiezza dell'arco e il verso dal nuovo modo di disposizione.",
    ["wn_325_cdf_spacing"] = "CooldownForge: la spaziatura delle icone è ora composta da due valori distinti — lungo la riga e tra le righe a capo — e il massimo è stato aumentato da 16 a 64 px.",
    ["wn_325_cdf_glow"] = "CooldownForge: il bagliore può ora attivarsi secondo una condizione a scelta — quando l'incantesimo è pronto, mentre un aura è attiva su di te (con un ID aura opzionale per monili/talenti), o sempre — configurabile per barra o per incantesimo.",
    ["wn_325_cdf_hidecd"] = "CooldownForge: una barra può ora nascondere ogni icona mentre è in recupero, con le icone rimanenti che colmano il vuoto; si riorganizza solo quando cambia l'insieme degli incantesimi pronti.",
    ["wn_326_whatsnew_stuck"] = "Novità: chiudere questa finestra con Esc lasciava lo schermo oscurato e il mouse inerte, e la versione non contrassegnata, così tornava al login successivo. Ogni modo di chiuderla (X, pulsante, Esc) passa ora da un unico punto che rimuove l'oscuramento e memorizza la versione.",
    ["wn_326_whatsnew_escape"] = "Novità: Esc è ora gestito dalla finestra stessa invece che tramite UISpecialFrames di Blizzard, eliminando una via di taint attraverso il menu di gioco; tutti gli altri tasti continuano a passare.",
    ["wn_326_whatsnew_gates"] = "Novità: la finestra attende ora un momento libero — mai sopra un filmato, un video o un combattimento — e salta completamente il primissimo login di un personaggio, per non accoglierti in piena sequenza introduttiva.",
    ["wn_326_tracker_empty"] = "Tracciatore obiettivi: quando non c'è nulla da tracciare non resta più un pannello scuro che copriva quasi tutto lo schermo — ora si riduce alla sua intestazione, e «Nascondi se vuoto» è attivo per impostazione predefinita (i profili esistenti vengono aggiornati una volta; se lo riporti su off, resta off).",
    ["wn_326_tracker_drag"] = "Tracciatore obiettivi: il pannello può di nuovo essere trascinato verso il basso — il vincolo allo schermo era applicato al riquadro sovradimensionato di Blizzard, il cui bordo inferiore era già fuori schermo, perciò ogni spostamento verso il basso veniva rifiutato.",
    ["wn_326_repbar_drag"] = "Barra della reputazione: corretto il caso in cui la barra mostrava il bordo di sblocco in modalità Disposizione ma non si lasciava afferrare — il mouse non era mai stato abilitato, quindi il trascinamento non poteva iniziare.",
    -- Supporti del Cooldown Manager (Movers / modalità disposizione)
    ["mover_cdm"]                        = "Cooldown Manager",
    ["cdm_drag_hint"]                    = "Trascina per spostare",
    ["cdm_preview_aura"]                 = "Aura",

    ["wn_326_suite_card"] = "Config: la dashboard guadagna una scheda «Suite Tomo» che presenta TomoBoss (timer dei boss con annunci vocali) — una scorciatoia alle sue opzioni se è installato, altrimenti un indirizzo copiabile e un «Non mostrare più» definitivo.",

    ["wn_330_cdf_unusable"] = "CooldownForge: un'icona ora può tingersi quando la magia non è in recupero ma non è lanciabile in quel momento — ira insufficiente, forma sbagliata, reagente mancante. Tre scelte: nessun effetto (predefinito), attenuare, oppure attenuare con una tinta blu quando a bloccare è proprio la risorsa; impostabile per barra e per magia.",
    ["wn_330_cdf_glow_usable"] = "CooldownForge: il bagliore ha guadagnato una condizione «quando la magia è utilizzabile» — pronta *e* lanciabile, così una magia a corto di risorse smette di brillare mentre attende invece di invitare a una pressione destinata a fallire.",
    ["wn_330_cdf_hide_unusable"] = "CooldownForge: una barra può anche nascondere del tutto un'icona finché manca la risorsa, accanto al filtro «nascondi durante il recupero» già esistente. I due sono indipendenti e cumulabili, e le icone rimanenti chiudono il vuoto.",
    ["wn_330_cp_charged"] = "Barre delle risorse: i punti combo sovraccarichi ora vengono mostrati come tali — la casella carica è evidenziata che sia piena o meno, così vedi dov'è la carica prima di spenderla. Il colore si sceglie in CD & Risorse → Colori, rosso per impostazione predefinita.",
    ["wn_330_colorpicker"] = "Configurazione: il selettore di colore si apriva dietro la finestra delle impostazioni e Cooldown Studio, dando l'impressione che il campione non facesse nulla. Ora si apre sopra di esse, proprio accanto al campione su cui hai cliccato anziché al centro dello schermo.",
    ["wn_330_locale_escapes"] = "Localizzazione: le opzioni della Bussola mostravano codici di escape grezzi al posto degli accenti — «modalitxC3xA0», «puxC3xB2», «Ampio (xC2xB190xC2xB0)». Quei testi usavano una sintassi di escape che il Lua del gioco non conosce e stampava alla lettera; sono di nuovo leggibili, in tutte e sei le lingue.",
    ["wn_330_diag_filters"] = "Diagnostica: essere immobilizzati e provare a spedire per posta un oggetto legato venivano registrati come errori nel rapporto. Sono entrambi normali messaggi di gioco e ora vengono filtrati come il resto.",
    ["wn_330_tracker_delve_place"] = "Tracciatore obiettivi: con «Nascondi se vuoto» disattivato il pannello restava, ma il blocco della spedizione non veniva mai posizionato al suo interno — il caso vuoto usciva prima della passata che lo colloca. I moduli scenario e spedizione ora vengono posizionati per primi, qualunque altra cosa sia tracciata.",
    ["wn_330_tooltip_info"] = "Tooltip: i tooltip delle unità portano finalmente un vero livello informativo — grado di gilda, bersaglio attuale dell'unità, punteggio Mitico+, cavalcatura, velocità di movimento e posizione, oltre alle icone di marcatore raid, ruolo e classe sulla riga del nome. Ogni riga ha il proprio interruttore in Skins → Tooltip.",
    ["wn_330_tooltip_inspect"] = "Tooltip: passare sopra un giocatore ora mostra il suo livello oggetto equipaggiato e la sua specializzazione. Entrambi richiedono un'ispezione, quindi appaiono solo a portata; il livello oggetto è colorato in base allo scarto con il tuo anziché su soglie di stagione che scadono a ogni patch.",
    ["wn_330_tooltip_border"] = "Tooltip: il bordo può assumere il colore dell'unità — colore di classe per un giocatore, ostile / neutrale / amichevole per un PNG — e la riga del livello è ricolorata per difficoltà, in rosso per un boss o un'unità «??».",
    ["wn_330_tooltip_bar"] = "Tooltip: la barra della salute è ora nascosta per impostazione predefinita, dato che il livello informativo la sostituisce. I profili esistenti vengono aggiornati una volta; togliendo la spunta la barra torna e resta.",
    ["wn_330_pf_leader"] = "Riquadri gruppo: il capogruppo è ora segnalato da una corona sopra il suo riquadro, con interruttore e cursore di dimensione propri.",
    ["wn_330_stance_bar"] = "Barre delle azioni: le classi senza forme di mutaforma si ritrovavano una barra delle posture con dieci caselle vuote, e togliendo «mostra slot vuoti» spariva l'intera barra. Ora compare solo se hai davvero delle forme, con esattamente tanti pulsanti quante sono le forme.",
    ["wn_330_leveling_panel"] = "Barra di livello: passandoci sopra si apre ora un pannello stilizzato al posto di un tooltip, con livello, PE, PE mancanti, avanzamento, riposo, PE/h, tempo al livello, PE guadagnati dall'ultimo passaggio di livello e il contributo dell'ultima missione. Si sposta sotto la barra quando non c'è spazio sopra.",
    ["wn_330_bags_click"] = "Borse: disincantare, macinare o prospettare dallo skin delle borse richiedeva due tentativi — la pressione consumava il cursore di targeting e il rilascio raccoglieva invece l'oggetto. Ora funziona al primo colpo, e il trascinamento non è toccato.",
    ["wn_330_bags_layout"] = "Borse: il layout «Categorie» è stato rimosso, restano Griglia combinata e Borse separate. Un profilo ancora impostato su di esso viene spostato una volta sulla griglia combinata.",
    ["wn_330_chat_copy"] = "Chat: l'icona di copia per messaggio metteva un glifo segnaposto davanti a ogni riga, perché la sua texture non si risolveva mai. L'opzione è stata rimossa e azzerata una volta per chi la aveva attiva.",

    ["wn_331_tooltip_secret"] = "Descrizione: l'intero livello di informazioni sull'unità aggiunto in 3.3.0 non compariva mai su Midnight — niente grado di gilda, bersaglio, punteggio Mitica+, cavalcatura, velocità, posizione, livello oggetto, specializzazione o icone sulla riga del nome. Il livello rilegge il token dell'unità dalla descrizione, il gioco ora lo restituisce come valore protetto e la protezione lo rifiutava: non veniva mai scritto nulla.",
    ["wn_331_tooltip_border"] = "Descrizione: il bordo con il colore dell'unità era spento per lo stesso motivo — leggeva il token tramite la propria protezione e rinunciava, quindi ogni unità ricadeva sul colore di bordo configurato, il che sembrava esattamente un'opzione che non fa nulla.",
    ["wn_331_tooltip_target"] = "Descrizione: la riga del bersaglio spariva per qualsiasi giocatore il cui nome torna protetto, ossia la maggior parte. Il nome non viene più racchiuso in un codice colore — costruire quella stringa equivale a leggere il nome — e il colore passa dagli argomenti di colore della descrizione stessa. Identico a schermo, e ora funziona.",
    ["wn_331_tooltip_guards"] = "Descrizione: le protezioni stesse potevano sollevare un errore. Una confrontava il valore con una stringa vuota prima di verificare se fosse protetto, quindi si bloccava proprio sui valori che doveva intercettare, e una ventina di test vero/falso (l'unità esiste, è un giocatore, è ispezionabile…) venivano confrontati senza protezione. Ora è tutto verificato nell'ordine giusto.",
    ["wn_331_inspect"] = "Descrizione: livello oggetto e specializzazione tornano insieme al resto — il motore di ispezione eseguiva gli stessi confronti non protetti a ogni test di idoneità e si arrendeva davanti a un valore protetto ancora prima di inviare una richiesta.",
    ["wn_330_tracker_delve"] = "Tracciatore obiettivi: dentro una spedizione il tracciatore non mostrava nulla — né fase, né criteri, né avanzamento. «Nascondi se vuoto» contava solo i blocchi missione, mentre una spedizione registra il proprio avanzamento nel modulo scenario, che quel conteggio lascia fuori di proposito, quindi l'intero pannello veniva nascosto. Spedizioni, scenari e obiettivi bonus ora contano come contenuto, e il pannello si adatta alla loro dimensione quando sono soli sullo schermo.",
    ["wn_327_tracker_progressbars"] = "Tracciatore obiettivi: le barre di avanzamento delle missioni (conteggi di uccisioni, forze nemiche, criteri di scenario e di spedizione) sono tornate — una barra non viene più scartata come orfana quando il suo blocco è raggiungibile solo tramite un ancoraggio, sopravvive alla chiusura e riapertura del suo gruppo, e quelle che restano adottano finalmente lo stile del resto del tracciatore.",
    ["wn_327_tracker_position"] = "Tracciatore obiettivi: un tracciatore spostato con la Modalità Modifica di Blizzard tornava al punto precedente al ricaricamento successivo — quella posizione non veniva mai scritta nel database dell'addon. Ora viene salvata alla fine della sessione di Modalità Modifica, e un tracciatore con una scala diversa dal 100% non scivola più un po' più in là a ogni ricaricamento.",
    ["wn_327_minimap_indicators"] = "Minimappa: l'indicatore di difficoltà dell'istanza restava visibile fuori dalle istanze, perché riancorare gli indicatori nativi li forzava anche a essere visibili, scavalcando la regola di Blizzard. Ora seguono di nuovo la visibilità di Blizzard — e il pulsante dell'espansione non resta più invisibile per sempre dopo essere stato disattivato e riattivato.",
    ["wn_327_resourcebar_frozen"] ="Barre delle risorse: la barra dell'energia centrata restava bloccata sul valore che aveva alla costruzione — 0 ira, 0 energia — per tutte le specializzazioni la cui unica risorsa è quella primaria (Guerriero, Sacerdote, Mago del Fuoco, Tessitore di nebbie, Havoc...), mentre il riquadro unità mostrava il valore reale lì accanto. Ora si aggiorna di nuovo come tutte le altre barre.",
    ["wn_327_profile_rename"] ="Profili: rinominare o duplicare un profilo non faceva assolutamente nulla — la riscrittura dei popup in 11.2 ha rimosso il campo da cui veniva letto il nome digitato. Entrambe le azioni funzionano di nuovo, e Invio ora conferma come il pulsante di conferma.",
    ["wn_327_cds_rename"] = "Cooldown Studio: stessa correzione per i popup «Rinomina barra» e «+ Nuova» — il nome digitato veniva ignorato, quindi rinominare non faceva nulla e ogni nuova barra usciva chiamata «Nouvelle barre».",
    ["wn_327_popup_layer"] = "Popup: la richiesta di ricaricamento, le finestre di importazione / esportazione e tutte le conferme di profilo venivano disegnate dietro la finestra di configurazione e Cooldown Studio, dando l'impressione che non succedesse nulla. Ora vengono portate sopra la finestra TomoMod aperta.",
    ["wn_327_profile_refresh"] = "Profili: creare, eliminare, rinominare o duplicare un profilo ora aggiorna l'elenco a schermo invece di lasciare quello precedente servito dalla cache delle pagine.",
    ["wn_327_import_perf"] = "Profili: l'importazione è nettamente più rapida — la stringa decodificata per l'anteprima viene riutilizzata alla conferma invece di essere decodificata una seconda volta, il che costituiva la maggior parte del blocco al clic su Importa.",
    ["wn_327_gui_split"] = "Config: Profili e Diagnostica tornano a essere categorie distinte nella barra laterale invece di essere raggruppate sotto Strumenti, ciascuna con la propria icona e descrizione; i vecchi collegamenti a Strumenti continuano a funzionare.",

