    ["art_tt_min_ago"]                    = "%dm fa",
    ["art_tt_hour_ago"]                   = "%dh fa",
    ["art_tt_day_ago"]                    = "%dg fa",
    ["wn_300_minimap"]                    = "Pulsante della minimappa — accesso rapido alle funzioni e alle impostazioni di TomoMod.",
    ["wn_300_buttonbag"]                  = "Button Bag — raggruppa e gestisce i tuoi pulsanti azione in modo efficiente.",
    ["tab_qol_rare_alert"]                = "Avviso rari",
    ["section_rare_alert"]                = "Avviso rari",
    ["opt_rare_alert_enable"]             = "Attiva gli avvisi di prossimità dei rari",
    ["opt_rare_alert_sound"]              = "Riproduci un suono di avviso",
    ["opt_rare_alert_duration"]           = "Durata del banner (s)",
    ["btn_reset_rare_alert_pos"]          = "Reimposta la posizione del banner",
    ["rare_alert_info"]                   = "Ti avvisa quando un PNG raro è nelle vicinanze. Clicca sul banner per bersagliarlo, applicare il simbolo del teschio e impostare un punto di rotta. Clic destro per chiuderlo. Usa /tm layout per spostare il banner.",
    ["rare_alert_tooltip"]                = "Clic sinistro: bersaglia + teschio + punto di rotta. Clic destro: chiudi.",
    ["wn_305_rare_alert_marker"]          = "Clicca sul banner di un raro per bersagliarlo, applicare il simbolo del teschio e impostare un punto di rotta. Suono e durata configurabili; trascinabile in modalità layout.",
    ["wn_305_tm_fix"]                     = "Corretto — cliccare su un avviso di raro di RareScanner non apre più la configurazione di TomoMod (la collisione del comando /tm è risolta).",

    -- =====================
    -- 3.3.2 — Novità
    -- =====================
    ["wn_332_perf_auras"] = "Prestazioni: il tracciatore di aure e lo stile dei potenziamenti ora ascoltano solo i tuoi cambiamenti di aure. Non hanno mai agito su nessun altro, ma venivano svegliati per ogni unità le cui aure cambiavano — oltre venti membri del raid più ogni targhetta visibile, di continuo — solo per controllare l'unità e scartarla. Il gioco le filtra ora, prima che venga eseguito qualsiasi nostro codice.",
    ["wn_332_perf_castbar"] = "Prestazioni: lo stesso per il monitoraggio della latenza della barra di lancio, che veniva svegliato da ogni incantesimo di ogni unità visibile — un intero gruppo di nemici minori di abilità — mentre contavano solo i tuoi lanci.",
    ["wn_332_perf_gc"] = "Prestazioni: il tracciatore di aure era la principale fonte di spazzatura in memoria dell'interfaccia. La sua scansione e la sua disposizione giravano più volte al secondo in combattimento e buttavano via una pila di tabelle temporanee a ogni passaggio; ora riutilizzano le stesse tabelle di lavoro. Sullo schermo non cambia nulla.",
    ["wn_332_aura_order"] = "Tracciatore di aure: due aure applicate con lo stesso lancio e la stessa durata potevano scambiarsi di posto in modo visibile tra un aggiornamento e l'altro, perché nulla ne decideva l'ordine. Ora è stabile.",
    ["wn_332_skyride_leak"] = "Volo dinamico: /tm skyride costruiva una seconda copia della barra ogni volta che veniva usato. La vecchia restava sullo schermo, non più collegata a nulla e impossibile da nascondere, perché il gioco non recupera mai un frame. La barra viene costruita una sola volta e il comando si limita a riapplicarvi le tue impostazioni.",
    ["wn_332_skyride_ticker"] = "Volo dinamico: lo stesso comando lasciava inoltre dietro di sé, ogni volta, un aggiornamento permanente a 4 Hz che non era più possibile fermare. Non si accumulano più, e l'aggiornamento si arresta quando il modulo viene disattivato invece di interrogare una barra nascosta.",
    ["wn_332_tooltip_incombat"] = "Descrizione: il livello dell'oggetto e la specializzazione sparivano da ogni descrizione non appena iniziava un combattimento, per tornare solo alla fine. Il controllo di distanza con cui si concludeva il motore di ispezione è tra quelli che il gioco rifiuta di rispondere agli addon in combattimento: ogni unità risultava quindi fuori portata per tutta la durata del gruppo — mentre il registro di contaminazione si riempiva di una chiamata bloccata per ogni passaggio del mouse. Ora usa un controllo che funziona in combattimento.",
    ["wn_332_tooltip_backoff"] = "Descrizione: il controllo di distanza sostitutivo è meno preciso (vede molto più lontano di quanto un'ispezione arrivi davvero), perciò un giocatore troppo lontano per rispondere viene ricordato e lasciato stare per venti secondi invece di essere interrogato a ogni descrizione. Può esserci una sola ispezione in corso alla volta, e un giocatore fuori portata occupava quel posto in continuazione. Una descrizione rimasta senza risposta non resta più bloccata su «caricamento».",
    ["wn_332_diag_nopath"] = "Diagnostica: caricare oltre un vuoto, balzare su una sporgenza o mandare un famiglio dove non può camminare veniva registrato come errore nel rapporto. «Nessun percorso disponibile» è un normale riscontro di gioco, e ora viene filtrato in tutte e sei le lingue.",
    ["wn_332_locale_castbar"] = "Configurazione: la casella principale del pannello Barre di lancio riportava «Attiva la barra dei consumabili» in tutte le lingue — due opzioni diverse condividevano la stessa chiave di traduzione e vinceva quella dei consumabili. Ora ognuna ha la propria.",
    ["wn_332_locale_translations"] = "Localizzazione: 173 stringhe per lingua tradotte in tedesco, spagnolo, italiano e portoghese — impostazioni avanzate e di visibilità della gestione dei tempi di recupero, categorie di missioni del tracciatore di obiettivi, interfaccia della chat, spostamenti e texture del cursore — oltre alle 49 stringhe dell'interfaccia della chat in francese. Ricadevano silenziosamente sull'inglese invece di mostrare un errore, quindi nessuno le aveva segnalate.",
    ["wn_332_locale_search"] = "Configurazione: la casella di ricerca mostrava il testo grezzo «gs_no_results» invece di «Nessuna opzione corrispondente» quando non c'erano risultati. Il messaggio è ora definito in tutte e sei le lingue.",
    ["wn_332_package"] = "Pacchetto: il download non include più le suite di test, gli esempi, la documentazione generata e i file readme delle librerie incluse. Nulla di tutto ciò veniva mai caricato dall'addon.",
    ["wn_332_companion_panel"] = "Promemoria famiglio: il modulo che ti avvisa quando il tuo famiglio manca o è morto ha finalmente un pannello di impostazioni, in QOL. L'attivazione, la dimensione, la scala, la visualizzazione di icona, testo o entrambi e la posizione sullo schermo si potevano cambiare solo modificando un file a mano.",
    ["wn_332_companion_travel"] = "Promemoria famiglio: poteva restare sullo schermo, a quattro volte la sua dimensione, per un intero volo. Controllava se stavi volando solo nei momenti in cui eri ancora a terra, e dopo nulla poteva più nasconderlo. Ora è nascosto in volo, sui voli di linea e nei veicoli — e anche su cavalcatura terrestre, cosa che puoi disattivare.",
    ["wn_332_companion_locale"] = "Promemoria famiglio: «Famiglio assente» e «Famiglio morto» apparivano in inglese qualunque fosse la lingua del client. Entrambi sono tradotti, così come tutto il nuovo pannello.",

    -- =====================
    -- 3.3.3 — Novità
    -- =====================
    ["wn_333_summon_stuck"] = "Riquadri di gruppo e incursione: l'icona di evocazione restava sul riquadro fino al ricaricamento dell'interfaccia. Una volta accettata o rifiutata, il gioco continua a restituire l'ultimo stato dell'evocazione invece di cancellarlo, quindi l'icona descriveva qualcosa che aveva smesso di esistere da minuti. Ora verifica che ci sia davvero un'evocazione in corso prima di mostrare qualsiasi cosa.",
    ["wn_333_summon_roster"] = "Riquadri di gruppo e incursione: al cambiare della composizione, un'icona di evocazione poteva restare su un riquadro che ormai apparteneva a un altro giocatore. Lo stato viene riletto a ogni cambio di composizione e dopo ogni cambio di zona, e viene aggiornato insieme al resto del riquadro anziché solo quando il gioco segnala un cambiamento.",
    ["wn_333_defensives_party"] = "Riquadri di gruppo: i tempi di recupero difensivi attivi su ogni membro sono ora mostrati. Esistevano solo sui riquadri d'incursione, e lì erano una sola icona, senza durata e senza alcuna indicazione di cosa fosse.",
    ["wn_333_defensives_categories"] = "Riquadri di gruppo e incursione: le difensive sono divise in esterne (lanciate su questo giocatore — Scorza di Ferro, Bozzolo Vitale, Soppressione del Dolore), di incursione (Grido d'Incitamento, Oscurità, Zona Antimagia) e personali (Scudo Divino, Blocco di Ghiaccio, Corteccia), ognuna con la propria opzione. Cinquanta incantesimi, ordinati in modo che le esterne vengano per prime, con il tempo rimanente e un bordo colorato per categoria.",
    ["wn_333_defensives_defaults"] = "Riquadri di gruppo e incursione: per impostazione predefinita vengono mostrate solo le esterne. Una difensiva di incursione accende tutti i riquadri insieme — esattamente quando sono meno leggibili — e le personali sono costanti. Entrambe possono essere attivate.",
    ["wn_333_defensives_size"] = "Riquadri d'incursione: il cursore della dimensione delle icone difensive aveva effetto solo dopo un ricaricamento. Ora si applica mentre lo trascini.",
    ["wn_333_hots_drift"] = "Riquadri di gruppo e incursione: i due insiemi di riquadri non concordavano su quali cure nel tempo mostrare. Benedizione dell'Estate, Totem Nembifero e Soffio Avvolgente comparivano sui riquadri di gruppo ma non su quelli d'incursione — lo stesso beneficio, sullo stesso giocatore, visibile da una parte e non dall'altra. Ora c'è un solo elenco, che copre tutte e sei le classi curatrici.",
    ["wn_333_dispel_border"] = "Riquadri di gruppo e incursione: lo spessore del bordo dell'evidenziazione di dissoluzione è ora regolabile, da 1 a 6. Cresce verso l'esterno, quindi un bordo più spesso non invade mai la barra della salute, e il valore predefinito appare esattamente come prima.",
    ["wn_333_stance_grid"] = "Barre delle azioni: con «mostra gli slot vuoti» disattivato, la barra delle posture poteva comunque mostrare dieci caselle vuote, e restavano lì finché non cambiavi postura. Il passaggio che rivela gli slot vuoti mentre trascini un incantesimo veniva eseguito anche sulle barre delle posture e del famiglio, i cui pulsanti non sono affatto slot d'azione — li considerava quindi tutti vuoti e li mostrava, mentre il passaggio che li nasconde di nuovo salta deliberatamente proprio quelle due barre, così non restava più nulla a rimetterli a posto.",
    ["wn_333_diag_display"] = "Diagnostica: i rapporti includono ora la risoluzione, la modalità di visualizzazione e la scala dell'interfaccia — e segnalano il caso in cui la scala sia stata impostata da qualcosa di diverso dalle opzioni del gioco. Oltre i 1200 pixel di altezza il client non riduce abbastanza la scala da solo, perciò le configurazioni ad alta risoluzione finiscono ridimensionate a mano o da un altro componente aggiuntivo, e questo era invisibile in un rapporto.",
    ["wn_333_diag_scalechange"] = "Diagnostica: un cambio di scala o di risoluzione durante la sessione viene registrato con i valori precedenti e successivi, così un ridimensionamento compare accanto agli errori che potrebbe aver causato. Quel ridimensionamento viene riapplicato dopo ogni schermata di caricamento, ed è proprio allora che rompe qualcosa.",
    ["wn_333_diag_perf"] = "Diagnostica: i rapporti riportano ora la frequenza dei fotogrammi (attuale, oltre a minimo, media e massimo della sessione) e la latenza, e ogni errore catturato registra la frequenza dei fotogrammi nel momento in cui si è verificato. Un errore che compare solo su un client che scatta è un problema di tempistica e non una funzione rotta, e nulla in un rapporto permetteva di distinguerli.",
    ["wn_333_diag_scale_expected"] = "Diagnostica: il rapporto sosteneva che la scala dell'interfaccia fosse stata impostata da una macro o da un altro componente aggiuntivo su quasi ogni configurazione. Quando l'opzione di scala dell'interfaccia del gioco è disattivata, il valore con cui veniva confrontata non è quello che il gioco sta usando, quindi veniva segnalata una configurazione del tutto normale. Ora calcola quale scala ci si aspetta per la tua risoluzione e le tue impostazioni, la stampa, e avvisa soltanto in caso di scostamento reale.",
    ["wn_333_diag_settle"] = "Diagnostica: la scala che il gioco applica da sé durante l'accesso finiva in ogni rapporto come un ridimensionamento a metà sessione. La rilevazione dello schermo attende ora quattro secondi che il client si stabilizzi prima di effettuare una lettura, così l'unica voce di scala rimasta in un rapporto è quella che merita davvero una spiegazione.",
    ["wn_333_diag_mode"] = "Diagnostica: quando il rapporto non riesce a determinare la modalità di visualizzazione, ora stampa i valori grezzi forniti dal gioco anziché un semplice punto interrogativo — quei nomi di impostazione cambiano da un'espansione all'altra, e un «?» da solo non era diagnosticabile senza tornare a chiedertelo. Lo schermo intero in finestra e le finestre massimizzate vengono riconosciuti in più casi, e le versioni dei componenti aggiuntivi non compaiono più come «vv1.2.3».",
    ["wn_333_shared"] = "Interno: i riquadri di gruppo e d'incursione mantenevano due copie delle stesse 250 righe — la logica di evocazione, l'elenco delle cure nel tempo, il tracciamento delle difensive. Tutti e tre i problemi qui sopra derivano da questo: una correzione applicata a una copia e non all'altra. Ora condividono un'unica implementazione.",

    -- =====================
    -- 3.5.7 — Novità
    -- =====================
    ["wn_357_talkingheadfix"] = "Correzione — Nascondi Talking Head poteva lasciare la voce fuori campo di un talking head in riproduzione sotto un riquadro nascosto. I riquadri dei talking head gestiscono la propria visibilità, quindi limitarsi a nascondere il riquadro alla visualizzazione lasciava lo stato di riproduzione e il relativo timer di fine in esecuzione — e saltava ogni riga successiva alla prima in un talking head su più righe, poiché il riquadro era già visibile per quelle. TomoMod ora si aggancia alla funzione di riproduzione effettiva e chiude ogni talking head esattamente come fa Blizzard, il che ferma in modo affidabile timer e voce fuori campo insieme.",
    ["wn_357_talkingheadcleanup"] = "Interno — Una chiamata di stop dell'audio emessa nello stesso istante in cui parte una voce fuori campo viene occasionalmente ignorata dal motore audio, quindi Nascondi Talking Head ora ripete il comando una frazione di secondo dopo per assicurarsi che si fermi davvero.",
    ["wn_357_queueeyedb"] = "Correzione — La posizione dell'occhio della coda in realtà non veniva mai salvata. La sua voce mancava dalla tabella delle impostazioni predefinite, quindi il gestore del salvataggio ignorava silenziosamente la scrittura di una nuova posizione ogni volta che la trascinavi — l'occhio si spostava correttamente a schermo, ma dimenticava dove l'avevi messo al login successivo. La voce mancante è tornata, e il percorso di salvataggio ora la crea al volo se le tue impostazioni salvate ne sono ancora prive, così che un salvataggio non aggiornato non costa più di una tabella in più.",
    ["wn_357_queueeyeposition"] = "Correzione — La posizione predefinita dell'occhio della coda era una stima alla cieca che finiva in un punto diverso a seconda della risoluzione — completamente fuori schermo su un monitor ultrawide, ed è così che è stato scoperto. Ora per impostazione predefinita si trova accanto alla minimappa, dove l'occhio vive realmente.",
    ["wn_357_lfgeyesurvive"] = "Novità — L'occhio del cerca gruppo scompariva del tutto quando nascondevi il micromenu di Blizzard, poiché vive in quello stesso contenitore. Ora resta al suo posto — lo stato della coda del cerca gruppo è sempre visibile, ovunque tu l'abbia posizionato, che il micromenu nativo sia nascosto o meno.",
    ["wn_357_lfgeyeoptions"] = "Novità — Due nuove opzioni della microbarra ti permettono di disattivare del tutto l'occhio del cerca gruppo o ridimensionarlo, accanto all'impostazione che nasconde il micromenu di Blizzard.",
    ["wn_357_lfgeyescale"] = "Correzione — Il cursore delle dimensioni dell'occhio del cerca gruppo non faceva nulla a meno che la microbarra non fosse completamente attiva con anche «nascondi il micromenu di Blizzard» attivo — altrimenti la scala veniva silenziosamente ripristinata al normale a ogni aggiornamento. Ora si applica in ogni caso.",
    ["wn_357_roletaintguard"] = "Correzione — Un errore delle nameplate poteva ancora verificarsi confrontando un ruolo non leggibile direttamente, anche con la protezione già presente. Questo confronto è ora controllato due volte, così un ruolo illeggibile viene trattato come nessun ruolo invece di generare un errore.",
    ["wn_357_cooldowntaint"] = "Correzione — Alcuni pulsanti della barra azione potevano accumulare un errore aggiornando la loro animazione di ricarica quando il gioco non permetteva di leggere il valore direttamente, anche sulle barre con la skin disattivata. Questo aggiornamento viene ora saltato in sicurezza su ogni pulsante interessato e ogni ricarica che porta, invece di generare un errore.",
    ["wn_357_mainbartaint"] = "Correzione — Poteva comparire un errore raro nel tentativo di rimostrare la barra azione predefinita dopo essere saliti in sella o in un veicolo. Ora viene silenziato allo stesso modo di casi simili.",
    ["wn_357_mailiconcrash"] = "Correzione — L'icona della posta della minimappa poteva generare un errore ogni volta che arrivava nuova posta. Ora non succede più, e l'icona si comporta esattamente come prima.",
    ["wn_357_buggrabber"] = "Novità — Se usi anche !BugGrabber, Diagnostics ora si appoggia anche a lui, recuperando gli errori che ha visto prima che il tracciamento di TomoMod iniziasse in questa sessione. Nulla cambia se non lo hai installato.",
    ["wn_357_shieldenchant"] = "Correzione — L'avviso di incantamento arma nella scheda personaggio poteva segnalare uno scudo o un oggetto tenuto nella mano sinistra (grimori, fronzoli, ecc.) come privo di incantamento, anche se nessuno dei due può essere incantato — i tank con scudo e i lanciatori di incantesimi che tenevano un oggetto nella mano sinistra vedevano un avviso rosso per qualcosa che non è mai stato incantabile. L'avviso ora compare solo su uno slot che contiene un'arma realmente incantabile.",
    ["wn_357_inspectiteminfo"] = "Novità — Ispezionare un altro giocatore ora mostra lo stesso dettaglio per oggetto della tua scheda personaggio: livello oggetto, livello di potenziamento, testo dell'incantamento (o un avviso di incantamento mancante) e slot delle gemme accanto a ogni oggetto indossato, invece di un solo numero medio in alto.",
    ["wn_357_inspectiteminfotoggle"] = "Novità — Una nuova casella ti permette di disattivare le info oggetto/incantamenti/gemme della finestra di ispezione indipendentemente dalle impostazioni della tua scheda personaggio.",
    ["wn_357_enemybuffgrid"] = "Novità — Il tracker dei Buff nemici sui tuoi riquadri bersaglio e focus (le aure benefiche lanciate su ciò che stai bersagliando) ha ora i propri menu a tendina Direzione (destra/sinistra) e Riga successiva (su/giù), più un cursore Icone per riga — prima era fisso a 3 per riga, in crescita verso l'alto, senza modo di cambiare nessuno dei due. Anche il massimo del cursore del numero è passato da 8 a 12, e qualsiasi pila è limitata a 3 righe, nascondendo il resto invece di crescere all'infinito.",
    ["wn_357_aurasgrid"] = "Novità — Le Aure normali (buff, debuff, o entrambi, su giocatore/bersaglio/focus) ora usano la stessa griglia icone-per-riga dei Buff nemici: un cursore Icone per riga (6 di default) sostituisce il vecchio a capo basato sui pixel, con lo stesso limite di 3 righe.",
    ["wn_357_auradirectionfix"] = "Correzione — Le impostazioni di direzione sia di Aure che di Buff nemici prima non facevano nulla silenziosamente: l'aggiornamento live del motore delle aure riapplicava la direzione di crescita solo se anche la dimensione o il numero di icone cambiavano nello stesso aggiornamento, e anche allora un angolo di ancoraggio fisso faceva sì che \"cresci verso l'alto\" lasciasse la pila di icone fluttuare alcune righe sopra la barra della salute invece di aderirvi. Entrambe sono corrette — le modifiche a direzione e icone per riga si applicano ora immediatamente, e la pila cresce esattamente da dove dovrebbe, senza nulla che fluttui.",
    ["wn_357_aurasliverefresh"] = "Correzione — Diverse opzioni di Aure/Buff nemici (numero, direzione, tipo) prima richiedevano un `/reload` per applicarsi davvero, anche se sembravano dover aggiornarsi all'istante. La maggior parte ora lo fa; le due che ne hanno ancora davvero bisogno — Abilita e il menu a tendina di tipo buff/debuff/entrambi — ora lo indicano direttamente nel pannello.",
    ["wn_357_microbarcombatfade"] = "Correzione — Passare il mouse su un pulsante della Micro Bar in combattimento poteva generare un errore di azione bloccata invece di far semplicemente comparire la barra in dissolvenza. La dissolvenza al passaggio del mouse ora salta direttamente al valore finale invece di animarsi durante il combattimento, evitando del tutto la chiamata bloccata.",

    -- =====================
    -- 3.5.5 — Novità
    -- =====================
    ["wn_355_barhoverblocked"] = "Correzione: il semplice passaggio del mouse su un pulsante della barra delle azioni durante un combattimento produceva un errore di azione bloccata, ogni singola volta. L'aggiornamento del pulsante di Blizzard viene eseguito al passaggio del mouse e si conclude scrivendo direttamente un'impostazione di pressione prolungata — una scrittura non consentita in combattimento, e attribuita a TomoMod perché i pulsanti sono nostri. Una voce per ogni passaggio del mouse: è così che una sola sessione ne ha accumulate 127. TomoMod scrive ora quell'impostazione dal proprio percorso sicuro, dove veniva già scritta correttamente, e salta la versione ridondante di Blizzard.",
    ["wn_355_barpingblocked"] = "Correzione: lo stesso passaggio del mouse eseguiva una seconda scrittura vietata due righe più avanti, questa volta appartenente al sistema dei ping. I ping riguardano le barre di Blizzard e non si sono mai applicati ai pulsanti di TomoMod, quindi anche quella chiamata viene ora saltata. Nessuna delle due ha mai rotto qualcosa a schermo — ma seppellivano gli errori reali sotto il rumore e facevano sembrare il componente aggiuntivo responsabile di qualunque altra cosa andasse storta nello stesso combattimento.",
    ["wn_355_escapekeyblocked"] = "Correzione: con una finestra di TomoMod aperta in combattimento, ogni tasto premuto produceva un errore di azione bloccata — tenere premuto un tasto di movimento bastava da solo a riempire il registro degli errori. Il controllo del combattimento c'era già, veniva solo eseguito una riga troppo tardi, dopo la chiamata protetta che avrebbe dovuto impedire. Ora viene eseguito per primo.",
    ["wn_355_microportrait"] = "Correzione: nel micromenu personalizzato, il pulsante della scheda del personaggio appariva come un quadrato colorato vuoto, mentre tutti gli altri pulsanti erano corretti. È l'unico la cui grafica non è un'icona fissa — è il ritratto del tuo personaggio — e TomoMod copiava un riferimento a una texture che semplicemente non si riproduce da nessun'altra parte. Ora chiede al gioco di disegnare il tuo ritratto direttamente sul pulsante e prende in prestito la stessa maschera arrotondata e la stessa ombra che Blizzard usa sul proprio pulsante del personaggio — così mostra il tuo personaggio con la stessa forma e la stessa profondità dei pulsanti accanto, invece di un quadrato piatto.",
    ["wn_355_perftooltip"] = "Novità: il suggerimento sulla memoria del micro-menu personalizzato si apre ora con un blocco Prestazioni: i tuoi fotogrammi al secondo, la latenza locale e mondiale e la CPU totale degli addon. La riga della CPU ha senso solo se il gioco la sta registrando, cosa disattivata per impostazione predefinita e che richiede un ricaricamento — perciò, anziché mostrarti degli zeri che sembrerebbero una misurazione reale, indica «profilazione disattivata» finché non la attivi.",
    ["wn_355_micronative"] = "Correzione: su alcuni client, spuntare «nascondi il micro-menu di Blizzard» non faceva assolutamente nulla: la casella restava spuntata e la barra restava sullo schermo. TomoMod cercava il menu di Blizzard sotto un unico nome, che è cambiato nel corso delle patch, e si arrendeva non appena non lo trovava — senza nemmeno nascondere i pulsanti, che era la parte che avrebbe funzionato. Ora riconosce tutti i nomi usati da Blizzard e gestisce comunque i pulsanti. Se sul tuo client non risponde nulla, ora te lo dice una volta in chat invece di fallire in silenzio — segnalalo con la versione del client se vedi quel messaggio.",
    ["wn_355_queueanchor"] = "Novità: l'occhio della coda — la piccola icona che ruota mentre attendi un dungeon o un campo di battaglia — ora può essere spostato. Blizzard lo aggancia alla minimappa e non gli dà alcuna maniglia nella modalità Modifica, il che ne faceva l'unico elemento dell'interfaccia che semplicemente non potevi posizionare. Ora compare tra le ancore spostabili di `/tm sr`, e uno spostamento effettuato in combattimento viene applicato al termine dello scontro anziché essere rifiutato.",
    ["wn_355_escapepropagate"] ="Interno: la propagazione della tastiera di quelle finestre viene ora stabilita una volta sola, alla costruzione della finestra, invece di essere reimpostata a ogni pressione di tasto. Non ne ha mai avuto bisogno: è una proprietà persistente del riquadro, e l'unica cosa che la disattiva è la chiusura della finestra con Esc, che in combattimento non può avvenire.",

    -- =====================
    -- 3.5.4 — Novità
    ["wn_354_preyfix"] = "Correzione — La barra di avanzamento del Prey Tracker restava bloccata permanentemente allo 0%. `GetPreyWidgetInfo` conservava solo il booleano restituito da `pcall`, non i dati reali del widget, quindi leggere `.progressPercent` da esso generava un errore ogni secondo e interrompeva l'aggiornamento prima che potesse mai ricadere sul conteggio dell'obiettivo della missione. La chiamata ora conserva entrambi i valori restituiti, così un campo del widget mancante viene gestito silenziosamente e l'avanzamento reale — letto dal conteggio dell'obiettivo della caccia — viene mostrato correttamente.",
    ["wn_354_extranudge"] = "Modifica — Le sovrapposizioni di spostamento del Pulsante Azione Extra e dell'Abilità di Zona perdono le quattro frecce di regolazione fine che le circondavano in `/tm layout`. Trascinare la sovrapposizione con il mouse continua a riposizionarla esattamente come prima; sono scomparsi solo i pulsanti extra.",
    ["wn_354_perflocale"] = "Interno — Caricare una lingua diversa dall'inglese costruiva e scartava immediatamente quasi 2900 voci di traduzione, cinque volte di seguito, a ogni `/reload` — il file veniva compilato per intero prima che l'addon potesse decidere che non serviva. Ogni file di lingua non attiva ora si interrompe prima di costruire la sua tabella, e il controllo di fusione della lingua base (che non faceva nulla silenziosamente per una particolarità della metatabella) è corretto per verificare solo ciò che doveva verificare.",
    ["wn_354_perfrangeticker"] = "Modifica — Il timer di controllo della portata dei riquadri di gruppo e d'incursione, una rete di sicurezza per i casi che l'evento di portata del gioco non copre, girava due volte al secondo per riquadro indipendentemente dalla dimensione del gruppo. Ora gira ogni due secondi — comunque più veloce di qualsiasi transizione debba cogliere — riducendo quel costo di tre quarti.",
    ["wn_354_perfaura"] = "Interno — Scansionare le difensive di un'unità apriva una nuova chiamata protetta per ogni beneficio controllato, fino a quaranta volte per aggiornamento aura per unità tracciata. Ora c'è un'unica chiamata protetta attorno all'intera scansione, con lo stesso comportamento di ripiego se qualcosa va storto a metà.",
    ["wn_354_perfpartylookup"] = "Interno — I riquadri di gruppo abbandonano una ricerca lineare del riquadro a favore di una tabella di ricerca diretta, e ora si disiscrivono completamente dagli eventi vita/risorsa/aura durante un'incursione — dove quei riquadri sono nascosti e i riquadri d'incursione gestiscono gli aggiornamenti — invece di continuare silenziosamente a elaborarli per niente.",
    ["wn_354_perfcdf"] = "Interno — L'evento di aggiornamento di Cooldown Forge poteva scattare più volte nello stesso frame durante una raffica di cambi di ricarica, ognuno dei quali ridisegnava da solo tutte le barre e le icone. Quelle raffiche sono ora raggruppate in un unico ridisegno per frame.",
    ["wn_354_perfmisc"] = "Interno — Alcune pulizie aggiuntive nei percorsi critici: il polling dei riquadri boss non costruisce più nuove stringhe a ogni tick, il passaggio di layout differito del tracciatore obiettivi e la sua scansione ricorsiva dei contenuti non allocano più tabelle usa e getta a ogni nodo, e i calcoli di velocità dello Skyriding non ricostruiscono più una closure a ogni tick.",
    ["wn_354_optionslod"] = "Modifica — Il pannello delle opzioni — Config, 28 file e circa 17.900 righe — ora si carica su richiesta anziché all'accesso. È stato spostato in un proprio componente aggiuntivo TomoMod_Options e si carica solo la prima volta che viene effettivamente aperto; ogni pulsante e comando slash che prima lo raggiungeva direttamente ora lo carica in modo trasparente al primo utilizzo.",
    ["wn_354_optionsfallback"] = "Interno — I colori del punteggio Mitica+, prima letti una sola volta all'accesso da una tabella di tema che ora risiede nel componente aggiuntivo delle opzioni su richiesta (e quindi non esisteva ancora), vengono ora letti in modo pigro — si risolvono correttamente non appena il pannello delle opzioni è stato aperto una volta, invece di restare bloccati su un valore di ripiego vuoto per l'intera sessione.",
    ["wn_354_escapefix"] = "Correzione — Le finestre Riepilogo morte, Riepilogo run, Dettaglio incantesimo e Dettaglio bersaglio del Misuratore di danno potevano lasciare Esc incapace di chiudere il menu di gioco dopo essere state usate, perché chiuderle nel vecchio modo passava per una funzione le cui chiamate protette vengono rifiutate una volta contaminato il percorso. Tutte e quattro usano ora lo stesso gestore sicuro di chiusura con Esc di ogni altra finestra di TomoMod.",

    -- =====================
    -- 3.5.3 — Novità
    ["wn_353_brezvisual"] = "Miglioramento — L'HUD del Contatore Battle Rez ha ricevuto un rinnovamento visivo ispirato dai pattern di design di Tui. Il frame ora presenta uno sfondo multistrato professionale con effetti ombra interna, spaziatura migliorata e tipografia raffinata per una migliore leggibilità in combattimento.",
    ["wn_353_brezglow"] = "Nuovo — Un effetto bagliore opzionale si attiva ora quando le risurrezioni di combattimento sono disponibili, fornendo un miglior feedback visivo e rendendo il contatore più evidente a prima vista.",
    ["wn_353_brezcolors"] = "Modifica — La tavolozza dei colori del Contatore Battle Rez è stata aggiornata con i colori accento teal ispirati a Tui e un migliore contrasto tra gli stati attivo (verde) e cooldown (rosso) per un'indicazione di stato più chiara.",
    ["wn_353_brezlayers"] = "Interno — Il layout del frame del Contatore Battle Rez è stato rielaborato con un appropriato ordinamento dei layer: sfondo, ombra interna, texture dell'icona, sweep cooldown e overlay di testo. Migliore geometria e posizionamento di tutti gli elementi UI.",
    ["wn_353_preytracker"] = "Nuovo — Tracciatore di Preda: Una barra di progresso mobile che visualizza il progresso attivo della caccia Prey (esclusivo dell'espansione Midnight). Mostra il nome della caccia, il livello di difficoltà e la percentuale di progresso in tempo reale con un design visivo fluido che corrisponde al Contatore Battle Rez.",
    ["wn_353_preyconfig"] = "Nuovo — Il Tracciatore di Preda è disabilitato per impostazione predefinita (contenuto solo Midnight) e può essere abilitato in Configurazione → QOL → Combattimento → Tracciatore di Preda. Si nasconde automaticamente quando nessuna caccia Prey è attiva e mostra un'anteprima in modalità di posizionamento.",
    ["wn_353_preylayout"] = "Nuovo — Il Tracciatore di Preda è completamente integrato con il sistema mover di layout unificato di TomoMod. Trascinare per posizionarlo insieme ad altri elementi HUD usando `/tm layout`, con comportamento di blocco/sblocco sincronizzato e anteprime coerenti della modalità di posizionamento.",
    ["wn_353_preyapi"] = "Interno — Il Tracciatore di Preda legge le API C_QuestLog e C_UIWidgetManager per rilevare i quest Prey attivi e tracciare il progresso in tempo reale con una frequenza di aggiornamento di 1 secondo, fornendo informazioni di stato accurate durante le cacce.",
    ["wn_353_brezcrash"] = "Correzione — Il Contatore Battle Rez poteva non caricarsi affatto su alcune build del client: un metodo di cooldown non più esistente e una chiamata al livello del frame effettuata su una texture anziché su un frame mandavano entrambi in crash l'inizializzazione del modulo. Entrambi risolti, insieme a un effetto bagliore che andava in crash non appena doveva riapparire dopo essere stato nascosto una volta.",
    ["wn_353_preyevent"] = "Correzione — Il Tracciatore di Preda registrava un evento che non esiste su questo client, generando un errore all'inizializzazione. Risolto, e ogni registrazione di evento è ora protetta cosicché un evento mancante non possa più mandare in crash il modulo.",
    ["wn_353_preygui"] = "Nuovo — Il Tracciatore di Preda ha ora una vera sezione di impostazioni: Configurazione → QOL → Automazioni, con una casella di abilitazione e cursori per larghezza/dimensione carattere. In precedenza non c'era modo di attivarlo dal gioco.",
    ["wn_353_abmover"] = "Correzione — La voce \"Action Bars\" in `/tm layout` non faceva assolutamente nulla. Il codice delle barre azione portato da Tui viene eseguito in un ambiente sandbox che non si esponeva mai al resto di TomoMod, impedendo silenziosamente l'attivazione della modalità di posizionamento. Ora raggiunge correttamente le barre.",
    ["wn_353_abflash"] = "Correzione — Premere un pulsante azione rendeva la sua icona completamente bianca, e il primo tentativo di correzione, all'inizio di questa stessa versione, non ha funzionato. La texture coinvolta non è una forma ritagliata che avesse bisogno di un'altra modalità di fusione, è un quadrato bianco pieno — fonderla diversamente continuava a dipingerla sopra l'icona, e la modifica rendeva altre tre texture, che erano sempre state a posto, più chiare del dovuto. L'effetto alla pressione ora scurisce l'icona invece di coprirla, che è ciò che avrebbe sempre dovuto fare.",
    ["wn_353_abpressopt"] = "Nuovo — Puoi scegliere cosa fa un pulsante mentre lo tieni premuto. Config → Barre delle azioni → Generale offre l'impostazione «Effetto alla pressione» con tre scelte: il lampo di Blizzard, ora quello predefinito, lo scurimento di TomoMod, oppure niente. Ha effetto nel momento in cui lo selezioni, senza ricaricare.",
    ["wn_353_abposition"] = "Correzione — Una barra azione trascinata tornava alla posizione predefinita ad ogni `/reload`. La posizione salvata non veniva mai effettivamente scritta, e il percorso di ripristino non la rileggeva mai anche quando lo era. Entrambi risolti — le posizioni delle barre ora persistono correttamente.",
    ["wn_353_abcolor"] = "Modifica — La sovrapposizione della modalità spostamento per le barre azione e i pulsanti azione extra/abilità di zona ora usa il colore teal di TomoMod invece del blu originale di Tui, in linea con ogni altra sovrapposizione `/tm layout`.",
    ["wn_353_abextramover"] = "Correzione — I supporti del Pulsante Azione Extra e dell'Abilità di Zona avevano una propria sovrapposizione di spostamento separata mai collegata a `/tm layout` — sempre visibile sullo schermo ma impossibile da trascinare dallo strumento di layout unificato. Entrambi ora hanno una voce «Pulsante Extra» dedicata in `/tm layout`.",
    ["wn_353_brezicon"] = "Correzione — L'icona del Contatore Battle Rez veniva visualizzata come un quadrato nero pieno: il percorso della texture utilizzata non esiste su questo client. Ora mostra correttamente l'icona di Rinascita.",
    ["wn_353_nameplaterole"] = "Correzione — Le nameplate potevano generare una raffica di errori di taint durante la lettura del ruolo di gruppo di un'unità in contenuti ristretti, perché il ruolo può tornare come valore segreto che non può essere confrontato direttamente. Ora è protetto e trattato come sconosciuto invece di generare un errore.",
    ["wn_353_abmicrodefer"] = "Correzione — I pulsanti del micro menu potevano sparire per il resto della sessione. Quando devono essere rimessi al loro posto e c'è un combattimento in corso, lo spostamento aspetta la fine del combattimento — ma la parte che avrebbe dovuto risvegliarlo dopo non c'è mai stata, quindi aspettava all'infinito, in silenzio e senza nulla nel registro degli errori a segnalarlo. Ora viene eseguito nel momento in cui esci dal combattimento.",
    ["wn_353_abpaging"] = "Correzione — Quando la barra cambiava sotto di te — un veicolo, una barra di possessione, una postura, una pagina di volo libero — i pulsanti mantenevano l'aspetto della pagina che avevi appena lasciato, oppure non mostravano più nulla, e solo una ricostruzione completa o un /reload rimetteva le cose a posto. Il ridisegno che avrebbe dovuto seguire un cambio di pagina dipendeva da una funzione di Blizzard che sul client attuale non esiste più, quindi non è mai stato eseguito nemmeno una volta. Le barre ora si ridisegnano da sole quando cambiano pagina.",
    ["wn_353_aboverride"] = "Correzione — La barra sostitutiva non veniva proprio mai ascoltata. È la barra su cui ti mettono un veicolo, una cavalcatura da volo libero o la Forma di volo di un druido: poiché nulla avvisava le barre che era successo, continuavano a mostrare le azioni della pagina precedente. Ora viene sorvegliata come qualsiasi altro cambio di pagina: gli slot vengono riletti e i pulsanti ridisegnati.",
    ["wn_353_totembar"] = "Novità — Una barra dei totem. Mostra i totem che hai piazzato, nell'ordine di priorità proprio della tua classe, con il tempo residuo scritto su ogni icona e uno spazzamento che la percorre. Clic destro su un'icona per richiamare quel totem; la barra si toglie da sola dallo schermo quando non ne resta nessuno. Il riquadro dei totem del gioco viene messo da parte finché è attiva e restituito intatto nel momento in cui la disattivi.",
    ["wn_353_totemconfig"] = "Novità — La barra dei totem si attiva in Config → Barre delle azioni → Generale, nella sezione Totem, ed è efficace all'istante, senza ricaricare. È disattivata di default. Dimensione delle icone, spaziatura, bordo, zoom, direzione di crescita e l'aspetto del testo della durata e dello spazzamento sono tutti regolabili.",
    ["wn_353_totemlayout"] = "Novità — Posizionala da `/tm layout` come qualsiasi altro elemento dell'interfaccia. Lì resta visibile ed etichettata anche senza alcun totem piazzato, così puoi sistemarla prima ancora di lanciarne uno invece di dover piazzare un totem, correre allo strumento di disposizione e sperare che regga ancora.",
    ["wn_353_petstancelayout"] = "Novità — La barra del famiglio e quella delle posture si possono finalmente disporre. Erano state private di orientamento, numero di pulsanti e colonne dando per scontato che fosse il gioco a governarne la forma — e non è così: passano esattamente per lo stesso codice di disposizione delle otto barre principali, e lo hanno sempre fatto, sicché le impostazioni erano attive da sempre senza nulla a schermo che le raggiungesse. I tre controlli sono ora presenti per entrambe, con un tetto di dieci slot anziché dodici. Impostare la barra delle posture oltre il numero di forme della tua classe è innocuo: il valore viene limitato per te.",
    ["wn_353_loots17"] = "Novità — Le tabelle del bottino sono aggiornate alla stagione 17. La rotazione dei dungeon è cambiata del tutto, quindi ci sono tutti e otto i nuovi — Riposo dei Re, Tempio di Sethraliss, Vasche della Vita Rubino, La valle Accecante, Arena della Cicatrice del Vuoto, Tana di Nalorakk, Vicolo dell'omicidio e Altare delle Zanne — insieme ai due nuovi raid, Grotta Vincolata alle Maree e Abisso Velenoso, e alle restrizioni di classe di ogni oggetto che lasciano cadere. Le tabelle della stagione precedente vengono ritirate anziché tenute accanto: nulla in nessuna delle due rotazioni punta più a esse.",
    ["wn_353_mplusteleports"] = "Novità — Il tracker Mitica+ conosce i teletrasporti della nuova rotazione. I cinque dungeon della rotazione arrivano con le loro magie di teletrasporto, e Riposo dei Re e il Tempio di Sethraliss hanno finalmente il proprio — entrambi erano vuoti pur facendo parte della rotazione, così il tracker non aveva nulla da offrire né per l'uno né per l'altro.",
    ["wn_353_keysync"] = "Correzione — `/tmt keysync` finalmente fa qualcosa. La diagnostica di sincronizzazione delle chiavi era stata scritta, e la nota subito sopra nominava perfino il comando a cui doveva rispondere, ma nulla nel gestore portava lì — sicché l'unico strumento per distinguere una sincronizzazione che fallisce in silenzio da una che semplicemente non ha trovato nulla da abbinare era irraggiungibile dal gioco. Ora compare in `/tmt help` in tutte e sei le lingue.",
    ["wn_353_totemport"] = "Interno — La barra dei totem è un port e non una riscrittura: ripresa da Tui così com'era scritta, con ogni riga modificata contrassegnata, così che rimettersi in pari con l'originale più avanti significhi rigiocare una manciata di segni anziché rileggere l'intero file. I suoi tempi di recupero rifiutano di netto i valori segreti invece di indovinarli — è così che il resto del codice portato tratta già i contenuti a regime ristretto — e ogni scrittura sicura attende la fine del combattimento invece di essere tentata nel mezzo della mischia.",
    ["wn_353_abemptyslot"] = "Correzione — E con «nascondi slot vuoti» attivo, quegli stessi cambi lasciavano la barra vuota invece che obsoleta: i pulsanti c'erano ma erano invisibili, e togliendo la spunta all'opzione il problema spariva — ed è proprio questo che ha svelato la causa. Il ridisegno veniva eseguito un fotogramma troppo presto, mentre i pulsanti puntavano ancora agli slot della pagina lasciata, così ognuno di essi risultava vuoto e veniva sbiadito — senza che nulla tornasse a controllare dopo. Ora viene eseguito una seconda volta al fotogramma successivo, quando i pulsanti si sono aggiornati.",

    -- 3.5.2 — Novità
    -- =====================
    ["wn_352_icons"] = "Correzione — Le icone delle barre delle azioni tornavano nere. Il controllo che doveva individuare uno spazio vuoto si aspettava che l'icona arrivasse come percorso di file, che è come rispondeva il gioco un tempo e non risponde più da anni: ora restituisce un numero. Così ogni icona vera falliva un test scritto per intercettare quelle mancanti, veniva cancellata e lasciava un quadrato vuoto al posto della tua magia. Sia la via normale sia quella di riserva accettano ora entrambe le risposte.",
    ["wn_352_tint"] = "Correzione — Fuori portata, mana insufficiente e azione inutilizzabile smettevano di mostrarsi dopo un ricaricamento o un cambio di barra, e bastava passarci sopra col mouse per farli riapparire. TomoMod colorava l'icona esattamente nello stesso punto in cui la colora Blizzard, quindi quello dei due che veniva eseguito per ultimo decideva ciò che vedevi. La colorazione è ora uno strato di TomoMod posato sopra l'icona, che la ombreggia esattamente come prima senza che i due si sovrascrivano a vicenda — e quando non c'è nulla da segnalare, semplicemente non c'è.",
    ["wn_352_scope"] = "Correzione — Con le barre delle azioni disattivate, l'aspetto grafico continuava comunque ad applicarsi. Ripiega sulla ricerca dei pulsanti per nome, e quei nomi appartengono ai pulsanti di Blizzard, che TomoMod li abbia presi in carico o no — spegnere le barre lasciava dunque l'aspetto a ridipingere riquadri che non lo riguardavano. Ora verifica che le barre siano davvero in funzione prima di modificare qualsiasi cosa.",
    ["wn_352_move"] = "Interno — Le barre delle azioni hanno traslocato. Erano riposte insieme alle comodità d'uso perché è lì che l'aspetto grafico è nato, e hanno smesso di essere una comodità nel momento in cui la versione precedente ne ha fatto un sistema a sé, con un motore, cinque strati e pulsanti propri. Ora stanno con i riquadri dell'unità, del gruppo e dell'incursione, che è il loro posto, e vengono caricate come loro. Lungo il tragitto non è cambiato nulla in esse: le tre correzioni qui sopra le hanno accompagnate.",
    ["wn_352_tui"] = "Interno — Fondamenta, e per ora nulla di visibile. Una parte di ciò che è previsto per le barre esiste già in un altro addon, e riscriverla riga per riga per adattarla qui sarebbe lento e introdurrebbe errori che nell'originale non ci sono. Esiste dunque ora un sottile strato il cui unico compito è permettere a uno di quei file di funzionare qui senza toccarlo. Dove TomoMod possiede già una propria versione di qualcosa — l'ancoraggio, la modalità di spostamento — lo strato punta a quella invece di trascinarsi dietro una seconda copia, ed è per questo che quattro funzioni ne sostituiscono milleseicento righe. Nulla richiama ancora tutto ciò: viene messo in opera di proposito per conto suo, prima che qualcosa vi si appoggi.",
    ["wn_352_port"] = "Interno — E poi la cosa per cui quello strato era stato costruito. Il modulo delle barre d'azione dell'altro addon è ora qui per intero: quattordici file, poco più di ottomila righe, portati così come erano stati scritti anziché ribattuti per adattarli. Ogni punto in cui una riga ha dovuto cambiare è contrassegnato, cosicché quando l'originale andrà avanti, rimettersi in pari significherà rigiocare una manciata di contrassegni invece di rileggere tutto sperando di accorgersi di ciò che si è spostato. È caricato, è verificato ed è spento di proposito: posare qualcosa di questa mole e accenderlo nella stessa versione è il modo di ritrovarsi senza poter dire quale delle due ha rotto le tue barre.",
    ["wn_352_portlayers"] = "Interno — Che cosa c'è dentro, per il giorno in cui l'interruttore verrà girato. Prima i menù a comparsa: la versione scorsa ha consegnato i pulsanti propri di TomoMod e ha dovuto dire chiaramente che un portale del mago o una trappola del cacciatore non si sarebbero aperti su una barra che li usa, perché il gioco rifiuta la via ordinaria su un pulsante costruito da un addon e l'aggiramento sono qualche centinaio di righe che nessuno scrive due volte. Quelle righe sono arrivate con la conversione, insieme a una riprogettazione in tinta del menù del gioco stesso per i pulsanti rimasti di Blizzard. Il pulsante d'azione aggiuntivo e l'abilità di zona ottengono un posto tutto loro, da cui il gioco non può spostarli in sordina. I tempi di recupero, il bagliore e l'attenuazione di ciò che non puoi lanciare arrivano ciascuno come strato a sé. Nulla di tutto ciò è ancora attivo.",
    ["wn_352_switch"] = "Modifica — L'interruttore è girato: le barre delle azioni girano ora sul modulo convertito, e il sistema che le muoveva prima è stato rimosso anziché lasciato lì spento, perché due sistemi convinti ciascuno di possedere gli stessi pulsanti non sono uno stato che si consegna per vedere come va a finire. Gli ultimi tre pezzi sono arrivati con esso: l'aspetto grafico, che toglie a un pulsante l'illustrazione del gioco stesso e lo ridisegna da zero, fino al nome della macro e al numero di cariche; la dissolvenza di una barra finché non ci passi sopra il mouse, una barra alla volta, con la barra tenuta visibile mentre il tuo libro degli incantesimi è aperto; e le sovrapposizioni che vedi quando vai a spostare una barra. Anche Masque è ora supportato, se lo usi, e semplicemente assente in caso contrario.",
    ["wn_352_bindings"] = "Modifica — I tuoi tasti restano, e ci sono 106 cose in meno da assegnare. La versione precedente forniva un'assegnazione per ogni pulsante di ogni barra, così mettere i pulsanti propri di TomoMod su una barra imponeva di assegnarla una seconda volta nella finestra delle scorciatoie del gioco, sotto un'intestazione TomoMod, accanto all'assegnazione che avevi già. I nuovi pulsanti non lo chiedono: leggono ciò che hai assegnato ai comandi delle barre delle azioni del gioco stesso e se li prendono. Una barra che avevi configurato continua a funzionare senza che tu tocchi nulla, e un tasto già occupato da qualcos'altro resta esattamente dov'è.",
    ["wn_352_settings"] = "Modifica — La pagina delle opzioni delle barre delle azioni è tornata, e c'è una cosa da sapere prima di aggiornare. Quando le barre sono passate al nuovo sistema, prima in questa stessa versione, la pagina si era ridotta a un solo messaggio, perché ogni suo controllo scriveva in un sistema che non esisteva più. Ora è ricostruita su ciò che le barre leggono davvero: cinque schede — i pulsanti stessi, il testo scritto sopra, gli indicatori di fuori portata, di risorsa insufficiente e di ciò che non puoi lanciare, la dissolvenza di una barra finché non ci punti sopra, e una scheda per barra con quanti pulsanti porta e in che direzione cresce. La cosa da sapere: le tue vecchie impostazioni delle barre non vengono riportate. Il vecchio modo di salvarle e quello nuovo non chiamano niente allo stesso modo, e i pochi nomi che si somigliano non significano la stessa cosa, quindi trasferirle avrebbe voluto dire indovinare — e un'ipotesi sbagliata ti lascia una disposizione che non hai mai scelto e da cui non puoi risalire a nulla. Le vecchie impostazioni vengono cancellate una volta sola, al tuo primo accesso dopo l'aggiornamento, e le barre partono da valori predefiniti puliti, poi le sistemi come preferisci.",
    ["wn_352_chatcopy"] = "Nuovo — La copia del testo dalla chat è stata rifatta. La finestra che ottieni ora somiglia al resto della chat invece che a una semplice scatola grigia: il testo è già selezionato e scorso fino all'ultima riga appena si apre, puoi ridimensionarla, e tiene 500 righe dove prima si fermava a 128. C'è anche un pulsante di copia sulla finestra di chat stessa — sempre visibile, solo quando ci punti sopra, oppure per niente, come preferisci, in Skins, Finestra di chat. E la finestrella che ti propone di copiare l'indirizzo di un link ora si accorda con tutto il resto invece di essere la finestra di dialogo del gioco.",

    -- =====================
    -- 3.5.1 — Novità
    -- =====================
    ["wn_351_engine"] = "Interno — Le barre delle azioni venivano ridipinte per intero cinque volte al secondo, ogni pulsante, che fosse cambiato qualcosa o no. È la forma che assume un aspetto grafico quando cresce fino a diventare un insieme di funzioni senza che gli sia mai stato dato un posto in cui ricordare qualcosa. Ora esiste un unico pezzo a cui appartiene la domanda — in che stato si trova questo pulsante — ed è il gioco ad avvisarlo quando accade qualcosa, invece che sia lui a controllare a intervalli; e passa la notizia solo quando un valore è davvero cambiato. La portata è l'eccezione, perché il gioco non ha modo di annunciarla: quel controllo resta su un timer, e solo finché hai un bersaglio. Inoltre non dà mai per scontato che il pulsante sottostante sia di Blizzard, ed è esattamente ciò che ha reso possibile tutto il resto di questa versione.",
    ["wn_351_render"] = "Novità — Icone e recuperi si possono finalmente regolare. I numeri del recupero e la loro dimensione, il colore e l'opacità dello spazzamento, il bordo e il bagliore, il testo di cariche e accumuli con la sua dimensione, il nome della macro, l'attenuazione di un'azione che non puoi usare, e quanto viene ritagliata l'icona — fino a non ritagliarla affatto. Si aggiunge la scelta di chi disegna il recupero: Blizzard, che tiene il proprio spazzamento e si limita a ristilizzarlo, oppure TomoMod, che lo disegna. Blizzard resta l'impostazione predefinita e per ora la più sicura delle due; quella di TomoMod è ciò di cui hanno bisogno i nuovi pulsanti più sotto, ed è lì per potersi dimostrare valida prima che qualcosa vi faccia affidamento.",
    ["wn_351_glow"] = "Novità — Due bagliori sulle barre, e possono essere accesi insieme. Uno è il classico risalto di un proc; l'altro segue il suggerimento di rotazione che il gioco stesso propone. Ciascuno ha il proprio stile — Pixel, Autolancio, Pulsante, Proc o Blizzard — il proprio colore, e per la variante a pixel il numero di linee, il loro spessore e la velocità dell'animazione. Convivono invece di alternarsi, perché ognuno mantiene la propria presa sul pulsante. La corrispondenza avviene sull'incantesimo, quindi una macro che finisce per lanciare qualcosa si illumina esattamente come farebbe l'incantesimo da solo, e viene seguito anche un talento che rinomina un incantesimo. Il bagliore di rotazione è disattivato di base e richiede che la funzione esista sul tuo personaggio.",
    ["wn_351_hotkeys"] = "Novità — Il testo della scorciatoia sui pulsanti è ora tuo: mostrarlo o no, la dimensione, il colore, in quale angolo si posa, di quanto è spostato, se viene abbreviato e se compare del tutto su una casella vuota. Viene ricavato dall'assegnazione stessa anziché copiato dall'etichetta di Blizzard, e conta perché un pulsante costruito da TomoMod non ha alcuna etichetta da copiare — quella di Blizzard resta come ripiego, così un cambiamento inatteso in una patch futura significa un testo un po' peggiore e non nessun testo. Si aggiunge una modalità di assegnazione: la attivi, passi sopra un pulsante, premi un tasto. Clic destro o Esc ne cancella una. Non si apre in combattimento.",
    ["wn_351_special"] = "Novità — Cose che le barre sapevano e non ti hanno mai mostrato. Su una barra con aspetto applicato non riuscivi a vedere in quale postura eri, quale incantamento d'arma avevi equipaggiato, né quale abilità del famiglio fosse impostata sull'autolancio: l'aspetto rimuove i contrassegni di Blizzard e sbiadisce il suo risalto. Ora c'è un anello per l'azione attiva e per gli oggetti equipaggiati, ciascuno con il proprio colore e uno spessore comune, su un unico anello con un ordine di precedenza perché due stati non si accavallino mai in un groviglio. L'autolancio del famiglio ha il proprio scintillio, che convive con i due bagliori qui sopra. La barra del famiglio può nascondersi quando non hai un famiglio. Per le posture non c'è equivalente — non esiste modo di chiedere al gioco se una classe abbia forme, e i pulsanti di postura di Blizzard spariscono già da soli quando non c'è nulla da mostrare.",
    ["wn_351_ownbuttons"] = "Novità — TomoMod può ora costruire i propri pulsanti d'azione invece di prendere in prestito quelli di Blizzard. È disattivato ovunque, si accende una barra alla volta e si annulla togliendo la spunta e ricaricando. Tutto quanto sopra funziona su di essi senza modifiche. Leggi i limiti prima di attivarlo, perché sono reali: i menù a comparsa non si aprono su una barra convertita — portali del mago, trappole del cacciatore, fiale evocate. Le barre del veicolo e di sostituzione seguono ancora il cambio di pagina, ma il pulsante di uscita specifico e la sua grafica non vengono dietro. Il risalto di rotazione del gioco non vi viene disegnato; usa invece il bagliore di rotazione qui sopra. Le barre del famiglio e delle posture restano interamente sui pulsanti di Blizzard. È contrassegnato come sperimentale perché lo è.",
    ["wn_351_bindings"] = "Novità — I nuovi pulsanti arrivano con 106 assegnazioni già dichiarate, quindi compaiono nella finestra delle scorciatoie del gioco stesso, sotto un'intestazione TomoMod con una sezione per barra. Sono legati tramite un clic dedicato anziché un semplice clic sinistro, ed è questo a far sì che il lancio alla pressione del tasto si comporti correttamente — è un punto noto, e Bartender4 ha fatto lo stesso spostamento anni fa per la stessa ragione.",
    ["wn_351_keybound"] = "Novità — Le barre di TomoMod si uniscono alla modalità di assegnazione condivisa che usano Dominos, Bartender4 e Bagnon: un solo passaggio assegna le tue barre e le loro insieme, invece che ogni addon insista sulla propria. La libreria che se ne occupa è ora inclusa, quindi la modalità condivisa c'è che tu usi uno di quegli addon oppure no. Un dettaglio da mettere per iscritto per chi la aggiornerà la prossima volta: va presa da una versione impacchettata, mai dal suo mirror GitHub, che calcola la propria versione da un contrassegno che viene riempito solo dentro una copia di lavoro del codice — copiata altrove, fallisce non appena viene caricata.",
    ["wn_351_tabs"] = "Modifica — La pagina delle opzioni delle barre delle azioni ha ora cinque schede invece di due: Aspetto, Pulsanti, Bagliore, Scorciatoie e Barre. Finora ogni novità finiva in un'unica lunga colonna nella scheda dell'aspetto, e tre dei cinque strati di questa versione sarebbero andati lì anch'essi.",

    -- =====================
    -- 3.4.6 — Novità
    -- =====================

    ["wn_346_probe_secret"] = "Correzione — Le icone dei benefici nello Studio dei recuperi, a cui la 3.4.5 aveva appena insegnato a mantenere il conto alla rovescia in combattimento, generavano un errore alla prima icona che sorvegliava un beneficio. Al contrassegno invisibile agganciato a ogni icona veniva chiesto se fosse sullo schermo, dando per scontato che sia una domanda su un pezzo di interfaccia e non sul beneficio — e non lo è. Che un'icona d'aura sia sullo schermo è esattamente il fatto che il beneficio sia attivo, cioè proprio ciò che il gioco trattiene: il sì-o-no restituito era a sua volta trattenuto, e a fallire era il fatto di consultarlo. Proteggere la chiamata non poteva servire: la chiamata funzionava benissimo, e l'errore arrivava una riga dopo, nel guardare la risposta.",
    ["wn_346_probe_cooldown"] = "Modifica — La domanda viene quindi posta a qualcos'altro. Ogni icona ha già la propria spazzata, quella che il gioco muove direttamente, e quel pezzo appartiene a TomoMod e non al gioco: la spazzata compare finché il beneficio è attivo e sparisce quando finisce, e nulla impedisce all'addon di leggerla. Dà la stessa risposta, dal lato del confine in cui leggere è ancora permesso. Il contrassegno del gioco resta dietro come secondo parere, ora interrogato in sicurezza, e se nessuno dei due risponde l'icona semplicemente non contribuisce nulla per quel fotogramma e continua a muovere la spazzata — che è sempre stata la parte più grande del suo compito.",

    -- =====================
    -- 3.4.5 — Novità
    -- =====================

    ["wn_345_class_secret"] = "Correzione — Le barre della salute generavano un errore a ogni aggiornamento per qualsiasi giocatore la cui classe il gioco ora nasconde: 399 volte in una sola sessione nel rapporto che ha portato a questo. La patch 12.1 ha ampliato ciò che un addon non può leggere, e un valore nascosto non è semplicemente assente: c'è, e fallisce non appena ci si fa qualcosa — confrontarlo, cercare qualcosa con esso, unirlo a un testo o persino chiedere se è vero. Il controllo deve quindi venire prima; dopo non c'è nulla da recuperare. Sedici punti di TomoMod leggevano ciascuno la classe di un'unità e cercavano il colore allo stesso modo; ora passano tutti per un unico insieme di funzioni di supporto che chiede se un valore è leggibile prima di toccarlo. Ogni punto decide da sé cosa significhi una classe sconosciuta, perché la risposta giusta non è la stessa ovunque: il promemoria di classe presume che qualcuno possa aver bisogno del beneficio invece di saltarlo, la tinta da incantatore sulle targhette ostili viene lasciata perdere anziché indovinata, e l'elenco delle chiavi come TomoScore si disegnano semplicemente senza colore. La corona di capogruppo appartiene alla stessa famiglia — anche chi guida il gruppo può ora essere nascosto, e in quel caso la corona resta nascosta, perché mostrarla su un giocatore che forse non è il capo è peggio che non mostrarne alcuna.",
    ["wn_345_class_passthrough"] = "Nuovo — E poi i colori di classe sono tornati. Ripiegare su un colore di fazione quando la classe non è leggibile è corretto, ma in un dungeon riguarda proprio tutto il gruppo: i riquadri sarebbero stati del colore sbagliato in permanenza, non ogni tanto. Si scopre che il gioco continua a colorare un'unità per te anche quando non vuole dirti la classe: la classe entra in una delle funzioni del gioco stesso e il colore esce direttamente da un'altra, nella barra, senza che l'addon legga mai né l'una né l'altro. Le barre della salute dei riquadri unità, delle targhette, dei riquadri gruppo e incursione prendono per prima quella strada e mantengono i loro colori di classe. Funziona però solo dove il colore viene applicato così com'è — tutto ciò che deve scurirlo o miscelarlo deve leggerne i numeri, e lì il colore di fazione resta la risposta.",
    ["wn_345_nameplate_auras"] = "Correzione — Le targhette nemiche sparivano quando si ruotava la telecamera. Non le loro aure: l'intera targhetta. Leggere le aure di un'unità è un'altra delle cose che la patch 12.1 può ora rifiutare, e il rifiuto arrivava nel mezzo del disegno della targhetta: tutto ciò che veniva dopo — la barra della salute, il nome, la barra di lancio — semplicemente non accadeva, e la targhetta sembrava cancellata. Ruotare la telecamera lo innescava perché è ciò che porta in vista nuove targhette. Ogni lettura di aura su una targhetta è ora protetta singolarmente: un rifiuto costa a quella sola aura la sua icona o il suo conto alla rovescia, e nient'altro. Due delle protezioni scritte per l'occasione non proteggevano in realtà nulla, per un motivo che vale la pena conoscere se si scrive in Lua: una protezione messa attorno a una chiamata non copre un'altra chiamata che le si passa come argomento, perché l'argomento viene eseguito per primo. Una delle due circondava esattamente la chiamata che falliva.",
    ["wn_345_aura_probe"] = "Interno — Undici punti diversi di TomoMod leggono le aure di un'unità: le aure sui riquadri e sulle targhette, l'evidenziazione da dissolvere, la riga delle cure persistenti, l'icona del beneficio di gruppo, le icone difensive, il monitoraggio dei benefici di CooldownForge. Ognuno percorreva fino a quaranta posizioni di aura una per una, proteggendo ogni passo, per scoprire solo alla fine che il gioco non avrebbe risposto affatto. Ora chiedono una volta sola, e la risposta vale per il resto del fotogramma: quaranta riquadri di gruppo costano una domanda invece di milleseicento passi protetti. La domanda è posta deliberatamente per la via più permissiva di leggere un'aura, così un no significa che ogni altra via era già chiusa e che non viene tralasciato nulla di disegnabile. Ne è uscito un bug reale: CooldownForge svuotava il proprio elenco di benefici monitorati ogni volta che una rilettura veniva rifiutata, e da quel momento non monitorava più nulla finché il gioco non consentiva una lettura. Meglio dire chiaramente il limite: questo rende le cose meno costose, non più complete. Un'icona la cui lettura non ottiene nulla si spegne ancora, esattamente come prima.",
    ["wn_345_aura_engine"] = "Nuovo — Le aure mancavano per gran parte di uno scontro, e nulla lo segnalava: nessun errore, niente sulla targhetta o sul riquadro, solo un vuoto dove avrebbe dovuto esserci ciò che volevi vedere. Tutto il resto di questa versione rende innocua una lettura di aura rifiutata; niente di ciò fa tornare l'aura, perché il gioco non la consegna mentre si combatte. Quindi TomoMod smette di chiedere. Ora descrive ciò che vuole — queste aure, in questa quantità, disposte così, con questo aspetto — e il gioco cerca e ordina da sé, restituendo le icone già pronte. Dalla parte di TomoMod nulla legge più un'aura, quindi non resta nulla da rifiutare. Ogni riga di aure dell'addon funziona così adesso: effetti negativi e positivi sulle targhette, aure e potenziamenti del bersaglio sui riquadri, icone di cura continuata del gruppo, effetti negativi e cure continuate dell'incursione. Le righe di cura continuata hanno richiesto un passaggio in più: si basavano sul riconoscere incantesimi precisi, e proprio l'incantesimo è ciò che viene nascosto — quindi l'elenco degli incantesimi da sorvegliare viene consegnato al gioco in anticipo, ed è lui a scegliere. L'indicatore di purificazione è stato il più lungo da risolvere, e cambia forma nel farlo. Era un bordo colorato attorno al riquadro di un giocatore, acceso confrontando ogni effetto nocivo con ciò che sai rimuovere — e poiché nessuna delle due cose è più consultabile, si accendeva solo fuori dal combattimento, l'esatto contrario di quando serve a un guaritore. Ora è una piccola icona nell'angolo del riquadro, ed è il gioco a scegliere quale effetto mostrare: gli si può chiedere direttamente se puoi purificare qualcosa, e risponde senza lasciar leggere nulla a nessuno. Due cose da sapere: i sanguinamenti non compaiono mai, perché nessuna abilità di classe li rimuove, e il controllo è escluso di proposito perché ha una propria visualizzazione. Strada facendo sono emersi quattro bug: un errore a ogni scomparsa di targhetta, icone create in pieno combattimento che uscivano senza dimensioni e restavano invisibili per sempre, gli interruttori per mostrare effetti negativi o cure continuate che non facevano più effetto fino a un ricaricamento, e un cursore di dimensione che non comandava più nulla.",
    ["wn_345_aura_layout"] = "Correzione — Le righe di aure non andavano più a capo e crescevano sempre nello stesso verso, qualunque cosa dicessero le impostazioni. Affidare la visualizzazione al gioco voleva dire indicargli la dimensione di un'icona, e questo non comprendeva né il verso della riga né il punto in cui deve ripiegare — entrambi appartengono alla riga stessa, e semplicemente non venivano mai trasmessi. I due versi funzionano di nuovo, orizzontale e verticale in modo indipendente, insieme alla spaziatura tra le icone. Nella stessa scia: una riga impostata su otto aure poteva disegnarne sedici quando mostrava insieme effetti positivi e negativi, trattandosi di due elenchi distinti e ricevendo ciascuno l'intera quota. Ora la quota è divisa. Il rovescio della medaglia è che una riga da otto non può più riempirsi interamente di effetti negativi quando non ci sono effetti positivi da mostrare — i due elenchi non possono prestarsi spazio.",
    ["wn_345_cdf_probe"] = "Nuovo — Le icone dei potenziamenti nel Cooldown Studio mantengono il conto alla rovescia in combattimento. Lo studio è l'unica visualizzazione che non si può affidare al gioco così com'è: mette tempi di recupero e potenziamenti nella stessa riga, nozione che il gioco non ha, e ciò che gli serve davvero è comunque più stretto — questo potenziamento è attivo, e quanto manca — cioè esattamente ciò che non gli è più consentito guardare. Chiede dunque senza lasciare che il gioco disegni: a ogni icona viene agganciato un contrassegno invisibile che sorveglia solo quel potenziamento, e il gioco muove direttamente lo scorrimento dell'icona. Se il potenziamento è attivo si risolve chiedendo a quel contrassegno se è sullo schermo, una domanda su un pezzo di interfaccia e non sul potenziamento. Una conseguenza da conoscere: una sola cosa per volta può scrivere lo scorrimento, perché due che si alternavano erano la causa dello sfarfallio.",
    ["wn_345_dm_dropdowns"] = "Correzione — Nella pagina delle opzioni del Misuratore di danni, i menù a tendina del tema e della trama delle barre si aprivano con il numero giusto di righe e nessun testo su nessuna. Il misuratore etichetta le sue liste in un modo e il menù a tendina di TomoMod ne attende un altro, e a differenza degli altri controlli questo non ha un valore di ripiego, quindi ogni riga veniva disegnata vuota. La pagina del Misuratore di danni ha inoltre ora un'icona propria nel menù: condivideva quella della Diagnostica, così due voci portavano la stessa immagine.",

    -- =====================
    -- 3.4.4 — Novità
    -- =====================

    ["wn_344_damagemeter"] = "Nuovo — TomoMod ha ora un misuratore di danni. DPS e HPS, danni subiti, danni evitabili, danni inflitti ai nemici, assorbimenti, interruzioni, dissipazioni e morti, suddivisi in Danni, Cure e Azioni che scorri dall'intestazione, con una sessione Corrente e una Globale e un cronometro di combattimento. Vale la pena sapere come funziona, perché spiega cosa può e cosa non può fare: legge i dati di combattimento di Blizzard invece di ascoltare il registro di combattimento e sommare tutto da sé. Questo significa nessun muro di eventi da filtrare e cifre identiche a quelle del misuratore di Blizzard, perché sono le stesse cifre. Un client privo di quei dati lo dice chiaramente invece di mostrarti una finestra vuota. Risponde a /tdm e può riportare in dire, gruppo, incursione, gilda, istanza, sussurro, il canale adatto al tuo gruppo, o solo a te stesso.",
    ["wn_344_dm_windows"] = "Nuovo — Fino a cinque finestre del misuratore insieme, ciascuna con il proprio tipo, la propria sessione, le proprie colonne e il proprio formato numerico: seguire danni e cure affiancati è il caso normale, e con una sola finestra si passava avanti e indietro per tutto lo scontro. Trascina una finestra contro un'altra e si agganciano bordo a bordo: da lì in poi si muovono insieme e condividono il bordo che le unisce, così ridimensionarne una ridimensiona anche l'altra, e allontanarne una la sgancia. Arrivano nove stili — Tomo Dark, Tomo Neon, Minimal, Glossy, Ember, Frost, Terminal, Void e Parchment — insieme alla trama delle barre, al carattere e alla sua dimensione, all'altezza delle barre, al colore d'accento o ai colori di classe, alla trasparenza dentro e fuori dal combattimento e a un'opzione per tenere sempre in vista la tua barra.",
    ["wn_344_dm_breakdowns"] = "Nuovo — Un numero su una barra non dice cosa l'ha prodotto. Clic sinistro su una barra per aprirne gli incantesimi lì sotto, clic destro per dare loro una finestra propria: totali, colpi, critici e percentuale di critico per incantesimo. Un dettaglio per bersaglio risponde all'altra metà della domanda — non cosa hai lanciato, ma su cosa — e ogni pull può essere letto per conto suo come segmento invece che solo come parte del totale corrente. Cliccando su un giocatore nell'elenco delle morti si apre un riepilogo di ciò che lo ha ucciso, che può anche aprirsi da solo quando muori tu; /tdm resetpos riporta quella finestra al centro se è finita in un punto scomodo.",
    ["wn_344_dm_runrecap"] = "Nuovo — Un riepilogo a fine dungeon: danni, cure, interruzioni, morti e danni evitabili subiti di tutto il gruppo, che si apre da solo alla fine della corsa o torna con /tdm recap. Si costruisce strada facendo invece di leggere tutto alla fine, e non è una preferenza: proprio quando una chiave finisce, il gioco non permette più a un addon di leggere quei valori, così un riepilogo scritto nel modo ovvio non riuscirebbe nemmeno a ordinare il gruppo. Al suo posto viene presa un'istantanea discreta ogni volta che esci dal combattimento, circa quindici volte in una chiave, a un costo che non noterai. Ciò che in quel momento è illeggibile viene lasciato com'è invece di essere sovrascritto, così l'ultima cifra valida di un giocatore non va mai persa.",
    ["wn_344_dm_standalone"] = "Nota — Il misuratore è pubblicato anche da solo come TomoDamageMeter. Se lo hai installato, la copia inclusa in TomoMod si fa da parte al caricamento e te lo dice una volta all'accesso, invece di lasciare due misuratori a contendersi le stesse finestre, impostazioni e sessioni di combattimento. A cedere è sempre la copia inclusa: installare l'addon autonomo è una scelta deliberata, e le versioni di quest'ultimo già in circolazione non hanno modo di sapere che dovrebbero farsi da parte loro.",
    ["wn_344_cds_window"] = "Correzione — Nel Cooldown Studio la colonna dei pulsanti delle barre a sinistra si disegnava sopra il pulsante della modalità modifica in fondo alla finestra, e le diciture uscivano dai pulsanti che le contenevano: «Import : Buffs suivis» era semplicemente più largo della casella in cui si trovava. La colonna aveva superato lo spazio riservato quando sono stati aggiunti i pulsanti di importazione, e nulla in questa interfaccia ritaglia un elemento che deborda: si disegna semplicemente sopra ciò che sta sotto. Lo spazio viene ora calcolato da ciò che deve contenere, i pulsanti sono abbastanza larghi per il proprio testo, e la finestra è più grande di conseguenza. Smette anche di chiedere più spazio di quanto il tuo schermo ne abbia: le era stato detto soltanto di restare sullo schermo, il che non serve a nulla per una finestra più grande del display — su uno schermo più piccolo l'intera colonna di sinistra poteva finire oltre il bordo. Ora si adatta allo spazio disponibile, ed è proprio questo a rendere sicuro ingrandirla. AstralForge si basa sulla stessa finestra e ne beneficia allo stesso modo. Nella pagina iniziale la scheda Cooldown Studio è inoltre risalita accanto a quella della Suite Tomo, dato che entrambe portano altrove.",
    ["wn_344_changelog_popup"] = "Correzione — La pagina Novità non riusciva a disporre le note che mostrava: aprendo una versione, i suoi paragrafi finivano uno sopra l'altro. Il motivo: un blocco di testo va misurato prima che la finestra abbia deciso la propria larghezza, così un paragrafo destinato a occupare sei righe veniva misurato come una sola, e tutto ciò che stava sotto veniva collocato nello spazio che quella singola riga avrebbe occupato. Invece di insegnare alla pagina a misurare il testo, ora passa la versione scelta proprio a questa finestra, che ha sempre saputo scorrere. La pagina stessa diventa un indice: ogni versione come pulsante con il numero di note che contiene, quattro per riga, dalla più recente alla più vecchia — cinquantanove in un'unica colonna significavano molto scorrimento per raggiungere qualcosa di vecchio. La accompagnano due cose minori. Leggere una vecchia versione non conta più come aver letto quella attuale: andare a vedere per curiosità cosa è cambiato nella 3.2.1 non si mangerà più l'avviso di un aggiornamento che non hai ancora visto. E la barra di scorrimento di questa finestra conservava le due frecce dorate di Blizzard alle due estremità di un binario per il resto verde; sono sparite, e la barra usa lo spazio che occupavano.",
    ["wn_344_dm_config"] = "Nuovo — Le impostazioni del misuratore sono ora una vera pagina Misuratore di danni nelle opzioni di TomoMod, e non più un pulsante che rimandava a un'altra finestra. Il tema, la trama delle barre, il carattere e la sua dimensione, l'altezza delle barre e l'accento con il colore della classe; l'opacità dello sfondo, fuori dal combattimento e sui pannelli di dettaglio; nascondere i reami, tenere in vista la propria barra, le descrizioni sulle barre, il timer di combattimento e da che lato sta, l'azzeramento entrando in un'istanza, l'aggancio delle finestre; i riepiloghi automatici di dungeon e di morte, e quante righe invia un rapporto. Sotto, questa pagina e la finestra propria del misuratore passano ora per un'unica descrizione di ciò che va aggiornato quando cambia un'impostazione — altrimenti ne esisterebbero due copie, che divergerebbero alla prima modifica di una delle due. Se un aggiornamento fallisce l'impostazione viene comunque salvata, invece di mostrare un errore e annullare in silenzio quello che hai appena cambiato. Colonne, aggiunta di finestre e filtro per categoria restano deliberatamente nella finestra del misuratore, dato che agiscono su una finestra precisa e non su tutto; la pagina lo dice e ti ci porta. Quella finestra, inoltre, si apriva dietro le opzioni anziché davanti, ed è corretto.",
    ["wn_344_aura_secret"] = "Correzione — Le aure dei riquadri unità producevano una valanga di errori nella patch 12.1 — 189 in una sola sessione nel rapporto che ha portato a questo. Prima il gioco si limitava a non restituire nulla quando un addon chiedeva le aure di un'unità in uno stato che non approvava; ora rifiuta la richiesta apertamente, e quel rifiuto non veniva intercettato, così scattava a ogni evento di aura. Ora viene intercettato, e il rifiuto ha una via d'uscita: le aure vengono lette una alla volta, più lentamente, ma è l'unica strada rimasta, e un'aura che compare ancora vale più di una che genera un errore. Il controllo dei benefici di CooldownForge aveva lo stesso problema dall'altro lato: l'aggiornamento delle aure inviato dal gioco può ora arrivare del tutto illeggibile, e il solo verificare se fosse un aggiornamento completo bastava a fallire, altre 38 volte in una sessione. Un aggiornamento illeggibile è ora trattato come completo e si rilegge semplicemente tutto, unico modo per restare aggiornati quando il dettaglio non è consultabile.",

    -- =====================
    -- 3.4.3 — Novità
    -- =====================
    ["wn_343_changelog"] = "Nuovo — Una pagina Novità nelle opzioni, con tutte le versioni che TomoMod ha pubblicato. Finora le note di versione comparivano solo nella finestra che segue un aggiornamento, e quella finestra mostra soltanto la versione a cui sei appena passato: una volta chiusa, il testo è perso. La nuova pagina elenca ogni versione, dalla più recente alla più vecchia, e cliccando su una si aprono le sue note. Legge esattamente le stesse note della finestra, quindi non esiste una seconda lista che possa rimanere indietro.",
    ["wn_343_cdf_resync"] = "Nuovo — Cooldown Studio: una barra creata dal gestore delle ricariche di Blizzard può ora essere riallineata con esso. Quelle barre erano corrette il giorno in cui le creavi e poi non avevano alcun modo di tornare indietro: una revisione della classe ti costringeva a confrontare le liste a mano. Risincronizza rilegge la categoria: le abilità che Blizzard ha aggiunto nel frattempo arrivano, quelle che ha tolto vengono tolte. Tutto ciò che hai fatto sulla barra sopravvive — un incantesimo ancora in elenco conserva la sua voce esattamente come l'avevi regolata, condizione di bagliore, visibilità per specializzazione ed effetti per voce compresi — e ciò che hai aggiunto tu non viene mai toccato né rimosso, qualunque cosa faccia la lista di Blizzard. Un incantesimo che avevi aggiunto a mano e che Blizzard inserisce in seguito nella categoria resta tuo invece di essere adottato, così una risincronizzazione successiva non potrà mai cancellare una voce che hai creato.",
    ["wn_343_cds_icons"] = "Cooldown Studio: l'elenco di ciò che una barra segue mostrava Sort 384100 — esatto e del tutto inutile. Ogni voce mostra ora la sua icona e il suo nome, con l'identificativo tra parentesi a seguire. Finché il client non ha in cache l'incantesimo continui a vedere solo il numero, che è la risposta onesta invece di una riga vuota.",
    ["wn_343_cds_scale"] = "Nuovo — Cooldown Studio: un cursore per la scala delle icone, in entrambe le disposizioni. Ingrandire una barra significava spostare un cursore di larghezza e poi portare quello di altezza esattamente allo stesso punto; ora è un solo controllo. È una vista sulla dimensione che avevi già e non una nuova impostazione, quindi sotto resta un unico numero e non c'è nulla da tenere allineato. Un pulsante riporta le icone quadrate mantenendo la dimensione che avevi davanti invece di tornare al valore predefinito. Non appena separi di proposito larghezza e altezza il cursore della scala si attenua — scalare di 1,2 non ha più una risposta univoca a quel punto — ed è quel pulsante a riportarlo.",
    ["wn_343_iconsize_range"] = "Correzione — Cooldown Studio: una dimensione delle icone inferiore a 24 o superiore a 64 sembrava accettata e non lo era. La barra veniva disegnata alla dimensione richiesta e la manteneva, finché un'azione successiva — una risincronizzazione, un'importazione, una duplicazione — non la riportava indietro in silenzio, senza nulla che collegasse quel cambiamento a qualcosa che avevi fatto. Nel frattempo le impostazioni separate di larghezza e altezza accettavano da 8 a 128, così la stessa icona piccola era raggiungibile da un controllo e rifiutata dall'altro. Ora c'è un solo intervallo, da 8 a 128, per tutti e tre. È più ampio di prima e non più stretto: nessuna barra che possiedi già cambia dimensione.",
    ["wn_343_studio_shortcut"] = "Nuovo — Un pulsante Cooldown Studio nella pagina iniziale, così aprire lo studio non richiede più di passare prima dal pannello CooldownForge.",

    -- =====================
    -- 3.4.2 — Novità
    -- =====================
    ["wn_342_astralforge"] = "Nuovo — AstralForge, un editor a schermo intero per gli elementi di un riquadro unità. Finora ogni parte di un riquadro stava dove TomoMod aveva deciso che stesse, e tutto ciò che ti veniva dato era un cursore che la spostava di qualche pixel da lì: portare il nome dall'altro lato non era un'impostazione, era un numero abbastanza grande da spingerlo fin là. Ora trascini ogni elemento dove vuoi: quale angolo dell'elemento si aggancia e a cosa si aggancia — il riquadro, la barra della salute, la barra della risorsa, la barra informazioni. Si allinea a una griglia sottile, si accosta agli altri elementi quando ci passi accanto, e tenendo Maiusc lo posi dove preferisci. I cursori restano per una correzione di due pixel, e i due scrivono la stessa cosa. Si apre dalle opzioni Riquadri unità e, come il Cooldown Studio, si carica solo quando lo chiedi. Ciò che trascini è una copia d'anteprima, mai un riquadro reale: quelli il gioco li protegge in combattimento, e modificarli direttamente è proprio ciò che causa i problemi di interfaccia che TomoMod ha passato due versioni a eliminare.",
    ["wn_342_af_nameplates"] = "Nuovo — Le targhette ricevono lo stesso editor, e per loro è terreno del tutto nuovo: a parte il simbolo d'incursione, nulla su una targhetta aveva un'impostazione di posizione. Il nome, il valore e la percentuale di salute, il livello, l'icona e il testo di classificazione, la barra di lancio con la sua icona, il suo nome, il suo cronometro e il suo scudo, e l'icona missione possono essere collocati ciascuno dove vuoi. La tua posizione del simbolo d'incursione viene mantenuta invariata, e tutto il resto parte esattamente da dov'era. Due cose non sono trascinabili di proposito: le aure, la cui posizione è calcolata dal loro posto nella fila anziché impostata, e le parti agganciate al riempimento di una barra — una maniglia su quelle direbbe di spostare qualcosa che non può spostare.",
    ["wn_342_af_props"] = "Nuovo — Opacità, scala e una forzatura della dimensione del testo, per singolo elemento. La forzatura parte da zero, cioè «lascia la dimensione calcolata dal modulo»: non cambia nulla finché non lo dici tu. Vengono mostrate solo le impostazioni che quel particolare elemento può davvero rispettare: l'opacità ha senso su un testo, la scala no, e una semplice immagine non accetta né l'una né l'altra — ottieni quindi quelle che si applicano a ciò che hai selezionato invece di una fila fissa di cursori metà dei quali non fa nulla.",
    ["wn_342_af_customtext"] = "Nuovo — Testo scritto da te. Aggiungi fino a sei testi personalizzati su un riquadro unità e quattro su una targhetta, scrivi qualcosa come «[name] - [level]» e collocalo come qualsiasi altro elemento. I segnaposto sono nome, livello, classe, razza e gilda su un riquadro, e nome, livello, classe, razza e classificazione su una targhetta. Vale la pena sapere perché non si tratta semplicemente del componente aggiuntivo che incolla parole: in Midnight il gioco fornisce nome e livello di un'unità in una forma che un componente aggiuntivo non ha il permesso di leggere, quindi anche un'operazione banale come unire un nome a un trattino fallirebbe. Il tuo modello viene trasformato in uno schema, i valori ci passano senza essere toccati ed è il gioco stesso ad assemblare il tutto.",
    ["wn_342_af_presets"] = "Nuovo — Preimpostazioni di disposizione e stringhe di condivisione. Salva con un nome l'intera disposizione di ciò che stai modificando — ogni posizione, ogni opacità e scala, ogni testo personalizzato —, riapplicala più tardi oppure passala a qualcuno come stringa da incollare. Tutto ciò che rientra viene controllato allo stesso modo, sia tuo sia di uno sconosciuto: i valori che il componente aggiuntivo non riconosce vengono scartati, un ancoraggio impossibile viene rifiutato prima di arrivare al gioco, e una disposizione che rimanda a se stessa in cerchio viene spezzata. Il peggio che una stringa incollata possa descrivere è una disposizione.",
    ["wn_342_af_migration"] = "I tuoi riquadri non si spostano. Ogni posizione che avevi impostato viene convertita nella nuova forma insieme all'ancoraggio su cui il motore la applicava, così un profilo convertito e uno nuovo di zecca disegnano esattamente lo stesso riquadro. Una vecchia impostazione viene scartata invece che convertita: uno scostamento delle aure che il motore ha smesso di leggere nella 3.0.5. Non ha effetto da diverse versioni, e convertirlo oggi sposterebbe aure che si trovano precisamente dove le hai messe. Anche i contenitori delle aure smettono di conservare la loro posizione in un secondo posto tutto loro: trascinarli in gioco, collocarli nell'editor e regolarli con i cursori ora scrivono nello stesso punto, quindi non possono più contraddirsi.",
    ["wn_342_af_secret"] = "Correzione — Aprire AstralForge su un'unità realmente presente poteva lasciarti una finestra vuota. L'anteprima che costruisce veniva alimentata con dati reali, e nel gioco attuale qualsiasi elemento dell'interfaccia il cui contenuto deriva da informazioni protette — un valore di salute, per esempio — nasconde agli addon anche la propria posizione e la propria dimensione. Misurarle è esattamente tutto il lavoro dell'editor: la primissima misurazione falliva e si portava dietro l'anteprima. Ora l'anteprima gira su dati inventati: un nome fittizio, un valore di salute fittizio, che nulla impedisce di misurare e che appaiono esattamente come ciò che stai disponendo. La accompagnano due protezioni: ciò che comunque non è misurabile resta semplicemente senza maniglia invece di bloccare tutto il resto, e se l'anteprima non può proprio essere costruita la finestra si apre lo stesso con l'elenco degli elementi, l'ispettore e i preset, anziché aprirsi vuota.",
    ["wn_342_keysync_realm"] ="Mitica+: l'elenco delle chiavi del gruppo era vuoto per chiunque fosse sul tuo stesso reame. La loro chiave veniva ricevuta e conservata da sempre — semplicemente non si riusciva più a ritrovarla. Quando il componente aggiuntivo di un'altra persona ti manda la sua chiave, il gioco la identifica come «Alice-Varimathras», che quel reame sia il tuo o no: ogni chiave viene quindi archiviata sotto un nome completo. Ma quando TomoMod chiede al gioco della persona che ti sta accanto sul tuo stesso reame, riceve «Alice» senza reame, e questo non corrisponde a nulla. È emerso con la nuova condivisione delle chiavi della 3.4.1, perché la libreria che ha sostituito nascondeva questa differenza nel proprio codice. Un nome senza reame viene ora ritentato con il tuo, così una chiave dello stesso reame si ritrova di nuovo — e succede una volta sola, dove le chiavi sono conservate, invece di essere qualcosa che ogni schermata che le legge deve ricordarsi di fare.",
    ["wn_342_escape_keys"] = "Correzione — Finché una delle finestre di TomoMod era aperta, i tasti non facevano più nulla: non potevi muoverti e le abilità non partivano. Ogni finestra che si chiude con Esc deve chiedere la tastiera al gioco, e una finestra che tiene la tastiera si tiene ogni tasto per sé a meno che non passi deliberatamente il resto — cosa che faceva solo di riflesso, ricevendo un tasto che non le interessava, e mai in combattimento, cioè proprio quando perdere i tasti costa di più. Ora ogni tasto passa direttamente; la finestra tiene solo Esc, e solo fuori dal combattimento. A questo si aggiunge l'altra metà del problema: una finestra tiene la tastiera solo mentre è davvero a schermo. Una chiusa con Esc manteneva la presa anche dopo, così il guaio sopravviveva alla finestra che lo aveva causato e la finestra successiva lo ereditava. Riguarda tutte le finestre dell'addon che si chiudono con Esc: le opzioni, l'installazione guidata, la finestra del bottino, l'hub Mitica+, TomoScore, l'assistente professioni, l'aspetto delle borse, la finestra di copia della chat e il Cooldown Studio.",
    ["wn_342_keysync_debug"] ="Nuovo — /tmt keysync. Stampa su quale canale viaggia la condivisione, se sei in gilda, tutte le chiavi che ha in memoria in quel momento e poi ogni membro del gruppo, indicando se la sua chiave viene effettivamente trovata. È quell'ultima riga il punto: una chiave salvata ma non trovata è un problema diverso da una chiave mai arrivata, e dall'elenco del gruppo le due sembrano identiche — ecco perché il problema qui sopra ha richiesto più tempo per essere individuato che per essere corretto. Il comando chiude chiedendo le chiavi al gruppo: rieseguirlo un secondo dopo ti dice se qualcuno ha risposto.",
    ["wn_342_cdf_viewer"] = "Nuovo — Cooldown Studio: crea una barra dal gestore dei tempi di recupero di Blizzard con un clic. Tre pulsanti — Essenziali, Utilità e Potenziamenti monitorati — creano una barra già pronta con le abilità che Blizzard seleziona per la specializzazione in cui ti trovi, nel suo stesso ordine, e i potenziamenti monitorati arrivano come potenziamenti e non come tempi di recupero: compaiono finché sono attivi e scalano quel che ne resta. L'elenco viene letto nel momento in cui fai clic e non viene mai salvato: Blizzard tiene aggiornate quelle tre categorie attraverso le revisioni delle classi, quindi una barra importata segue il gioco invece di congelare una copia che sarebbe giusta per una patch e silenziosamente sbagliata dalla successiva in poi. Dove un talento ha sostituito un'abilità con un'altra, è la sostituta a finire sulla barra, così l'icona corrisponde a quella del tuo libro degli incantesimi. È un punto di partenza, non un vincolo: quello che ottieni è una barra normale che puoi riordinare, sfoltire e ristilizzare. E se il tuo client non ha il gestore dei tempi di recupero, o Blizzard non seleziona nulla per la specializzazione in cui sei, lo studio te lo dice invece di darti una barra vuota.",

    -- =====================
    -- 3.4.1 — Novità
    -- =====================
    ["wn_341_style"] = "Tracker Mitica+: era l'ultima schermata di TomoMod con colori tutti suoi. La versione precedente ha allineato il tabellone di fine chiave e diceva che il tracker che vedi durante la chiave non si sarebbe accordato finché non avesse ricevuto lo stesso trattamento — eccolo. Ora usa lo stesso verde, lo stesso testo e gli stessi bordi di ogni altro pannello, su uno sfondo quasi nero con una sfumatura menta. Arriva insieme un'impostazione per la dimensione del carattere, da 0,70 a 1,60: ingrandisce il testo senza ingrandire il pannello.",
    ["wn_341_segments"] = "Tracker Mitica+: il cronometro è ora diviso in tre segmenti, uno per scrigno, e ciascuno conta il tempo che manca prima di perdere quello scrigno. Finora il pannello mostrava il tempo trascorso e lo scarto dal limite complessivo, e «quanto manca prima di perdere il +2» era un calcolo che facevi a mente tra un pull e l'altro. I segmenti sono dimensionati sui tempi di scrigno reali del dungeon, si leggono menta, giallo e rosso da sinistra a destra — la finestra in corso si annuncia quindi da sola con il colore — e un segmento consumato si attenua invece di sparire, così la barra resta la storia della chiave. Se preferisci leggere la barra dalla forma anziché dal colore, un'impostazione dipinge tutti e tre dello stesso verde.",
    ["wn_341_presets"] = "Tracker Mitica+: un pannello fisso è diventato tre aspetti. Pannello è quello che avevi già. HUD toglie lo sfondo e il blocco di intestazione ed elenca gli obiettivi come testo semplice, un po' più grande, con un carattere condensato. Minimo sono tre righe e nient'altro — informazioni, cronometro, mob — la lista dei boss sparisce e il suo conteggio sale nell'intestazione: sai ancora di essere a 2 su 4 senza spenderci quattro righe. Tutto ciò che un preset imposta è anche un interruttore a sé: sfondo, blocco di intestazione, nome del dungeon, lista dei boss, disposizione del cronometro, colori dei segmenti, dimensione del testo. Cambiane uno a mano e il preset dice «personalizzato» invece di far finta che tu sia ancora su di lui.",
    ["wn_341_forces"] = "Tracker Mitica+: la barra dei mob poteva mentire invece di ammettere che non vedeva nulla. Il gioco nasconde sempre più valori in combattimento, e la barra ci faceva comunque i conti sopra — un conteggio illeggibile usciva quindi come zero, e una barra che si svuota a metà pull non sembra un dato mancante, sembra un reset. Ora conserva l'ultima cifra letta davvero e ripiega per gradi: conteggi esatti, poi la sola percentuale, poi congelata. Mostra inoltre quanto resta da uccidere invece di 730 / 1000, e indica il momento in cui il conteggio è stato completato.",
    ["wn_341_bossnames"] = "Tracker Mitica+: i nomi dei boss venivano da una tabella scritta a mano che scade a ogni stagione. Blizzard aggiunge dungeon e riusa le voci del diario tra l'uno e l'altro, quindi un elenco del genere è sbagliato il giorno in cui esce la patch e niente ti avverte: i nomi semplicemente degradano in «Boss 1». Ora i nomi sono risolti dal vivo dal gioco, in tre modi e in ordine: la mappa su cui ti trovi, poi il nome del dungeon confrontato con il diario, poi il testo grezzo dell'obiettivo se nient'altro funziona. Ciò che trova viene ricordato per dungeon: è appreso e non scritto in anticipo, quindi non può scadere.",
    ["wn_341_splits"] = "Tracker Mitica+: non avevi nulla con cui confrontare una chiave. Ogni chiave completata viene ora registrata per dungeon e per livello, e al tentativo successivo ogni boss mostra quanto sei avanti o indietro rispetto al tuo migliore. I mob ricevono lo stesso trattamento: a ogni uccisione il tracker annota dove era arrivato il tuo miglior tentativo in quel momento e ti mostra lo scarto. Anche una chiave bruciata viene registrata — potrebbe essere il tuo unico riferimento per quel dungeon, e uno lento vale più di nessuno. Niente è precaricato: una tabella «mob attesi al boss 2» fornita da un addon sarebbe il percorso di qualcun altro e sarebbe sbagliata il giorno in cui il dungeon viene ribilanciato. Un pulsante nelle opzioni cancella quanto registrato.",
    ["wn_341_banner"] = "Tracker Mitica+: la fine di una chiave passava senza una parola. Ora c'è un banner — nei tempi o bruciata, il tempo del tentativo, i miglioramenti e il margine tra parentesi. Il margine è il numero che tutti dicono ad alta voce quando la chiave finisce, ed era l'unica cosa che dovevi ricostruire da solo partendo da un cronometro già fermo.",
    ["wn_341_options"] = "Tracker Mitica+: aveva una seconda finestra di opzioni tutta sua, con le stesse impostazioni della pagina Mitica+ nella configurazione di TomoMod — due posti per cambiare lo stesso valore, e divergevano. È sparita: /tmt apre ora la configurazione sulla pagina Mitica+. Tutti gli altri comandi /tmt restano invariati.",
    ["wn_341_legibility"] = "Tracker Mitica+: il testo scritto sopra una barra piena era illeggibile. Ogni etichetta disegnata dal tracker ha un contorno nero, e quel testo era a sua volta quasi nero: si scioglieva quindi nel proprio contorno — i segni degli scrigni sul cronometro e l'etichetta della barra dei mob erano macchie, mentre l'orologio bianco accanto restava nitido. Ora sono chiari. Due dettagli sono venuti con esso: una durata negativa poteva comparire come una grande positiva, -3:40 diventava 56:20, e il primo boss non ripete più il suo tempo di uccisione due volte sulla stessa riga.",
    ["wn_341_cds_taint"] = "Cooldown Studio: aprirlo poteva impedirti di disconnetterti, per due strade distinte. Una riga scriveva in una tabella che appartiene a Blizzard — senza cambiarne il valore, ma scriverci basta perché il gioco diffidi poi di ogni finestra costruita da quella tabella, conferma di uscita compresa. Separatamente, la finestra «copia lo stile da» gestiva Esc con una copia tutta sua di codice che esiste già altrove nell'addon, e quella copia era andata alla deriva: aveva perso il controllo sul combattimento e restituiva i tasti al gioco in un modo che impediva l'apertura del menu. Entrambe le cose sono risolte, e la finestra usa ora l'implementazione condivisa invece di tenerne una privata. Nessuna delle due toccava una sessione in cui non avessi aperto lo Studio, ed è per questo che ci è voluto tempo per attribuirle.",
    ["wn_341_keysync"] = "TomoMod si segnalava da solo come causa di problemi dell'interfaccia decine di volte a ogni combattimento, senza esserlo. La causa era una libreria inclusa, LibOpenRaid, che capisce se il gioco sta nascondendo un valore provando a leggerlo e intercettando l'errore — la risposta è giusta, ma il gioco scrive il nome di TomoMod nel proprio registro a ogni tentativo, e questo accade di continuo. La libreria non viene più distribuita. Era lì solo per quattro funzioni sulle pietre angolari, mentre sincronizzava anche tempi di recupero, equipaggiamento, talenti e durabilità — ed è proprio la parte dei tempi di recupero a causare tutto. La condivisione delle pietre angolari è ora di TomoMod, in un file molto più piccolo: la tua pietra arriva direttamente dal gioco, il resto viene scambiato con il gruppo e la gilda e conservato fino al reset settimanale. Una cosa dovrebbe funzionare per la prima volta: l'elenco delle pietre del gruppo si aggiorna da solo quando una cambia — il vecchio richiamo era collegato in un modo che la libreria non chiamava mai.",
    ["wn_341_buffskin"] = "L'aspetto di benefici e penalità è stato rimosso — l'intera funzione, con la sua scheda e le sue impostazioni. Sul gioco attuale non può funzionare: i pulsanti che Blizzard usa per le aure ora nascondono agli addon la propria dimensione, e mettere un bordo su uno di essi solleva un errore dentro il codice di Blizzard, non in quello di TomoMod, dove si sarebbe potuto intercettare. A questo si aggiunge che quei pulsanti vengono rifatti quasi a ogni patch: questa sola versione ci ha speso cinque tentativi. È manutenzione senza fine, proprio sulla parte dell'interfaccia in cui la visualizzazione di Blizzard è già adeguata. La tua finestra dei benefici torna a quella del gioco, e le impostazioni vengono cancellate dai profili perché non c'è dove riportarle. Se un aspetto personalizzato per i benefici ti sta davvero a cuore, un addon di aure dedicato è la risposta onesta.",
    ["wn_341_auratracker"] = "Il tracciatore di aure è stato rimosso. CooldownForge fa lo stesso lavoro e lo fa meglio, e tenere due sovrapposizioni che si contendono lo stesso angolo dello schermo non poteva finire altrimenti. La sua scheda, i suoi preset, il suo spostatore e le sue impostazioni se ne vanno con lui, e una pulizia una tantum toglie dai tuoi profili le impostazioni rimaste invece di portarsele dietro per sempre. Se ci avevi aggiunto incantesimi a mano, non vanno persi in silenzio: non possono essere convertiti automaticamente, quindi TomoMod li elenca una volta al prossimo accesso, con i loro nomi, e puoi ricreare quelli che ti interessano ancora nel Cooldown Studio.",
    ["wn_341_cds_reload"] = "Cooldown Studio: chiuderlo può ora ricaricare l'interfaccia, e lo fa in modo predefinito. Lo Studio si carica solo quando lo chiedi, ma il gioco non sa scaricare un addon — un ricaricamento è l'unica cosa che lo libera, ed è anche ciò che ripulisce quanto la sessione potrebbe aver raccolto per strada. La richiesta aspetta un momento sensato: mai in combattimento, mai durante una chiave, mai dentro un dungeon o un raid, e ritorna appena sei fuori. Puoi disattivarla nelle opzioni di CooldownForge. A parte questo, uscire dallo Studio con le barre sbloccate le lasciava bloccate in modalità modifica, con il pulsante di ripresa che galleggiava sullo schermo; ora entrambi i modi di chiudere la finestra fanno pulizia.",

    -- =====================
    -- 3.3.6 — Novità
    -- =====================
    ["wn_336_cdf_active"] = "CooldownForge: un buff attivo appariva esattamente come un incantesimo in ricarica. Da quando un'icona può seguire un buff invece di un tempo di recupero, entrambi gli stati arrivavano sullo schermo come la stessa immagine semplice, e l'unico modo per distinguerli era leggere il numero sopra. Due nuove impostazioni li separano: lo spazzamento del tempo di recupero e il bordo possono prendere ciascuno il colore della tua classe, o uno a tua scelta, mentre il buff seguito è attivo. Entrambe sono disattivate ovunque per impostazione predefinita, quindi nulla di ciò che hai già costruito cambia, e si applicano solo alle voci che seguono davvero un buff.",
    ["wn_336_cdf_threshold"] = "CooldownForge: il conto alla rovescia può cambiare colore quando un incantesimo sta per tornare. Imposta una soglia in secondi, fino a 60, e scegli il colore che assume al di sotto — leggere un colore in pieno combattimento è più rapido che decifrare un numero. Zero lo disattiva ed è il valore predefinito. Dove il gioco rifiuta di dire a un addon quanto manca, cioè nei contenuti soggetti a restrizioni, il timer mantiene il suo colore normale invece di tirare a indovinare: un conto alla rovescia che sbaglia sarebbe peggio di uno rimasto neutro.",
    ["wn_336_cdf_font"] = "CooldownForge: il testo sulle tue icone era bloccato su un solo carattere. L'impostazione esisteva in ogni barra fin dall'uscita della funzione e non l'aveva mai letta nessuno — il conto alla rovescia, gli accumuli, il nome dell'incantesimo e il timer speculare erano tutti fissati al Poppins di TomoMod. Ora puoi scegliere qualunque carattere condiviso dai tuoi altri addon, optare per un contorno sottile, spesso o assente, e dare al conto alla rovescia una dimensione propria indipendente dal testo di accumuli e nome, così cambiare carattere non impone più di rinunciare alle dimensioni del tuo preset. Entrambi i cursori di dimensione vanno ora da 8 a 28 pixel invece che da 9 a 20. Senza alcun addon di condivisione caratteri installato, l'elenco contiene solo Poppins e lo dichiara.",
    ["wn_336_cdf_glow_charges"] = "CooldownForge: il bagliore può attendere che tutte le cariche siano tornate. Un incantesimo a due o tre cariche era pronto o no dal punto di vista del bagliore, quindi una carica su tre si accendeva esattamente come tre su tre. La nuova condizione si ricava dalla ricarica stessa anziché da un conteggio — il gioco nasconde il numero attuale durante uno scontro, e contare è precisamente ciò che lì non si può fare. Un incantesimo senza cariche ricade sulla semplice disponibilità, perché la condizione non sia silenziosamente inutile sulla maggior parte delle tue voci.",
    ["wn_336_cdf_glow_stacks"] = "CooldownForge: il bagliore può attendere che un buff seguito raggiunga un certo numero di accumuli, impostabile per barra e ridefinibile per icona. Il gioco non dichiara un massimo per un buff, quindi il numero lo dai tu — da 2 a 20 su una barra, fino a 99 su una singola voce. Se il numero di accumuli non è leggibile, il bagliore resta spento invece di scattare su una supposizione, dato che un bagliore è qualcosa su cui si agisce.",
    ["wn_336_escape_taint"] = "Finestre: premere Esc poteva non aprire più affatto il menu di gioco, lasciandoti senza un modo normale di uscire. Otto finestre di TomoMod si chiudevano con Esc iscrivendosi a un elenco che Blizzard percorre dal codice del proprio menu, e quel codice esegue tre chiamate che il gioco rifiuta non appena qualcosa ha alterato la sessione — così il menu non si apriva mai ed Esc non faceva nulla. Quelle finestre ora gestiscono Esc da sole e non toccano più il menu di gioco. Tutti gli altri tasti continuano a passare. Una conseguenza da conoscere: su queste otto finestre Esc non chiude più durante un combattimento, perché la chiamata che lo consente è a sua volta limitata in combattimento. Il loro pulsante di chiusura funziona sempre.",
    ["wn_336_statusbar2"] = "Novità — Nascondi la barra di stato 2 di Blizzard, in QOL, Automazioni. La seconda barra di stato della modalità modifica si trova accanto a quella principale e non al suo interno, quindi l'opzione che nasconde le barre di stato di Blizzard non la raggiungeva mai e non esisteva alcuna impostazione che lo facesse. Viene resa invisibile e non cliccabile anziché eliminata, ed è proprio questo a evitare errori: la barra resta di Blizzard, quindi rimane nella sua modalità modifica e lì puoi ancora spostarla. Togliendo la spunta torna dopo un ricaricamento.",
    ["wn_336_ab_empty_refresh"] = "Barre delle azioni: con le caselle vuote nascoste, trascinare una magia su una di esse lasciava il pulsante vuoto. La magia c'era davvero e veniva lanciata al clic, ma non veniva disegnato nulla sopra fino al ricaricamento — e rilasciare su una barra svuotava le caselle vicine appena mostrate per il trascinamento. Nella versione precedente il modo di nascondere le caselle vuote è cambiato per non causare più errori sui pulsanti di Blizzard, e il nuovo metodo lasciava la barra ignara del fatto che una casella fosse stata riempita. Ora se ne accorge, anche quando un cambio di pagina o di postura modifica ciò a cui punta un pulsante.",
    ["wn_336_uf_aura_growth"] = "Riquadri unità: le aure crescevano solo verso il basso. L'impostazione della direzione copriva sinistra e destra, mentre la metà verticale della questione non aveva alcuna impostazione — così un riquadro posizionato in basso sullo schermo mandava la seconda fila di malus oltre il bordo inferiore, senza nulla da nessuna parte per impedirlo. Ora accanto a quella orizzontale c'è una direzione verticale nella scheda Aure di ogni unità, e le file possono impilarsi verso l'alto. Verso il basso resta il valore predefinito e nulla di quanto hai già configurato si sposta; nemmeno il riquadro si muove, è il blocco delle aure a crescere nell'altro senso.",
    ["wn_336_ts_palette"] = "Mythic+: il tabellone di fine corsa era l'unica schermata di TomoMod con colori propri — un accento ciano dove il resto dell'addon è verde, su uno sfondo tendente al blu dove il resto è neutro. Risaliva a prima della sua integrazione in TomoMod e non era mai stato allineato, quindi sembrava la finestra di un altro addon. Ora adotta lo stesso tema di tutto il resto. Due colori restano invariati di proposito: la barra « nei tempi » e il suo testo mantengono il loro verde, perché su un pannello già verde ovunque un indicatore « nei tempi » dello stesso verde smette di indicare qualcosa. Il tracker visibile durante la chiave per ora non è toccato, quindi i due non combaceranno finché non riceverà lo stesso trattamento.",
    ["wn_336_cdf_talent"] = "CooldownForge: un'icona può essere legata a un talento — mostrata solo se è preso, o solo se non lo è. La seconda metà è utile quanto la prima: una build che rinuncia a un talento di solito ne guadagna un altro al suo posto, e ora entrambe le icone possono stare nella stessa barra con solo quella pertinente a schermo. Indichi l'incantesimo che il talento concede e non un numero di nodo: i nodi vengono rinumerati a ogni revisione dei talenti, gli incantesimi no, quindi la condizione sopravvive a una patch. Ora segue anche i tuoi loadout — cambiare build si annuncia in modo diverso dal modificare i talenti, e solo uno dei due segnali veniva ascoltato, così una condizione poteva continuare a rispondere con la build precedente finché qualcos'altro non forzava un aggiornamento.",

    -- =====================
    -- 3.3.5 — Novità
    -- =====================
    ["wn_335_cdf_border"] = "CooldownForge: trascinare il cursore dello spessore del bordo faceva sparire il bordo invece di ispessirlo. Ogni impostazione di stile era memorizzata come un blocco unico, mentre l'editor ne scrive un campo alla volta — impostare lo spessore buttava via la modalità del bordo che stava accanto, e senza modalità l'icona veniva disegnata senza alcun bordo. Scegliere un colore faceva lo stesso, e scegliere una modalità riportava silenziosamente lo spessore a 1. Quelle impostazioni conservano ora i campi che non hai toccato. Nessuna barra cambia da sola; reimposta il valore e otterrai ciò che avevi chiesto la prima volta.",
    ["wn_335_cdf_border_paint"] = "CooldownForge: anche dopo che ha smesso di sparire, il bordo restava appena visibile e 1 pixel appariva identico a 4. Il contorno viene disegnato appena all'interno del margine dell'icona, e l'immagine dell'icona lo copriva per intero — il bordo veniva quindi dipinto e poi nascosto sotto, e ispessirlo non faceva che seppellirne di più. L'immagine ora si ferma prima del bordo e gli lascia spazio. Due conseguenze da aspettarsi: un'icona con bordo mostra la sua immagine leggermente più piccola, che è quanto costa un bordo, e uno spessore impostato quando il cursore sembrava non fare nulla diventa di colpo visibile — una barra rimasta su 4 apparirà quindi molto più pesante finché non la riporti a ciò che volevi davvero. Le icone senza bordo non cambiano.",
    ["wn_335_cdf_preset"] = "CooldownForge: toccare una qualsiasi impostazione fine trasformava silenziosamente la tua barra in una barra Tomo. Scegliere un colore del bordo su una barra Net o Verre ne portava lo stile su «Personalizzato», e Personalizzato non era uno stile vero — l'icona ricadeva quindi su Tomo e la base che avevi scelto spariva. Quale preimpostazione usa una barra e se ha impostazioni fini sono ora due cose distinte: cambiare preimpostazione conserva le tue impostazioni fini sopra la nuova, e modificare un'impostazione fine non tocca più la preimpostazione. Le barre già salvate come Personalizzato diventano Tomo mantenendo le loro impostazioni, che è come venivano già disegnate: sullo schermo non cambia nulla.",
    ["wn_335_cdf_thickness"] = "CooldownForge: il cursore dello spessore del bordo arriva a 10 invece che a 4. Quattro era un limite ragionevole finché il bordo era invisibile; ora che viene davvero disegnato non lo è più. Tieni presente che il bordo prende il suo spessore dall'immagine dell'icona: a 10, di un'icona piccola non resta quasi nulla.",
    ["wn_335_cdf_target"] = "CooldownForge: una barra può ora dipendere dal fatto che tu abbia un bersaglio, accanto alle condizioni già presenti di combattimento, spedizione, gruppo e incursione, e con le stesse tre scelte — indifferente, richiederlo, richiedere il contrario. Per la barra che vuoi vedere solo mentre sei effettivamente su qualcosa, o per la barra di utilità che deve togliersi di mezzo appena selezioni un bersaglio.",
    ["wn_335_cdf_dim"] = "CooldownForge: una barra la cui condizione di visibilità non è soddisfatta può ora attenuarsi invece di sparire. Scegli «ridurre l'opacità» al posto di «nascondere» e imposta quanto deve sbiadire, dal 5 % al 95 %. La barra attenuata resta viva — continua a seguire i tempi di recupero invece di congelarsi — quindi «in combattimento = sì» con questa opzione ti lascia fuori dal combattimento una barra leggibile a metà visibilità, anziché una che torna già superata. Nascondere resta l'impostazione predefinita e nulla cambia per le barre già configurate.",
    ["wn_335_cdf_iconwh"] = "CooldownForge: le icone non devono più essere quadrate. Larghezza e altezza hanno ora un cursore ciascuna, da 8 a 128 pixel, invece di un'unica dimensione per entrambe — icone larghe e piatte per una fila in cima allo schermo, alte e strette per una colonna accanto ai tuoi riquadri. Le barre già costruite non si spostano: i nuovi valori partono non impostati, e non impostato significa «mantenere la vecchia dimensione quadrata».",
    ["wn_335_cdf_aura"] = "CooldownForge: un'icona può seguire un buff invece di un tempo di recupero. Imposta una voce su «buff monitorato» e resterà fuori dallo schermo finché il buff è assente, per poi comparire con la durata residua e i cumuli finché è attivo — così un proc può stare sulla stessa barra accanto all'abilità che lo concede. Puoi anche indicare un ID di buff diverso, per i proc concessi da un incantesimo e applicati come un altro. In Mitica+ il gioco nasconde gran parte di ciò che un componente aggiuntivo può leggere di un buff; se ne parla a parte più sotto.",
    ["wn_335_cdf_secret"] = "CooldownForge: un buff monitorato spariva non appena iniziava un combattimento e tornava non appena finiva. Ogni ricerca passava per l'ID incantesimo del buff, e in Midnight il gioco nasconde quel numero durante il combattimento — misurato come pienamente leggibile fuori dal combattimento contro il 6,5 % al suo interno, con ogni buff monitorato che spariva nel fotogramma stesso in cui iniziava il pull. Il gioco però quell'ID lo fornisce una volta, nel momento in cui il buff viene applicato, insieme a un riferimento a quella specifica applicazione: TomoMod ora memorizza la coppia e da lì in poi interroga l'applicazione, cosa a cui il gioco continua a rispondere. Anche la durata residua e i cumuli sono tornati in Mitica+, letti nello stesso modo — la nota precedente secondo cui i buff monitorati lì funzionano ma senza timer non è più esatta.",
    ["wn_335_cdf_aura_sources"] = "CooldownForge: i benefici monitorati vengono ora trovati attraverso due strade invece di quattro. Ognuna era stata aggiunta per coprire un caso che la precedente si lasciava sfuggire, e nulla diceva quale stesse davvero facendo il lavoro — così sono state misurate su circa 12 700 ricerche ciascuna. Due reggevano l'intera funzione, e coprono metà opposte: una funziona durante uno scontro, l'altra fuori. Le due che non producevano quasi nulla sono state rimosse, e con esse una scansione di tutti i tuoi benefici che girava a ogni fotogramma e per ogni barra. Nel frattempo si chiude un'altra lacuna: un beneficio che guadagna soltanto un accumulo viene segnalato dal gioco come un aggiornamento e non come un nuovo beneficio, quindi un proc notato così in pieno combattimento non veniva mai registrato. Resta un limite del gioco, meglio conoscerlo che cercarlo: in combattimento nomina solo una parte delle aure. Un beneficio già attivo all'inizio dello scontro viene monitorato normalmente; uno applicato nel bel mezzo può non essere identificabile, e la sua icona resta nascosta. Non esiste alcuna impostazione per questo, e l'opzione del beneficio monitorato ora lo dice sul posto.",
    ["wn_335_cdf_viewer_source"] = "CooldownForge: un proc che scatta nel mezzo di un combattimento ora viene seguito anche lui — il limite descritto qui sopra viene in gran parte rimosso. Il gioco si rifiuta di dire a un addon di quale beneficio si tratti, ma lo sta disegnando sul tuo schermo da sempre: la visualizzazione dei benefici monitorati di Blizzard non è soggetta alle restrizioni a cui è soggetto un addon. TomoMod legge ora quella visualizzazione — se l'icona c'è, il tempo rimasto, il numero di accumuli — invece di porre una domanda a cui il gioco non risponde durante un combattimento. Nulla è scritto in modo fisso e nulla di protetto viene toccato: legge la stessa immagine che vedi tu. Copre solo i benefici che la visualizzazione dei benefici monitorati di Blizzard porta davvero: per tutto il resto i due metodi precedenti rispondono esattamente come prima, quindi questo aggiunge casi senza toglierne alcuno. Utile saperlo se usi il nuovo nascondimento barra per barra: nascondere una barra del Cooldown Manager non ti costa questa fonte, perché il nascondimento passa dalla trasparenza e la barra continua a funzionare sotto. Un dettaglio visivo da aspettarsi in combattimento: dove il gioco trattiene i numeri ma disegna comunque il conto alla rovescia, TomoMod ricopia quella cifra sulla tua icona — hai il tempo rimasto come numero, senza la spazzata dietro, e avanza a scatti invece che con continuità, perché la barra si aggiorna sugli eventi e non con un timer.",
    ["wn_335_cdf_aura_timer"] = "CooldownForge: un beneficio monitorato poteva comparire senza timer e senza spazzata anche quando il gioco aveva comunicato esattamente quanto gli restava. C'erano due modi per mettere un conto alla rovescia sull'icona, e veniva preferito quello sbagliato: quello che riceve un oggetto durata, che il gioco restituisce in una forma diversa da quella attesa dall'indicatore di recupero. Lo accettava, non disegnava nulla e non segnalava alcun errore — la rete di sicurezza pensata proprio per intercettare quel fallimento non scattava mai, e la via numerica, che avrebbe funzionato, non veniva mai raggiunta. Ora si usano prima i numeri leggibili, e l'oggetto soltanto quando il gioco si rifiuta di fornirli. Se i tuoi benefici monitorati apparivano come icone spoglie, ritrovano il loro timer e i loro accumuli.",
    ["wn_335_cdf_glow_aura"] = "CooldownForge: la condizione di bagliore «finché un beneficio è attivo su di te» si spegneva per tutta la durata di ogni scontro, e nessuno l'aveva collegata ai benefici monitorati. Chiedeva al gioco il tuo beneficio nello stesso modo in cui lo facevano in origine i benefici monitorati — il modo che smette di rispondere non appena inizia il combattimento — così il bagliore semplicemente si fermava, il che sembra un bagliore configurato male più che un difetto. Ora trova i benefici esattamente come fanno le icone dei benefici monitorati, così i due non possono più essere in disaccordo su ciò che stai portando.",
    ["wn_335_microbar"] = "Novità — Micro Barra: la piccola fila di pulsanti del menu di Blizzard diventa una barra tua. Scegli quali pulsanti compaiono e in quale ordine, in orizzontale o in verticale, quanti per riga, la loro dimensione, la spaziatura, la scala e l'opacità, e posizionala dove vuoi dal pannello Spostamenti. Può restare sempre sullo schermo, comparire al passaggio del mouse, oppure comparire al passaggio del mouse e restare visibile durante il combattimento. Le icone possono prendere il colore della tua classe, un colore a tua scelta o il loro aspetto originale, con desaturazione opzionale e uno zoom sotto il cursore. Ogni pulsante si limita a inoltrare il clic a quello di Blizzard: così tutto continua a funzionare in combattimento e nulla si rompe quando al gioco viene aggiunto un nuovo pannello. Anche gli originali continuano a funzionare al di sotto, così i loro avvisi, i loro stati disattivati e le loro scorciatoie possono essere riportati sui tuoi pulsanti — con quattro stili di bagliore d'avviso a scelta, l'attenuazione di ciò che non è disponibile e la scorciatoia disegnata sull'icona.",
    ["wn_335_cdf_aura_gate"] = "CooldownForge: un buff monitorato non deve più essere un incantesimo che puoi lanciare. Prima di mostrare qualsiasi icona la barra verifica che la voce ti riguardi, e per un incantesimo consultava il tuo libro degli incantesimi — corretto per un tempo di recupero, sbagliato per un buff. I buff da proc te li concede un talento o te li applica un altro incantesimo, quindi il libro degli incantesimi dice che non li hai, e la voce veniva scartata prima che qualcosa guardasse se il buff fosse davvero attivo. L'icona non compariva mai — che è gran parte di ciò a cui servono i buff monitorati. Un buff monitorato è ora giudicato sul buff.",
    ["wn_335_cdf_aura_link"] = "CooldownForge: seguire un proc non impone più di stanare l'ID del buff stesso. Un'abilità e il buff che concede non hanno quasi mai lo stesso ID, quindi inserire l'abilità — la cosa ovvia — sorvegliava un buff che nessuno ha mai, e l'icona restava semplicemente fuori dallo schermo. Una voce ora prova anche ciò che il gioco collega all'ID che hai inserito: il Cooldown Manager di Blizzard risolve già lo stesso problema per il suo visualizzatore dei buff monitorati, e TomoMod ne legge la stessa risposta. Nulla è scritto a mano nel codice, quindi segue da solo una patch che sposta un proc o un talento che lo sostituisce. Il campo opzionale dell'ID del buff funziona ancora e ha ancora la precedenza, per i casi che il gioco non collega.",
    ["wn_335_cds_reorder"] = "Cooldown Studio: le voci di una barra possono essere spostate in su e in giù. Riordinare le icone richiedeva di rimuovere una voce, riaggiungerla in fondo e rifare tutto quello che seguiva. Se il pannello delle opzioni è aperto sulla voce che sposti, la segue invece di restare sulla posizione — prima finiva per modificare quella che ne aveva preso il posto.",
    ["wn_335_mplus_teleport_override"] = "Mitica+: un teletrasporto di spedizione presente nel tuo libro degli incantesimi poteva comunque risultare non appreso — la riga in grigio, la descrizione che lo dava per non disponibile, il clic senza effetto. Quando una spedizione torna in una stagione successiva, Blizzard riemette il suo teletrasporto come un incantesimo diverso: quello di Skyreach viene ora lanciato come «Voie des cieux», e non l'incantesimo di Warlords che la tabella di TomoMod elenca. Il controllo chiedeva soltanto dell'incantesimo elencato, quindi possedere quello attuale era indistinguibile dal non possedere nulla. Ora chiede anche al gioco quale incantesimo sostituisce quello che conosce, e accetta l'uno o l'altro — per numero di incantesimo e non per nome, così funziona qualunque sia la lingua del tuo client e seguirà una futura stagione che riassegna un teletrasporto senza bisogno di un aggiornamento.",
    ["wn_335_ab_taint"] = "Barre delle azioni: l'opzione «mostrare gli spazi vuoti dei pulsanti» era all'origine di una raffica di errori di azione bloccata sui pulsanti della barra in basso a sinistra — errori che il gioco attribuiva al componente aggiuntivo che per caso stava girando in quel momento, il che ultimamente faceva sembrare che la colpa fosse di Cooldown Studio. Mostrare gli spazi vuoti avveniva scrivendo nello stato interno dei pulsanti di Blizzard e forzandone la comparsa, cosa che il gioco poi si rifiuta di toccare. L'opzione usa ora l'impostazione del gioco stesso «mostra sempre le barre delle azioni», e le barre che non devono mostrare i propri spazi vuoti vengono invece rese invisibili e non cliccabili. Blizzard mantiene il controllo dei suoi pulsanti. Due cose da sapere: quell'impostazione è globale, quindi si attiva non appena una sola delle tue barre vuole i suoi spazi vuoti, e se l'avevi attivata tu nelle opzioni di Blizzard verrà rimessa su disattivata appena nessuna barra di TomoMod ne ha bisogno. Trascinare un incantesimo su uno spazio vuoto funziona esattamente come prima.",
    ["wn_335_cdm_viewers"] = "Cooldowns: le quattro barre del Cooldown Manager di Blizzard si possono ora nascondere una per una, dal pannello Cooldowns accanto al pulsante del Cooldown Studio — Essential, Utility e le due visualizzazioni dei benefici monitorati hanno ciascuna la propria casella. Spuntarne una toglie quella barra dallo schermo e dalla modalità di posizionamento di TomoMod, e lascia le altre tre dove sono. Sostituisce un'unica casella che non nascondeva nulla: si limitava a interrompere la rivisitazione grafica di TomoMod su quelle barre, che restavano quindi sullo schermo con l'aspetto originale di Blizzard — una casella intitolata «nascondere le barre del Cooldown Manager» che le rendeva più evidenti anziché meno. Una barra nascosta viene resa invisibile e non cliccabile, non eliminata: resta la barra di Blizzard, continua a funzionare sotto, e se esista o meno lo decide ancora la modalità modifica di Blizzard. Togliendo la spunta torna esattamente dove l'avevi messa. L'interruttore in CD e Risorse non è cambiato e risponde a un'altra domanda — se TomoMod vesta queste barre, non quali vuoi vedere. Ora i due funzionano anche insieme: nascondere una barra continua a valere quando il modulo Cooldown Manager stesso è disattivato, l'unica combinazione in cui la casella veniva salvata e non applicata a nulla — ed è esattamente ciò che proverà chi vuole togliersi di mezzo queste barre.",
    ["wn_335_cdf_entry_spec"] = "CooldownForge: la specializzazione di una voce si poteva scegliere solo nel momento in cui la aggiungevi. Dopo, non c'era da nessuna parte modo di cambiarla — un'icona aggiunta sulla specializzazione sbagliata, o aggiunta prima che decidessi di limitarla a una sola, andava eliminata e riaggiunta, perdendo per giunta il suo posto nella barra. Il menu a tendina si trova ora sulla voce stessa, sia in Cooldown Studio sia nella pagina di impostazioni Cooldowns.",
    ["wn_335_scrollbar_click"] = "Impostazioni: la barra di scorrimento della finestra delle impostazioni ora si vede e si usa. Erano cinque pixel di grigio scuro su un pannello scuro — quasi impossibile da centrare, e già difficile da notare, per cui la rotellina era di fatto l'unico modo per scendere lungo una pagina lunga. Fare clic sulla guida sopra o sotto il cursore ora salta quasi una schermata in quella direzione, e il cursore si afferra senza doverlo prendere al pixel. Cambia anche l'aspetto, di proposito: un po' più larga, in un grigio più chiaro, con una sottile linea scura sul bordo interno perché si stacchi dal pannello dietro. Le caselle di testo che contengono le stringhe di importazione ed esportazione hanno la stessa barra, e ora combaciano. Vale per ogni pagina delle impostazioni, non per una sola.",
    ["wn_335_cds_tabjump"] = "Cooldown Studio: cambiare quasi qualsiasi cosa ti scaraventava su un'altra scheda. Modificare lo stile di un'icona ti lasciava su Condivisione, spuntare una condizione di visibilità ti lasciava su Disposizione. L'editor si ricostruisce dopo quasi ogni modifica e riapriva la scheda che aveva memorizzato — ma memorizzava una scheda solo la primissima volta che veniva costruita, quindi restava bloccato sull'ultima che avevi aperto per la prima volta, e tornare su una scheda già visitata non lo aggiornava mai. Ora segue la scheda su cui ti trovi davvero.",

    -- =====================
    -- 3.3.4 — Novità
    -- =====================
    ["wn_334_studio_reasons"] = "Cooldown Studio: il pulsante «Apri il Cooldown Studio» poteva non fare assolutamente nulla. Ogni possibile motivo per cui l'editor non riusciva a caricarsi veniva annunciato con lo stesso messaggio — «non installato» — compreso quello di gran lunga più frequente: è installato e semplicemente non spuntato nell'elenco dei componenti aggiuntivi. Ora ogni motivo dice qual è e cosa fare.",
    ["wn_334_studio_enable"] = "Cooldown Studio: se l'unico problema è che non è spuntato nell'elenco dei componenti aggiuntivi, un clic sul pulsante lo spunta e apre l'editor. Quando il gioco pretende prima un ricaricamento, lo dice invece di mandarti a cercare l'impostazione da solo.",
    ["wn_334_studio_preflight"] = "Cooldown Studio: la scheda nella linguetta Cooldowns ti avverte che l'editor non può aprirsi prima che tu faccia clic, non dopo. Il pulsante resta cliccabile di proposito: per un componente non spuntato, il clic è proprio ciò che risolve la situazione.",
    ["wn_334_studio_init"] = "Cooldown Studio: un editor che si caricava ma non riusciva ad avviarsi inghiottiva il tuo clic senza una parola. Ora dichiara di essersi caricato ma di non essere riuscito a inizializzarsi, e perché.",
    ["wn_334_studio_toc"] = "Cooldown Studio: il sotto-componente mostra ora l'icona di TomoMod, una categoria e il vero numero di versione del componente nel tuo elenco. Dichiarava ancora 1.0.0 e nessuna icona, il che lo faceva sembrare il componente di qualcun altro che per caso condivide il nome.",
    ["wn_334_package_builder"] = "Pacchettizzazione: il download è ora generato da uno script che si rifiuta di produrlo se il Cooldown Studio finisce dentro la cartella TomoMod invece che accanto. WoW guarda solo il primo livello della cartella AddOns, quindi uno Studio riposto un livello più in basso è uno Studio che nessuno vede nel proprio elenco — ed è esattamente la situazione che metà delle correzioni qui sopra serve a diagnosticare.",
    ["wn_334_diag_export"] = "Diagnostica: la finestra di esportazione ti chiedeva di copiare il rapporto e poi metteva l'indirizzo del tracker nel titolo — un indirizzo che potevi prendere solo buttando via il rapporto appena copiato. Ora alterna tra il rapporto e il collegamento, ti dice quale dei due è appena finito negli appunti e mostra l'indirizzo in chiaro sullo schermo, così puoi semplicemente leggerlo.",
    ["wn_334_diag_reminder"] = "Diagnostica: la finestra precisa ora che il rapporto è salvato e può essere riaperto in qualsiasi momento con /tmdiag tracker, quindi prendere prima il collegamento non ti costa nulla. Alla chiusura l'indirizzo viene inoltre stampato in chat, una volta per sessione, nel caso l'avessi chiusa troppo in fretta.",
    ["wn_334_presets_roles"] = "Preset: i preset Difensore, Guaritore e DPS scrivevano solo tre o quattro impostazioni ciascuno e prendevano tutto il resto dalla base comune — tre archetipi che erano la stessa configurazione sotto nomi diversi. Ora ognuno scrive una configurazione di ruolo completa su riquadri gruppo e incursione, targhette, auree del bersaglio, risorse, ricariche e barre di lancio: targhette larghe colorate per minaccia e minaccia numerica per i difensori, riquadri molto più grandi con HoT, dissolvenze e scudi per i guaritori, barre delle risorse più alte e solo i tuoi debuff per il danno.",
    ["wn_334_presets_reset"] = "Preset: passare da uno all'altro conservava le impostazioni del precedente. Un preset scriveva solo le proprie modifiche, quindi tutto ciò che non menzionava restava come l'aveva lasciato l'ultimo — passare da Difensore a Guaritore ti faceva curare con targhette in modalità difensore. La base comune contiene ora un valore per ogni impostazione che un preset può toccare e viene scritta per prima ogni volta: applicare un preset dà lo stesso risultato qualunque cosa ci fosse prima.",
    ["wn_334_presets_cards"] = "Pagina iniziale: i preset sono ora schede invece di quattro pulsanti colorati con sopra soltanto un nome. Ognuna mostra la sua icona di ruolo, la sua frase di sintesi e tre punti su ciò che cambia davvero, con la descrizione completa al passaggio del mouse — e quello attualmente in uso è contrassegnato come «Attivo», cosa che quel pannello non indicava da nessuna parte.",
    ["wn_334_role_badges"] = "Impostazioni: le sezioni utili a un ruolo preciso portano ora una piccola icona di difensore, guaritore o danno nella loro intestazione — HoT e dissolvenze, ricariche difensive, modalità difensore, monitoraggio delle interruzioni, testo della minaccia e altro. Passando il mouse sulle icone vengono nominati i ruoli.",
    ["wn_334_role_filter"] = "Impostazioni: è stata aggiunta una barra di focus del ruolo in cima alla barra laterale — Tutti, Difensore, Guaritore, DPS. Sceglierne uno mantiene in piena luce le impostazioni di quel ruolo e attenua le altre. Attenua invece di nascondere di proposito: un'opzione di cui conosci già la posizione resta esattamente dove l'hai lasciata, qualunque sia il focus attivo. La tua scelta viene conservata tra una sessione e l'altra.",
    ["wn_334_chat_history_settings"] = "Cronologia della chat: l'unica cosa che potevi farci era attivarla. Ora ha una sezione tutta sua — per quanto tempo i messaggi vengono conservati (da 1 ora a 3 giorni, o senza limite), quante righe vengono memorizzate (da 10 a 500) e un indicatore di sessione stampato dopo le righe ripristinate, così tutto ciò che segue proviene chiaramente dalla sessione corrente. Il limite di memorizzazione era inoltre sfasato di uno: dichiarava 128 righe e ne teneva 127.",
    ["wn_334_chat_history_delay"] = "Cronologia della chat: le righe ripristinate comparivano esattamente nel momento in cui i messaggi di caricamento degli addon e gli errori Lua arrivano in chat, seppellendoli sotto una pagina intera di riepilogo. La cronologia ora attende qualche secondo prima di comparire — regolabile, oppure zero per il comportamento di prima.",
    ["wn_334_chat_history_channels"] = "Cronologia della chat: quali canali vengono conservati — sussurri, gilda, ufficiale, gruppo, incursione, istanza, canali, dire, urlare, emote — era un'impostazione fin dall'introduzione della funzione e non compariva da nessuna parte nell'interfaccia. Ora è nel pannello. Un canale non spuntato non viene registrato affatto, non è soltanto escluso dal ripristino: rispuntarlo non recupera quanto è passato mentre era disattivato.",
    ["wn_334_chat_history_clear"] = "Cronologia della chat: c'è ora un pulsante per cancellare tutto il memorizzato, protetto da una conferma, e disattivare la funzione cancella anche ciò che è già salvato invece di lasciare ogni riga nelle variabili salvate. Il pannello lo dice prima che tu tolga la spunta — insieme al fatto che la cronologia è salvata per l'intero account ed è quindi condivisa da tutti i tuoi personaggi.",
    ["wn_334_roles_guides"] = "Ruoli: una nuova categoria Ruoli, con una pagina guida per difensore, guaritore e danno. Ognuna spiega ciò che conta davvero per quel ruolo, e ogni punto porta un pulsante che apre il pannello contenente l'impostazione e la evidenzia. La pagina applica anche il preset del ruolo e cambia il focus del ruolo nella barra laterale con un clic.",
    ["wn_334_search_nested_tabs"] = "Ricerca della configurazione: un risultato collocato in una scheda annidata — gli HoT dei riquadri incursione, i colori delle barre delle risorse, tutto ciò che un pannello mette dietro la propria seconda fila di schede — apriva la categoria giusta e poi finiva sulla sua prima scheda, non su quella cercata. L'indice memorizzava solo il nome della scheda più interna, che la barra esterna non poteva mai riconoscere. Ora registra un nome per livello, e ogni barra di schede legge il proprio.",
    ["wn_334_search_index_all_tabs"] = "Ricerca della configurazione: la maggior parte delle impostazioni non era affatto nell'indice. Le pagine che non hai mai aperto vengono costruite una volta, fuori schermo, perché la ricerca possa trovarle — ma un pannello costruisce solo la sua prima scheda, quindi tutto ciò che sta dietro una seconda o terza sottoscheda, cioè il grosso dell'interfaccia, non era rintracciabile cercandolo. Ora vengono percorse tutte le schede. È molto di più da costruire, perciò il lavoro avviene in secondo piano a spezzoni di pochi millisecondi anziché bloccare il gioco alla prima ricerca, e un elenco di risultati già a schermo si aggiorna da solo una volta finito.",
    ["wn_334_search_index_duplicates"] = "Ricerca della configurazione: i pannelli che riutilizzano una stessa pagina su più schede — ogni unità della barra di lancio, ogni riquadro unità — si riducevano a un solo risultato. L'indice conservava soltanto il nome della scheda più interna, così la barra del bersaglio e quella del focus scrivevano la stessa voce sulla stessa sezione, e ogni copia tranne la prima spariva. Le voci portano ora il percorso completo, e le sezioni di ciascuna unità sono elencate separatamente.",
    ["wn_334_roles_deeplink"] = "Ruoli: i pulsanti delle pagine guida aprivano la categoria giusta e poi ti lasciavano sulla scheda usata per ultima. Cercavano la propria impostazione nell'indice di ricerca, e proprio quelle impostazioni — HoT dei riquadri incursione, difensivi del gruppo, modalità difensore — erano quelle che all'indice mancavano. Ogni pulsante dichiara ora il proprio percorso, scheda per scheda: arriva sulla pagina giusta ed evidenzia la sezione, sia su un client appena avviato sia su qualunque cosa stessi guardando prima.",
    ["wn_334_cr_detection"] = "Promemoria classe: leggeva la barra delle posture per posizione. Felino era la casella 2, Orso la 1, Lunagufo la 4 — ma dove una forma si colloca su quella barra dipende dai talenti. Appena si spostava, il promemoria confrontava la tua forma reale con una casella che non c'entrava nulla: ti segnalava una forma mancante mentre ci stavi dentro, o taceva mentre ne eri fuori. Ora le forme sono riconosciute per incantesimo. I guerrieri riottengono le loro tre posture, una per specializzazione, invece di una voce che copriva tre caselle su ogni specializzazione. E le aure del paladino venivano cercate tra le forme, dove non sarebbero mai state trovate — sono buff, e come tali vengono controllate.",
    ["wn_334_cr_false"] = "Promemoria classe: alcuni avvisi non si potevano proprio spegnere. L'evocatore seguiva un solo buff Benedizione del Bronzo, e quell'incantesimo ne applica uno diverso a ciascuna classe — così a dodici classi su tredici veniva detto che mancava un buff che stavano portando, per tutto il tempo in cui il modulo era attivo. Lo stesso per le versioni con talento di Marchio del Selvaggio, Intelletto Arcano, Forma di Lunagufo e Forma d'Ombra: era nota solo la versione base, quindi chi giocava la variante riceveva avvisi per un buff che aveva già.",
    ["wn_334_cr_icons"] = "Promemoria classe: era una riga di testo pulsante al centro dello schermo che elencava ciò che mancava. Ora è una fila di icone, una per ogni buff, forma, postura o aura mancante, e fuori dal combattimento un clic sinistro lo lancia direttamente, invece di costringerti a leggerne il nome e andarlo a cercare su una barra. Il clic centrale scarta un promemoria fino al prossimo caricamento, per il buff che hai deciso di non prendere oggi. In combattimento nulla è cliccabile, di proposito: una fila che restasse armata mentirebbe su cosa fa premerla.",
    ["wn_334_cr_options"] = "Promemoria classe: dimensione delle icone, spaziatura, scala della fila, opacità, etichetta e relativa dimensione, e un bagliore con un colore proprio. I due cursori di posizione sono spariti — la fila si posiziona con lo spostatore, come tutto ciò che si sposta, e ha una voce propria nel pannello Spostamento. Se l'avevi spostata con i cursori, quella posizione viene ripresa una volta.",
    ["wn_334_cr_panel"] = "Promemoria classe: la pagina delle impostazioni si apre su un'anteprima viva della fila, disegnata dal modulo stesso, quindi ogni cursore muove esattamente ciò che stai guardando. Cliccare un'icona ti porta al suo interruttore, la sua etichetta alle opzioni etichetta, lo spazio attorno ai cursori delle dimensioni. E l'elenco delle classi supportate — un paragrafo di testo per classe — è ora una griglia, una casella per ogni buff o forma monitorati, colorata per classe, ognuna un interruttore che puoi spegnere per ciò su cui preferisci non ricevere promemoria.",
    ["wn_334_cr_enchants"] = "Promemoria classe: gli incantamenti d'arma non erano affatto monitorati. Linguafiamma, Furia del Vento, Terra Vivente, Guardia dell'Evocamaree ed Egida del Colpo di Tuono hanno ciascuno il proprio promemoria, e i due riti del Forgialuce ne condividono uno, dato che si escludono a vicenda e basta averne uno. Non sono aure: il gioco non li annunciava come annuncia un buff — ora spariscono nel momento in cui ne applichi uno, invece di aspettare un aggiornamento che non c'entra nulla.",
    ["wn_334_cr_poisons"] = "Promemoria classe: i veleni del ladro, un promemoria per categoria anziché per veleno — letale e non letale. Ciò che conta è che gli slot siano pieni: si conta quanti veleni di quella categoria sono attivi rispetto a quanti puoi davvero applicarne, uno o due con Lame Temprate dai Draghi. Nessuna lista di build da tenere aggiornata, e nulla da riconfigurare quando cambi talenti.",
    ["wn_334_cr_shields"] = "Promemoria classe: gli scudi dello sciamano sono monitorati, e Orbita Elementale viene considerata invece che ignorata. Con il talento porti Scudo di Terra su di te e uno degli altri due, quindi vengono controllati entrambi; senza, basta un solo scudo. Il promemoria nomina la categoria e la sua icona punta allo scudo giusto per la tua specializzazione — acqua per Ristoro, fulmini altrimenti.",
    ["wn_334_cr_context"] = "Promemoria classe: ora scegli dove appare — ovunque, solo in spedizioni e incursioni, o solo in gruppo. È nascosto in città e nelle locande per impostazione predefinita, perché è proprio lì che stai per riapplicare tutto, e tace mentre sei morto, su un veicolo o in volo su una cavalcatura: situazioni in cui nulla della fila può essere premuto.",
    ["wn_334_cr_group"] = "Promemoria classe: può tenere d'occhio anche il gruppo. Attiva «avvisa anche quando a un membro del gruppo manca un buff» e un buff di gruppo che tu porti continua a far scattare il promemoria finché qualcuno a portata ne è privo — il caso che si è sempre lasciato sfuggire, perché averlo tu non dice nulla del resto del gruppo. Contano solo i membri a cui la statistica interessa, e solo fuori dal combattimento: le aure di un altro giocatore non sono leggibili durante uno scontro, e tirare a indovinare lascerebbe un promemoria a schermo per tutto il pull. Disattivato di default, perché sorvegliare le aure di tutti non è gratis.",
    ["wn_334_cr_perf"] = "Promemoria classe: riesaminava le tue aure e la barra delle posture una volta al secondo, all'infinito, che qualcosa fosse cambiato o no. Il gioco annuncia già un buff ottenuto, perso o scaduto, e la barra delle posture ha i propri eventi: quel sondaggio non serviva a nulla. Ora reagisce agli eventi, e nota anche un cambio di talenti o di libro degli incantesimi, cioè proprio il momento in cui l'insieme delle forme interessate cambia davvero.",
    ["wn_334_uf_preview_engine"] = "Riquadri unità: l'anteprima delle impostazioni era un mockup. Disegnava proprie barre finte partendo dagli stessi valori ma con codice proprio, e poteva quindi divergere da ciò che ottenevi in gioco — e divergeva. Ora è costruita dalle stesse funzioni che costruiscono i tuoi riquadri reali: texture delle barre, caratteri, bordi, barra informativa, scostamenti degli elementi, griglia delle aure, potenziamenti nemici e minaccia provengono tutti dal motore reale, e l'anteprima non può più discostarsene.",
    ["wn_334_uf_preview_live"] = "Riquadri unità: l'anteprima mostra le tue unità reali. Quando l'unità esiste — il tuo bersaglio, il tuo focus, il tuo famiglio — i riquadri vengono alimentati con dati reali e contrassegnati REALE; altrimenti ripiegano su valori simulati contrassegnati SIM. C'è anche un interruttore Adatta / 1:1 per controllare i riquadri alla loro vera dimensione in pixel invece che nella striscia ridotta.",
    ["wn_334_uf_texture_live"] = "Riquadri unità: cambiare la texture delle barre non faceva nulla fino al ricaricamento — veniva letta solo alla creazione del riquadro. Lo stesso valeva per i numeri di durata sulle aure. Entrambi si applicano ora mentre li modifichi, sui tuoi riquadri reali e non solo nell'anteprima.",
    ["wn_334_tmkeys"] = "Mitica+: /tm keys apre il tabellone sul tuo gruppo reale — nome, classe, punteggio M+ e la chiave che ciascuno porta. Finora quel tabellone compariva solo da sé alla fine di una corsa, e l'unico comando che lo apriva a mano mostrava dati di esempio, non persone vere. Il momento in cui si decide quale chiave fare era proprio quello in cui non lo si poteva consultare. Funziona fuori dalla spedizione, cioè dove serve.",
    ["wn_334_score_roleicon"] = "Mitica+: ogni riga del tabellone mostra ora un'icona di ruolo accanto a quella della specializzazione, negli stessi colori dei preset di ruolo e dei distintivi nelle impostazioni. La specializzazione dice cosa ha portato una persona, il ruolo dice cosa ne sta facendo, e un elenco di chiavi che si legge prima del pull vuole entrambi.",
    ["wn_334_score_spec"] = "Mitica+: la tua stessa specializzazione mancava dalla tua riga del tabellone — il gioco non la restituisce con la stessa chiamata che usa per tutti gli altri. Ora viene letta direttamente. Anche i giocatori che condividono un ruolo uscivano in un ordine diverso a ogni apertura del tabellone fuori da una corsa, dato che il valore dei danni che di norma li separa lì è zero per tutti; a parità si passa ora al livello della chiave, poi al punteggio, poi al nome.",
    ["wn_334_mplus_teleports"] = "Mitica+: i teletrasporti per le spedizioni che avevi ottenuto venivano mostrati come non appresi. Il pannello e il tabellone sbiadivano la spedizione, il suggerimento diceva che il teletrasporto non era disponibile, e cliccando la riga compariva «non appreso» senza lanciare nulla. Il controllo utilizzato segnala solo gli incantesimi concessi dalla tua classe o dal tuo famiglio, mentre i teletrasporti per le spedizioni derivano dalle imprese — rispondeva quindi no per ognuno di essi, qualunque cosa ci fosse davvero nel tuo libro degli incantesimi. Segnalato per Cielo Squarciato, e riguardava l'intero elenco. Ora i teletrasporti funzionano dal pannello.",
    ["wn_334_delete_confirm"] = "Conferma di eliminazione: la funzione che digita per te la parola di conferma cercava ancora un pezzo di quella finestra che Blizzard ha rimosso nella 11.2, e funzionava solo grazie a un ripiego che indovina il nome interno della finestra. Ora chiede il campo di testo al gioco per la via supportata, con i vecchi percorsi alle spalle — continuerà quindi a riempire la casella qualunque cosa Blizzard faccia in seguito a quella finestra.",
    ["wn_334_friends_removed"] = "Contatti: lo skin della finestra dei contatti è stato rimosso, insieme alla sua linguetta nelle impostazioni. Blizzard ricostruisce quella finestra nella 12.1, e lo skin funzionava andando a prendere diverse decine dei suoi singoli pezzi per nome — nomi che quella ricostruzione è libera di spostare o rinominare. Non invecchia con dolcezza: il giorno della patch resta una finestra mezza spogliata, da te e non da noi. Lo skin era disattivato per impostazione predefinita; se lo avevi attivo, la finestra torna semplicemente all'aspetto originale di Blizzard. Il pulsante Contatti nella barra laterale della chat non è interessato.",

    -- =====================
